import { repairToolInvocation } from './self-healing-tools.js';

function clean(value = '', max = 2600) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, max);
}

function complexityScore(prompt = '', { hasProject = false, hasArtifacts = false } = {}) {
  const text = String(prompt || '');
  let score = 0;
  if (text.length > 320) score += 1;
  if (text.length > 900) score += 1;
  if (hasProject) score += 1;
  if (hasArtifacts && /\b(fix|repair|refactor|improve|polish|debug)\b/i.test(text)) score += 1;
  const complexTerms = text.toLowerCase().match(/\b(refactor|migration|migrate|architecture|implement|production|benchmark|optimi[sz]e|debug|investigate|multi-file|repo|repository|build|tests?|verify|compatibility|release|security|performance)\b/g) || [];
  if (complexTerms.length) score += 2;
  if (new Set(complexTerms).size >= 3) score += 1;
  if (/\b(and|then|also|plus|after that|while)\b/i.test(text) && text.length > 180) score += 1;
  return score;
}

function crewRoles(prompt = '', { hasProject = false, hasArtifacts = false, greed = false } = {}) {
  const roles = [];
  if (hasProject) roles.push({
    id: 'explorer', name: 'Explorer',
    instruction: 'Inspect the project yourself. Map the implementation surface, dependencies, and the smallest set of files/symbols the lead should touch.',
    tools: new Set(['get_info','list_directory','file_glob_search','read_file','read_many_files','grep_search','git_status','git_diff','code_intelligence']),
  });
  else roles.push({ id: 'strategist', name: 'Strategist', instruction: 'Identify the best execution approach and the few decisions that matter most.', tools: new Set() });

  if (hasArtifacts || /\b(ui|game|artifact|html|frontend|visual|design|render|browser)\b/i.test(prompt)) roles.push({
    id: 'quality', name: 'Quality',
    instruction: 'Inspect the active artifact when tools allow it. Find concrete visual/runtime/interaction failures and define crisp acceptance checks.',
    tools: new Set(['browser_get_state','browser_inspect','browser_console','browser_snapshot','read_artifact','read_file','grep_search','code_intelligence']),
  });
  else roles.push({
    id: 'verifier', name: 'Verifier',
    instruction: 'Inspect evidence and execute safe verification when useful. Identify likely failure modes and concrete checks.',
    tools: new Set(['get_info','read_file','read_many_files','grep_search','git_status','git_diff','verify_project','code_intelligence']),
  });

  if (!greed && /\b(architecture|security|performance|migration|release|production|refactor|debug)\b/i.test(prompt)) roles.push({
    id: 'critic', name: 'Critic',
    instruction: 'Challenge the current direction using project evidence. Surface one or two high-impact regressions, compatibility traps, or simpler alternatives.',
    tools: new Set(['get_info','read_file','read_many_files','grep_search','git_status','git_diff','code_intelligence','browser_console','browser_inspect']),
  });
  return roles.slice(0, greed ? 1 : 3);
}

function safeJson(value) {
  if (value && typeof value === 'object') return value;
  let text = String(value || '').trim();
  if (!text) return {};
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try { return JSON.parse(text); } catch {}
  const start = text.indexOf('{'); const end = text.lastIndexOf('}');
  if (start >= 0 && end > start) text = text.slice(start, end + 1);
  try { return JSON.parse(text.replace(/,\s*([}\]])/g, '$1').replace(/([{,]\s*)([A-Za-z_$][\w$-]*)(\s*:)/g, '$1"$2"$3')); } catch { return null; }
}

function mergeToolDelta(map, tc = {}) {
  const key = tc.index ?? Object.keys(map).length;
  if (!map[key]) map[key] = { id: tc.id || '', name: '', arguments: '' };
  if (tc.id) map[key].id = tc.id;
  const fn = tc.function || tc;
  if (fn.name) map[key].name += fn.name;
  if (fn.arguments) map[key].arguments += typeof fn.arguments === 'string' ? fn.arguments : JSON.stringify(fn.arguments);
}

function specialistToolDefinitions(role, definitions = []) {
  if (!role?.tools?.size) return [];
  return definitions.filter((tool) => role.tools.has(tool?.function?.name)).slice(0, 9);
}

function compactToolResult(result) {
  const text = typeof result === 'string' ? result : JSON.stringify(result ?? null);
  return text.length > 9000 ? `${text.slice(0, 9000)}\n…[trimmed]` : text;
}

export class AgentCrew {
  constructor(runtime) {
    this.runtime = runtime;
  }

  shouldActivate(prompt, { mode = 'work', crewMode = 'auto', hasProject = false, hasArtifacts = false, greed = false } = {}) {
    if (mode !== 'work' || crewMode === 'off') return false;
    if (crewMode === 'on') return true;
    if (greed && complexityScore(prompt, { hasProject, hasArtifacts }) < 6) return false;
    return complexityScore(prompt, { hasProject, hasArtifacts }) >= 3;
  }

  async runSpecialist({ role, prompt, projectContext = '', memoryContext = '', toolDefinitions = [], executeTool, greed = false, onEvent } = {}) {
    const tools = specialistToolDefinitions(role, toolDefinitions);
    const canTool = tools.length > 0 && typeof executeTool === 'function';
    const messages = [
      { role: 'system', content: `You are BlackRiver Crew · ${role.name}, an internal specialist working for a lead agent. ${role.instruction}\n${canTool ? 'You have a small, role-scoped toolset. Use it to inspect reality rather than guessing. Never mutate the primary project; your tools are intentionally inspection/verification scoped.' : 'Use only the supplied context and never pretend you inspected unavailable state.'}\nReturn a terse evidence-backed brief for the lead. No user-facing prose, no roleplay, no filler.` },
      { role: 'user', content: `Task:\n${clean(prompt, 5000)}${projectContext ? `\n\nProject map/context:\n${clean(projectContext, 6500)}` : ''}${memoryContext ? `\n\nRelevant memory:\n${clean(memoryContext, 2600)}` : ''}` },
    ];

    // Keep specialists deliberately small. They are an invisible preflight, not
    // a second full agent run competing with the lead for latency/context.
    const maxTurns = greed ? 2 : 4;
    const dynamicTools = !!this.runtime.capabilities?.dynamicTools;
    const specialistSessionId = `crew_${role.id}_${Date.now().toString(36)}_${Math.random().toString(16).slice(2, 7)}`;
    const executeSpecialistTool = async (name, rawArgs = {}) => {
      const healed = repairToolInvocation(name, rawArgs && typeof rawArgs === 'object' ? rawArgs : {}, tools);
      if (!healed.valid) return { error: healed.errors.join('; ') || 'Invalid specialist tool call.' };
      onEvent?.({ phase: 'crew-tool', status: 'running', role: role.name, name: healed.name, label: `${role.name} inspecting` });
      try { return await executeTool(healed.name, healed.args, { role: role.name, roleId: role.id }); }
      catch (error) { return { error: error?.message || String(error) }; }
    };
    let accumulated = '';
    for (let turn = 0; turn < maxTurns; turn += 1) {
      const toolMap = {};
      let content = '';
      await this.runtime.chat({
        messages,
        blackriver_session_id: specialistSessionId,
        blackriver_mode: 'work',
        blackriver_reasoning_profile: 'low',
        ...(canTool ? { tools, tool_choice: 'auto' } : {}),
        ...(canTool && dynamicTools ? { blackriver_tool_executor: executeSpecialistTool } : {}),
      }, (chunk) => {
        const delta = chunk?.choices?.[0]?.delta || {};
        if (delta.content) content += delta.content;
        for (const tc of delta.tool_calls || []) mergeToolDelta(toolMap, tc);
      });

      accumulated += content;
      const calls = Object.values(toolMap).filter((item) => item.name);
      // Codex-style dynamic tools execute inside the runtime and return the final
      // evidence-backed specialist text in this same call.
      if (dynamicTools || !calls.length || !canTool) break;
      messages.push({ role: 'assistant', content: content || null, tool_calls: calls.map((call, index) => ({ id: call.id || `crew_${role.id}_${turn}_${index}`, type: 'function', function: { name: call.name, arguments: call.arguments || '{}' } })) });
      for (let index = 0; index < calls.length; index += 1) {
        const call = calls[index];
        const parsed = safeJson(call.arguments);
        const callId = call.id || `crew_${role.id}_${turn}_${index}`;
        if (parsed === null) {
          messages.push({ role: 'tool', tool_call_id: callId, content: JSON.stringify({ error: 'Invalid specialist JSON arguments.' }) });
          continue;
        }
        const result = await executeSpecialistTool(call.name, parsed);
        messages.push({ role: 'tool', tool_call_id: callId, content: compactToolResult(result) });
      }
    }
    return clean(accumulated, 2400);
  }

  async runPreflight({ prompt, crewMode = 'auto', hasProject = false, hasArtifacts = false, greed = false, projectContext = '', memoryContext = '', toolDefinitions = [], executeTool = null, onSpawn = null, onEvent } = {}) {
    if (!this.shouldActivate(prompt, { mode: 'work', crewMode, hasProject, hasArtifacts, greed })) return [];
    const roles = crewRoles(prompt, { hasProject, hasArtifacts, greed });
    const briefs = [];
    for (const role of roles) {
      onEvent?.({ phase: 'crew', status: 'running', role: role.name, label: `${role.name} inspecting` });
      try {
        await onSpawn?.(role);
        const brief = await this.runSpecialist({ role, prompt, projectContext, memoryContext, toolDefinitions, executeTool, greed, onEvent });
        if (brief) briefs.push({ role: role.name, content: brief });
        onEvent?.({ phase: 'crew', status: 'done', role: role.name, label: `${role.name} ready` });
      } catch (error) {
        onEvent?.({ phase: 'crew', status: 'error', role: role.name, label: `${role.name} skipped`, error: error?.message || String(error) });
      }
    }
    return briefs;
  }

  formatBriefs(briefs = []) {
    if (!briefs.length) return '';
    return `BlackRiver Crew 2.0 specialist evidence (advisory; the lead agent owns final decisions):\n${briefs.map((item) => `\n[${item.role}]\n${item.content}`).join('\n')}`;
  }
}
