import { DEFAULT_RUNTIME, DEFAULT_SAMPLING } from '../config.js';

const DISABLED_MESSAGE = 'Wllama is not bundled in the Android build. BlackRiver Mobile uses native llama.cpp.';

function disabled() {
  throw new Error(DISABLED_MESSAGE);
}

// Build-time Android substitute for the browser Wllama runtime. PlatformLocalRuntime
// still keeps the same interface, but native Android always selects AndroidLlamaRuntime.
// Keeping this tiny inert class avoids shipping a second local inference engine/WASM
// inside the APK while preserving the Web/Desktop source architecture unchanged.
export class WllamaRuntime extends EventTarget {
  constructor() {
    super();
    this.loaded = null;
    this.reloadSpec = null;
    this.modelManager = null;
    this.runtimeParams = { ...DEFAULT_RUNTIME };
    this.sampling = { ...DEFAULT_SAMPLING };
    this.hardware = { checked: true, api: false, adapter: false, adapterInfo: null, error: null, androidStub: true, backend: 'disabled' };
  }

  get isLoaded() { return false; }
  get contextSize() { return Number(this.runtimeParams.n_ctx || 0); }
  get loadedContextInfo() { return null; }
  get supportsWebGPU() { return false; }
  get capabilities() {
    return { image: false, audio: false, chatTemplate: false, multithread: false, threads: 0, reasoning: false, nativeTools: false, androidLlama: false };
  }

  emit(type, detail = {}) { this.dispatchEvent(new CustomEvent(type, { detail })); }
  async probeWebGPU() { this.emit('hardware', this.hardware); return this.hardware; }
  async listCachedModels() { return []; }
  setRuntimeParams(patch = {}) { this.runtimeParams = { ...this.runtimeParams, ...patch }; }
  setSampling(patch = {}) { this.sampling = { ...this.sampling, ...patch }; }
  reasoningDescriptor(profile = 'auto') { return { profile, label: String(profile || 'auto'), hint: DISABLED_MESSAGE, resolved: profile, mode: 'disabled' }; }
  async reloadCurrent() { return disabled(); }
  async loadLocal() { return disabled(); }
  async loadFromUrls() { return disabled(); }
  async loadFromHF() { return disabled(); }
  async chat() { return disabled(); }
  stop() {}
  async unload() { return null; }
}
