import { DEFAULT_RUNTIME, DEFAULT_SAMPLING } from '../config.js';

const PROFILE_KEY = 'blackriver.workspace.android.modelProfile.v1';

function capPlugin() {
  return globalThis?.Capacitor?.Plugins?.BlackRiverLlama || null;
}

function safeMessage(error, fallback = 'Android llama.cpp runtime failed.') {
  return String(error?.message || error || fallback).trim() || fallback;
}

function loadProfile() {
  try {
    const value = JSON.parse(localStorage.getItem(PROFILE_KEY) || '{}');
    return value && typeof value === 'object' ? value : {};
  } catch { return {}; }
}

function saveProfile(value = {}) {
  try { localStorage.setItem(PROFILE_KEY, JSON.stringify(value)); } catch {}
}

function arrayBufferToBase64(buffer) {
  const bytes = buffer instanceof ArrayBuffer
    ? new Uint8Array(buffer)
    : ArrayBuffer.isView(buffer)
      ? new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength)
      : null;
  if (!bytes) return '';
  let binary = '';
  const step = 0x8000;
  for (let i = 0; i < bytes.length; i += step) binary += String.fromCharCode(...bytes.subarray(i, i + step));
  return btoa(binary);
}

function normalizeMessages(messages = []) {
  return messages.map((message) => {
    const role = ['system', 'user', 'assistant', 'tool'].includes(message?.role) ? message.role : 'user';
    let content = message?.content;
    const images = [];
    if (Array.isArray(content)) {
      const text = [];
      for (const part of content) {
        if (part?.type === 'text') text.push(String(part.text || ''));
        else if (part?.type === 'image' && part.data) {
          const encoded = arrayBufferToBase64(part.data);
          if (encoded) images.push(encoded);
        }
      }
      content = text.filter(Boolean).join('\n');
    }
    return { role, content: String(content || ''), ...(images.length ? { images } : {}) };
  }).filter((message) => message.content || message.images?.length);
}

export class AndroidLlamaRuntime extends EventTarget {
  constructor() {
    super();
    this.plugin = capPlugin();
    this.loaded = null;
    this.runtimeParams = { ...DEFAULT_RUNTIME, n_ctx: Math.min(Number(DEFAULT_RUNTIME.n_ctx || 8192), 8192) };
    this.sampling = { ...DEFAULT_SAMPLING };
    this.abortController = null;
    this.modelManager = null;
    this.reloadSpec = null;
    this.hardware = { checked: true, api: true, adapter: false, adapterInfo: null, error: null, android: true, backend: 'cpu' };
    this.nativeInfo = null;
    this.selectedProfile = loadProfile();
    this._loadStatusHandle = null;
    if (this.plugin?.addListener) {
      Promise.resolve(this.plugin.addListener('loadStatus', (detail) => {
        const state = detail?.state === 'staging' ? 'staging' : (detail?.state || 'loading');
        this.emit('status', { ...detail, state, androidNative: true });
      })).then((handle) => { this._loadStatusHandle = handle; }).catch(() => {});
    }
  }

  get available() { return !!this.plugin && globalThis?.Capacitor?.getPlatform?.() === 'android'; }
  get isLoaded() { return !!this.loaded; }
  get contextSize() { return Number(this.nativeInfo?.context || this.runtimeParams.n_ctx || 0); }
  get loadedContextInfo() {
    return this.loaded ? {
      n_ctx: this.contextSize,
      backend: this.nativeInfo?.backend || 'cpu',
      system: this.nativeInfo?.system || '',
      vision: !!this.nativeInfo?.vision,
      mmprojName: this.nativeInfo?.mmprojName || '',
    } : null;
  }
  get supportsWebGPU() { return false; }
  get capabilities() {
    return {
      image: !!(this.loaded && this.nativeInfo?.vision),
      audio: false,
      chatTemplate: true,
      multithread: true,
      threads: Number(this.nativeInfo?.threads || 1),
      reasoning: true,
      nativeTools: false,
      androidLlama: true,
    };
  }

  emit(type, detail = {}) { this.dispatchEvent(new CustomEvent(type, { detail })); }
  async probeWebGPU() { this.emit('hardware', this.hardware); return this.hardware; }
  async listCachedModels() { return []; }
  setRuntimeParams(patch = {}) { this.runtimeParams = { ...this.runtimeParams, ...patch }; }
  setSampling(patch = {}) { this.sampling = { ...this.sampling, ...patch }; }
  reasoningDescriptor(profile = 'auto') {
    return { profile, label: profile === 'auto' ? 'Auto' : String(profile || 'auto'), hint: 'llama.cpp Android · embedded model template', resolved: profile, mode: 'template-aware' };
  }

  async getDeviceInfo() {
    if (!this.available) throw new Error('BlackRiver llama.cpp Android bridge is unavailable.');
    const info = await this.plugin.getInfo();
    this.nativeInfo = { ...(this.nativeInfo || {}), ...(info || {}) };
    const gpu = !!info?.gpuAvailable;
    this.hardware = {
      checked: true, api: true, adapter: gpu, error: null, android: true,
      backend: String(info?.backend || 'cpu'),
      adapterInfo: gpu ? { vendor: info?.gpuVendor || '', architecture: info?.gpuName || '', device: info?.gpuName || '', description: info?.gpuName || '' } : null,
    };
    this.emit('hardware', this.hardware);
    return info;
  }

  getSelectedProfile() { return { ...(this.selectedProfile || {}) }; }

  clearProjector() {
    this.selectedProfile = { ...(this.selectedProfile || {}), mmprojUri: '', mmprojName: '' };
    saveProfile(this.selectedProfile);
    return this.getSelectedProfile();
  }

  async pickModelDocument() {
    if (!this.available) throw new Error('BlackRiver llama.cpp Android bridge is unavailable.');
    const picked = await this.plugin.pickModel();
    if (!picked?.uri) return null;
    this.selectedProfile = { ...(this.selectedProfile || {}), uri: picked.uri, name: picked.name || 'Android GGUF' };
    saveProfile(this.selectedProfile);
    return this.getSelectedProfile();
  }

  async pickProjectorDocument() {
    if (!this.available) throw new Error('BlackRiver llama.cpp Android bridge is unavailable.');
    const picked = await this.plugin.pickProjector();
    if (!picked?.uri) return null;
    this.selectedProfile = { ...(this.selectedProfile || {}), mmprojUri: picked.uri, mmprojName: picked.name || 'mmproj.gguf' };
    saveProfile(this.selectedProfile);
    return this.getSelectedProfile();
  }

  async pickModel({ backend = 'auto' } = {}) {
    const profile = await this.pickModelDocument();
    if (!profile?.uri) return null;
    return this.loadSelectedProfile({ backend });
  }

  async loadSelectedProfile({ backend = 'auto', context = this.runtimeParams.n_ctx, withProjector = true } = {}) {
    const profile = this.getSelectedProfile();
    if (!profile?.uri) throw new Error('Choose a GGUF model first.');
    return this.loadUri(profile.uri, {
      name: profile.name || 'Android GGUF',
      mmprojUri: withProjector ? (profile.mmprojUri || '') : '',
      mmprojName: withProjector ? (profile.mmprojName || '') : '',
      backend,
      context,
    });
  }

  async loadUri(uri, { name = 'Android GGUF', mmprojUri = '', mmprojName = '', backend = 'auto', context = this.runtimeParams.n_ctx } = {}) {
    if (!this.available) throw new Error('BlackRiver llama.cpp Android bridge is unavailable.');
    this.emit('status', { state: 'loading', message: `Loading ${name} with llama.cpp…` });
    try {
      const result = await this.plugin.loadModel({ uri, mmprojUri, backend, context: Number(context) || 8192, threads: 0 });
      this.nativeInfo = result || {};
      this.loaded = {
        name: result?.modelName || name,
        source: 'android-private',
        uri,
        mmprojUri,
        mmprojName: result?.mmprojName || mmprojName || '',
        backend: result?.backend || backend,
        vision: !!result?.vision,
        gpuFallback: !!result?.gpuFallback,
        storageMode: result?.storageMode || 'app-private-path',
        stagedFallback: !!result?.stagedFallback,
      };
      this.selectedProfile = { uri, name: this.loaded.name, mmprojUri, mmprojName: this.loaded.mmprojName };
      saveProfile(this.selectedProfile);
      this.reloadSpec = { ...this.selectedProfile, backend: result?.backend || backend };
      await this.getDeviceInfo().catch(() => {});
      const suffix = this.loaded.vision ? ' · vision ready' : this.loaded.gpuFallback ? ' · CPU fallback' : '';
      this.emit('status', { state: 'ready', message: `${this.loaded.name} loaded${suffix}`, loaded: this.loaded });
      return this.loaded;
    } catch (error) {
      this.emit('status', { state: 'error', message: safeMessage(error) });
      throw error;
    }
  }

  async reloadCurrent(overrides = {}) {
    if (!this.reloadSpec?.uri) throw new Error('No Android GGUF is available to reload.');
    return this.loadUri(this.reloadSpec.uri, {
      ...this.reloadSpec,
      context: overrides.n_ctx || this.runtimeParams.n_ctx,
      backend: overrides.backend || this.reloadSpec.backend || 'auto',
    });
  }

  async loadLocal() { return this.pickModel(); }
  async loadFromUrls() { throw new Error('Android local models use the native file picker. Download the GGUF first, then choose it from Models → Local.'); }
  async loadFromHF() { throw new Error('Direct Hugging Face loading is not enabled for the native Android runtime yet. Download the GGUF and optional mmproj to device storage, then choose them locally.'); }

  async chat(params = {}, onChunk) {
    if (!this.loaded || !this.available) throw new Error('Load an Android GGUF model first.');
    const messages = normalizeMessages(params.messages || []);
    if (messages.some((message) => message.images?.length) && !this.capabilities.image) {
      throw new Error('This Android model has no vision projector loaded. Open Models → Local and attach its matching mmproj GGUF.');
    }
    const callId = crypto.randomUUID?.() || `android_${Date.now()}_${Math.random().toString(16).slice(2)}`;
    this.abortController = new AbortController();
    let tokenHandle = null;
    let doneHandle = null;
    let errorHandle = null;
    let deliveredLength = 0;
    let deliveryChain = Promise.resolve();
    let settled = false;
    let resolveDone;
    let rejectDone;
    const done = new Promise((resolve, reject) => { resolveDone = resolve; rejectDone = reject; });

    const emitAt = (text, start = deliveredLength) => {
      let value = String(text || '');
      let offset = Number.isFinite(Number(start)) ? Number(start) : deliveredLength;
      if (!value) return;
      if (offset < deliveredLength) {
        const overlap = deliveredLength - offset;
        if (overlap >= value.length) return;
        value = value.slice(overlap);
        offset = deliveredLength;
      }
      if (offset > deliveredLength) return;
      deliveredLength += value.length;
      onChunk?.({ choices: [{ delta: { content: value }, finish_reason: null }] });
    };

    const reconcileSnapshot = async ({ settle = false } = {}) => {
      if (!this.plugin?.generationSnapshot) return null;
      const snapshot = await this.plugin.generationSnapshot({ callId, from: deliveredLength }).catch(() => null);
      if (!snapshot || snapshot?.missing) return snapshot;
      emitAt(String(snapshot.text || ''), Number(snapshot.start ?? deliveredLength));
      if (settle && snapshot.done && !settled) {
        settled = true;
        const message = String(snapshot.error || '').trim();
        if (message) rejectDone(new Error(message));
        else resolveDone(snapshot);
      }
      return snapshot;
    };

    const queue = (task) => {
      deliveryChain = deliveryChain.then(task).catch((error) => {
        if (!settled) { settled = true; rejectDone(error); }
      });
      return deliveryChain;
    };

    const onVisibilityChange = () => {
      if (document.visibilityState === 'visible' && !settled) queue(() => reconcileSnapshot({ settle: true }));
    };

    try {
      tokenHandle = await this.plugin.addListener('token', (event) => {
        if (event?.callId !== callId || settled) return;
        queue(async () => {
          const start = Number(event?.start ?? deliveredLength);
          if (start > deliveredLength) await reconcileSnapshot({ settle: false });
          emitAt(String(event?.text || ''), start);
        });
      });
      doneHandle = await this.plugin.addListener('generationDone', (event) => {
        if (event?.callId !== callId || settled) return;
        queue(async () => {
          const snapshot = await reconcileSnapshot({ settle: false });
          if (!settled) {
            settled = true;
            resolveDone(snapshot || event);
          }
        });
      });
      errorHandle = await this.plugin.addListener('generationError', (event) => {
        if (event?.callId !== callId || settled) return;
        queue(async () => {
          const snapshot = await reconcileSnapshot({ settle: false });
          if (!settled) {
            settled = true;
            rejectDone(new Error(snapshot?.error || event?.message || 'Android llama.cpp generation failed.'));
          }
        });
      });
      document.addEventListener?.('visibilitychange', onVisibilityChange);
      window.addEventListener?.('focus', onVisibilityChange);
      const sampling = { ...this.sampling, ...(params?.sampling || {}) };
      await this.plugin.chat({
        callId,
        messages,
        maxTokens: Number(sampling.max_tokens || sampling.max_completion_tokens || 1024),
        temperature: Number(sampling.temperature ?? 0.7),
        topP: Number(sampling.top_p ?? 0.95),
        topK: Number(sampling.top_k ?? 40),
        minP: Number(sampling.min_p ?? 0),
      });
      // Catch an extremely fast generation that can finish before bridge events
      // make it back to the renderer, and rehydrate any tokens retained while the
      // WebView was paused in the background.
      queue(() => reconcileSnapshot({ settle: true }));
      const end = await done;
      onChunk?.({ choices: [{ delta: {}, finish_reason: end?.reason || 'stop' }] });
      return end;
    } catch (error) {
      throw new Error(safeMessage(error));
    } finally {
      document.removeEventListener?.('visibilitychange', onVisibilityChange);
      window.removeEventListener?.('focus', onVisibilityChange);
      try { await tokenHandle?.remove?.(); } catch {}
      try { await doneHandle?.remove?.(); } catch {}
      try { await errorHandle?.remove?.(); } catch {}
      this.abortController = null;
    }
  }

  async stop() {
    try { await this.plugin?.stop?.(); } catch {}
    this.abortController?.abort?.();
  }

  async unload() {
    await this.stop();
    if (this.plugin) await this.plugin.unload();
    this.loaded = null;
    this.nativeInfo = null;
    this.emit('status', { state: 'idle', message: 'No model loaded' });
  }
}
