import { nativeAvailable, nativeCore } from '../native/native-bridge.js';

const BRIDGE = 'blackriver-artifact-preview-v1';
function uid() { return crypto.randomUUID?.() || `browser_${Date.now()}_${Math.random().toString(16).slice(2)}`; }
function sleep(ms) { return new Promise((resolve) => setTimeout(resolve, ms)); }

function dataUrlToBytes(value = '') {
  const match = String(value || '').match(/^data:([^;,]+);base64,(.+)$/i);
  if (!match) return null;
  const binary = atob(match[2]);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return { mime: match[1], data: bytes.buffer };
}

function artifactIdProperty() {
  return { artifact_id: { type: 'string', description: 'Optional HTML artifact id. Omit to use the newest HTML artifact in this conversation.' } };
}

export class BrowserLab extends EventTarget {
  constructor(artifacts) {
    super();
    this.artifacts = artifacts;
    this.pending = new Map();
    this.readyFrames = new Map();
    this.frameGetter = () => document.getElementById('artifactFrame');
    window.addEventListener('message', (event) => this.onMessage(event));
  }

  get definitions() {
    const artifact = artifactIdProperty();
    return [
      { type: 'function', function: { name: 'browser_get_state', description: 'Read the rendered state and viewport of a BlackRiver HTML Artifact without changing source.', parameters: { type: 'object', properties: { ...artifact } } } },
      { type: 'function', function: { name: 'browser_inspect', description: 'Inspect the rendered DOM of a BlackRiver HTML Artifact as a compact accessibility-oriented tree. Browser Lab never edits Artifact source.', parameters: { type: 'object', properties: { ...artifact, selector: { type: 'string' }, max_nodes: { type: 'number' } } } } },
      { type: 'function', function: { name: 'browser_click', description: 'Click an element in the rendered BlackRiver HTML Artifact by CSS selector or visible text.', parameters: { type: 'object', properties: { ...artifact, selector: { type: 'string' }, text: { type: 'string' } } } } },
      { type: 'function', function: { name: 'browser_pointer', description: 'Dispatch a real pointer-style interaction into an Artifact canvas/WebGL surface or selected element. Use this for canvas clicks, ripples, drawing, games, drag tests, and other interactions that browser_click cannot exercise.', parameters: { type: 'object', properties: { ...artifact, action: { type: 'string', enum: ['click','down','move','up'] }, selector: { type: 'string', description: 'Optional target selector. For a canvas benchmark, use canvas.' }, x: { type: 'number', description: 'Optional viewport client X coordinate. Defaults to the selected element center.' }, y: { type: 'number', description: 'Optional viewport client Y coordinate. Defaults to the selected element center.' }, button: { type: 'number', description: 'Mouse/pointer button, normally 0.' }, pointer_type: { type: 'string', enum: ['mouse','touch','pen'] } }, required: ['action'] } } },
      { type: 'function', function: { name: 'browser_type', description: 'Type into an input, textarea, select, or contenteditable element in the rendered BlackRiver HTML Artifact.', parameters: { type: 'object', properties: { ...artifact, selector: { type: 'string' }, text: { type: 'string' }, clear: { type: 'boolean' } }, required: ['selector', 'text'] } } },
      { type: 'function', function: { name: 'browser_key', description: 'Send a keyboard key to the focused element in the rendered BlackRiver HTML Artifact.', parameters: { type: 'object', properties: { ...artifact, key: { type: 'string' }, code: { type: 'string', description: 'Optional KeyboardEvent.code override such as KeyP, Space, ArrowLeft, or Enter.' }, selector: { type: 'string' } }, required: ['key'] } } },
      { type: 'function', function: { name: 'browser_scroll', description: 'Scroll the rendered BlackRiver HTML Artifact viewport or a selected element.', parameters: { type: 'object', properties: { ...artifact, x: { type: 'number' }, y: { type: 'number' }, selector: { type: 'string' } } } } },
      { type: 'function', function: { name: 'browser_wait', description: 'Wait briefly while the rendered Artifact runs, then return its state. Use for timing, animation, loading, game-loop, and delayed-behavior QA.', parameters: { type: 'object', properties: { ...artifact, milliseconds: { type: 'number', minimum: 50, maximum: 5000 } } } } },
      { type: 'function', function: { name: 'browser_console', description: 'Read recent console warnings/errors and uncaught runtime errors from the rendered BlackRiver HTML Artifact.', parameters: { type: 'object', properties: { ...artifact } } } },
      { type: 'function', function: { name: 'browser_snapshot', description: 'Capture the rendered BlackRiver HTML Artifact viewport for visual QA. Vision-capable models receive the screenshot as image context automatically.', parameters: { type: 'object', properties: { ...artifact } } } },
    ];
  }

  has(name) { return this.definitions.some((tool) => tool.function.name === name); }
  frame() { return this.frameGetter?.() || null; }

  resolveArtifact(args = {}, context = {}) {
    const requestedId = String(args?.artifact_id || '').trim();
    const conversationId = String(context?.conversationId || '').trim();
    let item = requestedId ? this.artifacts.get(requestedId) : null;
    if (!item && conversationId) item = this.artifacts.list(conversationId).find((candidate) => candidate.type === 'html') || null;
    if (!item) {
      const active = this.artifacts.get(this.artifacts.activeId || this.artifacts.lastTouchedId);
      if (active?.type === 'html' && (!conversationId || active.conversationId === conversationId)) item = active;
    }
    if (!item || item.type !== 'html') throw new Error('Browser Lab needs an HTML Artifact from this conversation. Use create_artifact/update_artifact for source changes.');
    if (conversationId && item.conversationId && item.conversationId !== conversationId) {
      throw new Error('Browser Lab refused a cross-conversation Artifact target. Use the Artifact from the active Work conversation.');
    }
    return item;
  }

  async visibleFrameFor(item) {
    // ArtifactStore is the source of truth. Rebind only when the visible frame is
    // missing, points at another artifact, or renders an older saved revision.
    // Re-opening an already-current frame would reset interactive state between
    // Browser Lab calls (click -> wait -> inspect), invalidating behavioral QA.
    let frame = this.frame();
    const matchesSavedRevision = () => {
      frame = this.frame();
      const revision = Number(frame?.dataset?.artifactUpdatedAt || 0);
      return !!(frame?.contentWindow
        && frame.dataset?.artifactId === item.id
        && revision === Number(item.updatedAt || 0));
    };
    if (!matchesSavedRevision()) this.artifacts.open(item.id);

    for (let i = 0; i < 40; i++) {
      const revision = Number(frame?.dataset?.artifactUpdatedAt || 0);
      const ready = this.readyFrames.get(item.id);
      if (matchesSavedRevision() && ready?.frame === frame && ready.updatedAt === revision) return frame;
      await sleep(70);
    }
    throw new Error('The requested Artifact is not available in the visible Browser Lab. Keep source changes in read_artifact/update_artifact; open this Work conversation/Artifact to run interactive QA.');
  }

  onMessage(event) {
    const data = event.data;
    if (!data || data.bridge !== BRIDGE) return;
    if (data.type === 'bootstrap-ready' && data.artifactId) {
      const frame = this.frame();
      const frameRevision = Number(frame?.dataset?.artifactUpdatedAt || 0);
      if (frame?.contentWindow === event.source
        && frame.dataset?.artifactId === data.artifactId
        && Number(data.artifactUpdatedAt || 0) === frameRevision) {
        this.readyFrames.set(data.artifactId, { frame, updatedAt: frameRevision });
      }
      return;
    }
    if (data.type !== 'browser-result' || !data.requestId) return;
    const pending = this.pending.get(data.requestId);
    if (!pending) return;
    if (event.source !== pending.frame?.contentWindow) return;
    if (data.artifactId !== pending.artifactId) return;
    if (Number(data.artifactUpdatedAt || 0) !== Number(pending.updatedAt || 0)) return;
    clearTimeout(pending.timer);
    this.pending.delete(data.requestId);
    if (data.error) pending.reject(new Error(String(data.error)));
    else pending.resolve({ artifact_id: pending.artifactId, artifact_updated_at: pending.updatedAt, ...(data.result || {}) });
  }

  commandOnFrame(item, frame, command, args = {}) {
    const requestId = uid();
    const browserArgs = { ...(args || {}) };
    delete browserArgs.artifact_id;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pending.delete(requestId);
        reject(new Error(`Browser Lab timed out while inspecting Artifact ${item.id}. The saved Artifact source was not modified.`));
      }, 5000);
      this.pending.set(requestId, { resolve, reject, timer, frame, artifactId: item.id, updatedAt: item.updatedAt });
      frame.contentWindow.postMessage({ bridge: BRIDGE, artifactId: item.id, artifactUpdatedAt: Number(item.updatedAt || 0), type: 'browser-command', requestId, command, args: browserArgs }, '*');
    });
  }

  async command(command, args = {}, context = {}) {
    const item = this.resolveArtifact(args, context);
    const frame = await this.visibleFrameFor(item);
    return this.commandOnFrame(item, frame, command, args);
  }

  async snapshot(args = {}, context = {}) {
    const item = this.resolveArtifact(args, context);
    const frame = await this.visibleFrameFor(item);
    const state = await this.commandOnFrame(item, frame, 'state', {});
    const rect = frame.getBoundingClientRect();

    // Desktop can capture the complete rendered iframe, including DOM overlays.
    if (nativeAvailable() && nativeCore()?.captureRegion && rect.width >= 16 && rect.height >= 16) {
      try {
        const scale = window.devicePixelRatio || 1;
        const capture = await nativeCore().captureRegion({ x: rect.left, y: rect.top, width: rect.width, height: rect.height, scaleFactor: scale });
        const decoded = dataUrlToBytes(capture?.dataUrl || '');
        if (decoded) return { ...state, screenshot: true, source: 'native-region', width: capture?.width || Math.round(rect.width), height: capture?.height || Math.round(rect.height), __blackriverVisionImage: decoded };
      } catch {}
    }

    // Web/Android fallback: ask the sandbox bridge to capture its largest visible
    // canvas. This makes Three.js/canvas benchmark QA visual on every platform
    // without granting the artifact same-origin access to Workspace.
    try {
      const capture = await this.commandOnFrame(item, frame, 'capture', { max_dimension: Math.max(320, Math.min(Number(args?.max_dimension) || 1024, 1536)) });
      const decoded = dataUrlToBytes(capture?.dataUrl || '');
      if (decoded) return { ...state, screenshot: true, source: capture.source || 'canvas', width: capture.width || 0, height: capture.height || 0, __blackriverVisionImage: decoded };
      return { ...state, screenshot: false, source: capture?.source || 'none', note: capture?.note || 'No capturable canvas was visible.' };
    } catch (error) {
      return { ...state, screenshot: false, note: error?.message || 'Visual capture was unavailable.' };
    }
  }

  async execute(name, args = {}, context = {}) {
    switch (name) {
      case 'browser_get_state': return this.command('state', args, context);
      case 'browser_inspect': return this.command('inspect', args, context);
      case 'browser_click': return this.command('click', args, context);
      case 'browser_pointer': return this.command('pointer', args, context);
      case 'browser_type': return this.command('type', args, context);
      case 'browser_key': return this.command('key', args, context);
      case 'browser_scroll': return this.command('scroll', args, context);
      case 'browser_wait': {
        const ms = Math.max(50, Math.min(Number(args?.milliseconds) || 500, 5000));
        const item = this.resolveArtifact(args, context);
        const frame = await this.visibleFrameFor(item);
        const expectedRevision = Number(item.updatedAt || 0);
        await sleep(ms);
        if (this.frame() !== frame
          || frame.dataset?.artifactId !== item.id
          || Number(frame.dataset?.artifactUpdatedAt || 0) !== expectedRevision) {
          throw new Error('Artifact changed or the Browser Lab frame was replaced during browser_wait. Repeat the timing check on the latest saved revision.');
        }
        return this.commandOnFrame(item, frame, 'state', args);
      }
      case 'browser_console': return this.command('console', args, context);
      case 'browser_snapshot': return this.snapshot(args, context);
      default: throw new Error(`Unknown Browser Lab tool: ${name}`);
    }
  }
}
