const COMMON_ALIASES = Object.freeze({
  file: 'path', file_path: 'path', filepath: 'path', filename: 'path', directory: 'path', dir: 'path',
  search: 'query', text: 'query', pattern_text: 'query', replacement: 'replace', replacement_text: 'replace',
  replaceAll: 'replace_all', timeout: 'timeout_ms', timeoutMs: 'timeout_ms', maxResults: 'max_results',
  maxChecks: 'max_checks', artifactId: 'artifact_id', conversationId: 'conversation_id', projectId: 'project_id',
  selector_css: 'selector', css: 'selector', value: 'text', href: 'url', address: 'url',
  artifactType: 'type', artifact_type: 'type', kind: 'type', format: 'type',
  source: 'content', html: 'content', body: 'content', code: 'content', name: 'title',
});

function cleanName(value = '') {
  return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function distance(a = '', b = '') {
  a = cleanName(a); b = cleanName(b);
  if (!a) return b.length;
  if (!b) return a.length;
  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let left = i;
    let diag = i - 1;
    for (let j = 1; j <= b.length; j++) {
      const up = prev[j];
      const next = Math.min(up + 1, left + 1, diag + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev[j] = next; diag = up; left = next;
    }
  }
  return prev[b.length];
}

function nearest(value, candidates = [], maxDistance = 3) {
  const source = cleanName(value);
  if (!source) return '';
  let best = ''; let score = Infinity;
  for (const candidate of candidates) {
    const normalized = cleanName(candidate);
    if (normalized === source) return candidate;
    const d = distance(source, normalized);
    if (d < score) { best = candidate; score = d; }
  }
  const relative = Math.max(source.length, cleanName(best).length);
  return score <= maxDistance && (relative < 7 || score / Math.max(1, relative) <= 0.34) ? best : '';
}

function coerce(value, schema = {}) {
  if (value == null) return value;
  const types = Array.isArray(schema.type) ? schema.type : [schema.type].filter(Boolean);
  const type = types.find((entry) => entry !== 'null') || '';
  if (Array.isArray(schema.enum)) {
    const exact = schema.enum.find((entry) => String(entry).toLowerCase() === String(value).toLowerCase());
    if (exact !== undefined) return exact;
  }
  if (type === 'string' && typeof value !== 'string') return String(value);
  if ((type === 'number' || type === 'integer') && typeof value !== 'number') {
    const n = Number(value);
    if (Number.isFinite(n)) return type === 'integer' ? Math.round(n) : n;
  }
  if (type === 'boolean' && typeof value !== 'boolean') {
    if (/^(true|1|yes|on)$/i.test(String(value))) return true;
    if (/^(false|0|no|off)$/i.test(String(value))) return false;
  }
  if (type === 'array' && !Array.isArray(value)) {
    if (typeof value === 'string') {
      try { const parsed = JSON.parse(value); if (Array.isArray(parsed)) return parsed; } catch {}
      return value.split(/\s*,\s*/).filter(Boolean);
    }
    return [value];
  }
  if (type === 'object' && (typeof value !== 'object' || Array.isArray(value))) {
    if (typeof value === 'string') { try { const parsed = JSON.parse(value); if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed; } catch {} }
  }
  return value;
}

function validateType(value, schema = {}) {
  if (value == null) return schema.type === 'null' || (Array.isArray(schema.type) && schema.type.includes('null'));
  if (!schema.type) return true;
  const types = Array.isArray(schema.type) ? schema.type : [schema.type];
  return types.some((type) => {
    if (type === 'array') return Array.isArray(value);
    if (type === 'object') return value && typeof value === 'object' && !Array.isArray(value);
    if (type === 'integer') return Number.isInteger(value);
    if (type === 'number') return typeof value === 'number' && Number.isFinite(value);
    if (type === 'null') return value == null;
    return typeof value === type;
  });
}

function repairObject(args = {}, schema = {}, repairs = []) {
  if (!args || typeof args !== 'object' || Array.isArray(args)) return args;
  const props = schema.properties && typeof schema.properties === 'object' ? schema.properties : {};
  const allowed = Object.keys(props);
  const out = {};
  for (const [rawKey, rawValue] of Object.entries(args)) {
    let key = rawKey;
    if (!(key in props) && allowed.length) {
      const alias = COMMON_ALIASES[key] || COMMON_ALIASES[cleanName(key)];
      const candidate = alias && allowed.includes(alias) ? alias : nearest(key, allowed);
      if (candidate) {
        repairs.push({ kind: 'parameter', from: key, to: candidate });
        key = candidate;
      }
    }
    const propertySchema = props[key] || {};
    let value = coerce(rawValue, propertySchema);
    if (value !== rawValue) repairs.push({ kind: 'coerce', parameter: key, fromType: Array.isArray(rawValue) ? 'array' : typeof rawValue, toType: Array.isArray(value) ? 'array' : typeof value });
    if (value && typeof value === 'object' && !Array.isArray(value) && propertySchema.type === 'object') value = repairObject(value, propertySchema, repairs);
    out[key] = value;
  }
  return out;
}


function repairToolSpecific(name, args = {}, repairs = []) {
  if (name !== 'create_artifact' || !args || typeof args !== 'object' || Array.isArray(args)) return args;
  const out = { ...args };
  const rawType = String(out.type || '').trim().toLowerCase();
  const aliases = {
    website: 'html', webpage: 'html', page: 'html', app: 'html', game: 'html', 'text/html': 'html', htm: 'html',
    md: 'markdown', 'text/markdown': 'markdown', source: 'code', sourcecode: 'code', 'source-code': 'code', script: 'code',
  };
  if (rawType && aliases[rawType]) {
    out.type = aliases[rawType];
    repairs.push({ kind: 'coerce', parameter: 'type', fromType: rawType, toType: aliases[rawType] });
  }
  if (!out.type) {
    const content = String(out.content || '');
    const language = String(out.language || '').trim().toLowerCase();
    if (/<!doctype\s+html|<html(?:\s|>)|<body(?:\s|>)|<canvas(?:\s|>)|<script(?:\s|>)/i.test(content) || language === 'html') out.type = 'html';
    else if (language === 'markdown' || language === 'md') out.type = 'markdown';
    else if (language) out.type = 'code';
    else if (content) out.type = 'text';
    if (out.type) repairs.push({ kind: 'infer', parameter: 'type', value: out.type });
  }
  return out;
}

function validate(args = {}, schema = {}) {
  const errors = [];
  if (schema.type === 'object' && (!args || typeof args !== 'object' || Array.isArray(args))) errors.push('arguments must be an object');
  for (const key of schema.required || []) if (!(key in (args || {}))) errors.push(`missing required parameter: ${key}`);
  for (const [key, value] of Object.entries(args || {})) {
    const sub = schema.properties?.[key];
    if (!sub) continue;
    if (!validateType(value, sub)) errors.push(`invalid type for ${key}`);
    if (Array.isArray(sub.enum) && !sub.enum.includes(value)) errors.push(`invalid value for ${key}`);
  }
  return errors;
}

export function repairToolInvocation(name, args, definitions = []) {
  const tools = (definitions || []).filter((tool) => tool?.function?.name);
  const names = tools.map((tool) => tool.function.name);
  let repairedName = String(name || '').trim();
  const repairs = [];
  let definition = tools.find((tool) => tool.function.name === repairedName);
  if (!definition && repairedName) {
    const candidate = nearest(repairedName, names, 4);
    if (candidate) {
      repairs.push({ kind: 'tool', from: repairedName, to: candidate });
      repairedName = candidate;
      definition = tools.find((tool) => tool.function.name === repairedName);
    }
  }
  if (!definition) return { name: repairedName, args: args && typeof args === 'object' ? args : {}, repairs, valid: false, errors: [`Unknown BlackRiver tool: ${repairedName || name}`] };
  const schema = definition.function.parameters || { type: 'object', properties: {} };
  let repairedArgs = repairObject(args && typeof args === 'object' && !Array.isArray(args) ? args : {}, schema, repairs);
  repairedArgs = repairToolSpecific(repairedName, repairedArgs, repairs);
  const errors = validate(repairedArgs, schema);
  return { name: repairedName, args: repairedArgs, repairs, valid: errors.length === 0, errors, definition };
}

export function summarizeRepairs(repairs = []) {
  if (!repairs.length) return '';
  return repairs.map((item) => item.kind === 'tool'
    ? `${item.from}→${item.to}`
    : item.kind === 'parameter' ? `${item.from}→${item.to}`
      : item.kind === 'infer' ? `${item.parameter}=inferred:${item.value}`
      : `${item.parameter}:${item.fromType}→${item.toType}`).join(', ');
}
