function fileSet(snapshot = {}) {
  return new Set([...(snapshot.files || []), ...(snapshot.directories || [])].map((value) => String(value || '').replace(/\\/g, '/').toLowerCase()));
}

export function detectVerificationPlan(snapshot = {}, { max = 3 } = {}) {
  const files = fileSet(snapshot);
  const has = (name) => files.has(String(name).toLowerCase());
  const any = (re) => [...files].some((name) => re.test(name));
  const plan = [];
  const add = (id, label, command, kind = 'test') => {
    if (!plan.some((entry) => entry.command === command)) plan.push({ id, label, command, kind });
  };

  if (has('package.json')) {
    add('js-build', 'JavaScript build', 'npm run build --if-present', 'build');
    add('js-test', 'JavaScript tests', 'npm test --if-present', 'test');
    add('js-lint', 'JavaScript lint', 'npm run lint --if-present', 'lint');
  }
  if (has('pyproject.toml') || has('pytest.ini') || has('setup.cfg') || any(/(^|\/)tests?\/.*\.py$/)) add('pytest', 'Python tests', 'python -m pytest -q', 'test');
  if (has('cargo.toml')) add('cargo-test', 'Rust tests', 'cargo test --quiet', 'test');
  if (has('go.mod')) add('go-test', 'Go tests', 'go test ./...', 'test');
  if (has('pom.xml')) add('maven-test', 'Maven tests', 'mvn test -q', 'test');
  if (has('gradlew.bat')) add('gradle-test-win', 'Gradle tests', 'gradlew.bat test', 'test');
  else if (has('gradlew')) add('gradle-test', 'Gradle tests', './gradlew test', 'test');
  if (any(/\.sln$/) || any(/\.csproj$/)) add('dotnet-test', '.NET tests', 'dotnet test --nologo', 'test');
  if (has('cmakelists.txt') && (has('build') || any(/^build\//))) add('cmake-build', 'CMake build', 'cmake --build build', 'build');

  return plan.slice(0, Math.max(1, Math.min(Number(max) || 3, 6)));
}

export function verificationSummary(results = []) {
  const passed = results.filter((item) => item.ok).length;
  const failed = results.filter((item) => !item.ok).length;
  if (!results.length) return 'No automatic verification command was detected.';
  return `${passed}/${results.length} verification checks passed${failed ? ` · ${failed} failed` : ''}.`;
}
