const STORAGE_KEY = 'blackriver.memory.v1';

function uid(prefix = 'mem') {
  return `${prefix}_${crypto.randomUUID?.() || `${Date.now()}_${Math.random().toString(16).slice(2)}`}`;
}

function cleanText(value = '', max = 1400) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, max);
}

function tokens(value = '') {
  return new Set(cleanText(value, 8000).toLowerCase().match(/[\p{L}\p{N}_./:+-]{2,}/gu) || []);
}

function overlapScore(a, b) {
  if (!a.size || !b.size) return 0;
  let hit = 0;
  for (const value of a) if (b.has(value)) hit += 1;
  return hit / Math.sqrt(a.size * b.size);
}

function normalizeScope(scope) {
  return ['global', 'project', 'conversation', 'experience'].includes(scope) ? scope : 'global';
}

function normalizeMemory(raw = {}) {
  return {
    id: String(raw.id || uid()),
    scope: normalizeScope(raw.scope),
    projectId: String(raw.projectId || ''),
    conversationId: String(raw.conversationId || ''),
    type: ['preference', 'decision', 'fact', 'convention', 'experience', 'goal', 'note'].includes(raw.type) ? raw.type : 'note',
    title: cleanText(raw.title || 'Memory', 140),
    content: cleanText(raw.content || '', 1800),
    tags: Array.isArray(raw.tags) ? raw.tags.map((tag) => cleanText(tag, 60).toLowerCase()).filter(Boolean).slice(0, 16) : [],
    pinned: !!raw.pinned,
    confidence: Math.max(0, Math.min(1, Number(raw.confidence ?? 0.8))),
    source: cleanText(raw.source || 'manual', 80),
    createdAt: Number(raw.createdAt) || Date.now(),
    updatedAt: Number(raw.updatedAt) || Date.now(),
    lastUsedAt: Number(raw.lastUsedAt) || 0,
    useCount: Number(raw.useCount) || 0,
  };
}

function defaultState() {
  return {
    version: 1,
    settings: {
      enabled: true,
      automatic: true,
      global: true,
      project: true,
      conversation: true,
      experience: true,
    },
    memories: [],
  };
}

function sensitive(value = '') {
  const text = String(value || '');
  return /\b(password|passwd|secret|api[_ -]?key|access[_ -]?token|refresh[_ -]?token|private[_ -]?key|seed phrase|mnemonic|credit card|cvv|social security|ssn)\b/i.test(text)
    || /\b(sk-[a-z0-9_-]{12,}|gh[pousr]_[a-z0-9]{16,}|nvapi-[a-z0-9_-]{12,})\b/i.test(text);
}

function inferType(text = '') {
  if (/\b(prefer|preference|i like|i want|default to|rather than|avoid|do not use|don't use)\b/i.test(text)) return 'preference';
  if (/\b(stable baseline|locked|decision|decided|roadmap|use .* instead|from now on)\b/i.test(text)) return 'decision';
  if (/\b(always|never|must|convention|rule|workflow)\b/i.test(text)) return 'convention';
  if (/\b(goal|plan|want to|aim to|target)\b/i.test(text)) return 'goal';
  return 'fact';
}

function titleFromContent(text = '') {
  const clean = cleanText(text, 180);
  const first = clean.split(/[.!?;]\s/)[0] || clean;
  return first.length <= 72 ? first : `${first.slice(0, 69).trim()}…`;
}

function explicitDurableMemory(text = '') {
  const clean = cleanText(text, 1600);
  if (!clean || sensitive(clean)) return null;
  if (/\b(?:do not|don't)\s+remember\b|\bforget\b/i.test(clean)) return null;
  // Conservative automatic memory: explicit durable instructions plus clear
  // first-person environment/preferences. Avoid treating ordinary task prose as
  // profile data merely because it mentions a tool or product.
  const strong = /\b(remember|remember that|remember this|from now on|going forward|always|never|my default|i prefer|i like|i dislike|i hate|prefer .* over|do not use|don't use|stable baseline|lock(?:ed)? to|we want|we will use|we use|our default|my setup|my machine|i use|i run|i work on|i develop|i own|i'm using|i am using)\b/i.test(clean);
  if (!strong) return null;
  if (/^(hi|hello|thanks|thank you|ok|okay|yes|no)\b/i.test(clean) && clean.length < 80) return null;
  return clean;
}


function inferScopeFromText(text = '', projectId = '') {
  if (!projectId) return 'global';
  return /\b(project|repo|repository|this codebase|this app|in this project|for this project|project uses|project default|workspace)\b/i.test(String(text || '')) ? 'project' : 'global';
}

function experienceCandidates({ user = '', assistant = '', toolEvents = [], projectId = '' } = {}) {
  const out = [];
  const errors = toolEvents.filter((event) => event?.phase === 'result' && event?.result?.error).map((event) => String(event.result.error));
  const successes = toolEvents.filter((event) => event?.phase === 'result' && !event?.result?.error).map((event) => event.name);
  if (errors.some((value) => /failed to parse grammar|initialize samplers/i.test(value)) && successes.length) {
    out.push({ title: 'llama.cpp tool grammar recovery', content: 'If llama.cpp rejects a large native tool grammar, prefer BlackRiver compatibility transport or a reduced routed tool surface instead of retrying the same oversized grammar.', tags: ['llama.cpp', 'tools', 'grammar', 'recovery'] });
  }
  if (toolEvents.some((event) => event?.name === 'inspect_artifact' && event?.phase === 'result' && event?.result?.healthy === false)
      && toolEvents.some((event) => event?.name === 'update_artifact' && event?.phase === 'result')) {
    out.push({ title: 'Artifact runtime repair loop', content: 'For interactive artifacts, render after changes, inspect runtime/console diagnostics, repair the same artifact, and verify again before completion.', tags: ['artifact', 'verification', 'runtime'] });
  }
  const command = toolEvents.find((event) => event?.name === 'run_command' && event?.phase === 'result' && event?.result?.ok)?.args?.command;
  if (projectId && command && /(?:npm|pnpm|yarn|pytest|cargo|cmake|gradle|mvn|dotnet).*\b(?:test|build|lint|check)\b/i.test(command)) {
    out.push({ title: 'Project verification command', content: `A successful verification command for this project is: ${cleanText(command, 400)}`, tags: ['project', 'verification', 'command'] });
  }
  const verification = toolEvents.find((event) => event?.name === 'verify_project' && event?.phase === 'result' && event?.result?.ok);
  const verifiedCommands = (verification?.result?.results || []).filter((item) => item?.ok && item?.command).map((item) => item.command).slice(0, 4);
  if (projectId && verifiedCommands.length) {
    out.push({ title: 'Project verification workflow', content: `Verified project checks: ${verifiedCommands.join(' ; ')}`, tags: ['project', 'verification', 'workflow'] });
  }
  return out;
}

export class MemoryStore extends EventTarget {
  constructor() {
    super();
    this.state = this.load();
  }

  load() {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
      if (parsed?.memories) {
        const base = defaultState();
        return {
          ...base,
          ...parsed,
          settings: { ...base.settings, ...(parsed.settings || {}) },
          memories: parsed.memories.map(normalizeMemory).filter((item) => item.content),
        };
      }
    } catch {}
    return defaultState();
  }

  save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.state));
    this.dispatchEvent(new Event('change'));
  }

  get settings() { return { ...this.state.settings }; }
  list() { return [...this.state.memories].sort((a, b) => Number(b.pinned) - Number(a.pinned) || b.updatedAt - a.updatedAt); }
  get(id) { return this.state.memories.find((item) => item.id === id) || null; }

  setSettings(patch = {}) {
    this.state.settings = { ...this.state.settings, ...patch };
    this.save();
    return this.settings;
  }

  upsert(raw = {}) {
    const next = normalizeMemory(raw);
    if (!next.content || sensitive(next.content)) return null;
    const sameScope = (item) => item.scope === next.scope
      && item.projectId === next.projectId
      && item.conversationId === next.conversationId;
    const nextTokens = tokens(`${next.title} ${next.content} ${next.tags.join(' ')}`);
    const duplicate = this.state.memories.find((item) => sameScope(item)
      && overlapScore(nextTokens, tokens(`${item.title} ${item.content} ${item.tags.join(' ')}`)) >= 0.82);
    if (duplicate) {
      duplicate.title = next.title || duplicate.title;
      duplicate.content = next.content.length >= duplicate.content.length ? next.content : duplicate.content;
      duplicate.tags = [...new Set([...(duplicate.tags || []), ...(next.tags || [])])].slice(0, 16);
      duplicate.confidence = Math.max(duplicate.confidence, next.confidence);
      duplicate.updatedAt = Date.now();
      duplicate.source = next.source || duplicate.source;
      this.save();
      return duplicate;
    }
    this.state.memories.unshift(next);
    this.state.memories = this.state.memories.slice(0, 2400);
    this.save();
    return next;
  }

  update(id, patch = {}) {
    const item = this.get(id);
    if (!item) return null;
    if (patch.title !== undefined) item.title = cleanText(patch.title, 140) || item.title;
    if (patch.content !== undefined) {
      const content = cleanText(patch.content, 1800);
      if (!content || sensitive(content)) return item;
      item.content = content;
    }
    if (patch.pinned !== undefined) item.pinned = !!patch.pinned;
    if (patch.scope !== undefined) item.scope = normalizeScope(patch.scope);
    if (patch.projectId !== undefined) item.projectId = String(patch.projectId || '');
    if (patch.tags !== undefined) item.tags = Array.isArray(patch.tags) ? patch.tags.map((tag) => cleanText(tag, 60).toLowerCase()).filter(Boolean).slice(0, 16) : item.tags;
    item.updatedAt = Date.now();
    this.save();
    return item;
  }

  forget(id) {
    const before = this.state.memories.length;
    this.state.memories = this.state.memories.filter((item) => item.id !== id);
    if (this.state.memories.length !== before) this.save();
    return this.state.memories.length !== before;
  }

  clearScope(scope, projectId = '') {
    const normalized = normalizeScope(scope);
    this.state.memories = this.state.memories.filter((item) => !(item.scope === normalized && (!projectId || item.projectId === projectId)));
    this.save();
  }

  retrieve(query = '', { projectId = '', conversationId = '', max = 8, greed = false } = {}) {
    if (!this.state.settings.enabled) return [];
    const q = tokens(query);
    const now = Date.now();
    const eligible = this.state.memories.filter((item) => {
      if (item.scope === 'global') return this.state.settings.global;
      if (item.scope === 'project') return this.state.settings.project && !!projectId && item.projectId === projectId;
      if (item.scope === 'conversation') return this.state.settings.conversation && !!conversationId && item.conversationId === conversationId;
      if (item.scope === 'experience') return this.state.settings.experience && (!item.projectId || item.projectId === projectId);
      return false;
    });
    const scored = eligible.map((item) => {
      const hay = tokens(`${item.title} ${item.content} ${item.tags.join(' ')}`);
      let score = overlapScore(q, hay) * 5;
      if (item.pinned) score += 2.4;
      if (item.scope === 'conversation') score += 1.6;
      if (item.scope === 'project') score += 1.35;
      if (item.scope === 'experience') score += 0.75;
      if (item.scope === 'global') score += 0.4;
      score += item.confidence * 0.7;
      const ageDays = Math.max(0, (now - item.updatedAt) / 86_400_000);
      score += Math.max(0, 0.55 - Math.min(ageDays, 180) / 360);
      return { item, score };
    }).filter(({ item, score }) => item.pinned || score >= (q.size ? 0.95 : 2.0));
    scored.sort((a, b) => b.score - a.score || b.item.updatedAt - a.item.updatedAt);
    const selected = scored.slice(0, Math.max(1, Math.min(Number(max) || 8, greed ? 5 : 12))).map(({ item }) => item);
    if (selected.length) {
      for (const item of selected) { item.lastUsedAt = now; item.useCount += 1; }
      // Avoid emitting a change event on every prompt; persistence is enough.
      try { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.state)); } catch {}
    }
    return selected;
  }

  contextBlock(query = '', options = {}) {
    const selected = this.retrieve(query, options);
    if (!selected.length) return { memories: [], text: '' };
    const lines = selected.map((item) => `- [${item.scope}${item.type ? `/${item.type}` : ''}] ${item.content}`);
    return { memories: selected, text: `Relevant BlackRiver Memory (use only when it helps the current task):\n${lines.join('\n')}` };
  }


  get definitions() {
    return [
      { type: 'function', function: { name: 'search_memory', description: 'Search BlackRiver Memory for relevant stored user/project/agent memories.', parameters: { type: 'object', properties: { query: { type: 'string' }, max_results: { type: 'number' } }, required: ['query'] } } },
      { type: 'function', function: { name: 'save_memory', description: 'Save a durable memory because the user explicitly asked BlackRiver to remember it. Do not save secrets or transient task details.', parameters: { type: 'object', properties: { content: { type: 'string' }, title: { type: 'string' }, scope: { type: 'string', enum: ['global', 'project', 'conversation'] } }, required: ['content'] } } },
      { type: 'function', function: { name: 'forget_memory', description: 'Forget one BlackRiver memory by exact memory id. Search memory first when the id is unknown.', parameters: { type: 'object', properties: { memory_id: { type: 'string' } }, required: ['memory_id'] } } },
    ];
  }

  async execute(name, args = {}, { projectId = '', conversationId = '' } = {}) {
    if (name === 'search_memory') {
      const items = this.retrieve(String(args.query || ''), { projectId, conversationId, max: Math.max(1, Math.min(Number(args.max_results) || 8, 20)) });
      return { memories: items.map((item) => ({ id: item.id, scope: item.scope, type: item.type, title: item.title, content: item.content, pinned: item.pinned })) };
    }
    if (name === 'save_memory') {
      const scope = normalizeScope(args.scope || inferScopeFromText(args.content, projectId));
      if (scope === 'experience') throw new Error('Explicit user memories cannot be saved to agent experience.');
      const item = this.upsert({ scope, projectId: scope === 'project' ? projectId : '', conversationId: scope === 'conversation' ? conversationId : '', type: inferType(args.content), title: args.title || titleFromContent(args.content), content: args.content, source: 'tool:user-requested', confidence: 1 });
      if (!item) throw new Error('BlackRiver did not store that memory. Secrets and empty memories are rejected.');
      return { status: 'remembered', memory: { id: item.id, scope: item.scope, title: item.title, content: item.content } };
    }
    if (name === 'forget_memory') {
      const item = this.get(String(args.memory_id || ''));
      if (!item) return { status: 'not_found' };
      this.forget(item.id);
      return { status: 'forgotten', memory_id: item.id, title: item.title };
    }
    throw new Error(`Unknown BlackRiver memory tool: ${name}`);
  }

  observeUserMessage(text = '', { projectId = '', conversationId = '' } = {}) {
    if (!this.state.settings.enabled || !this.state.settings.automatic) return null;
    const durable = explicitDurableMemory(text);
    if (!durable) return null;
    const scope = inferScopeFromText(durable, projectId);
    if (scope === 'global' && !this.state.settings.global) return null;
    if (scope === 'project' && !this.state.settings.project) return null;
    return this.upsert({
      scope,
      projectId: scope === 'project' ? projectId : '',
      conversationId: scope === 'conversation' ? conversationId : '',
      type: inferType(durable),
      title: titleFromContent(durable),
      content: durable,
      source: 'automatic:user',
      confidence: /\bremember|from now on|always|never|stable baseline|locked\b/i.test(durable) ? 0.96 : 0.84,
      tags: [...tokens(durable)].slice(0, 8),
    });
  }

  observeTurn({ user = '', assistant = '', toolEvents = [], projectId = '', conversationId = '' } = {}) {
    const created = [];
    const userMemory = this.observeUserMessage(user, { projectId, conversationId });
    if (userMemory) created.push(userMemory);
    if (!this.state.settings.enabled || !this.state.settings.automatic || !this.state.settings.experience) return created;
    for (const candidate of experienceCandidates({ user, assistant, toolEvents, projectId })) {
      const item = this.upsert({
        scope: 'experience',
        projectId,
        type: 'experience',
        title: candidate.title,
        content: candidate.content,
        tags: candidate.tags || [],
        source: 'automatic:agent-experience',
        confidence: 0.9,
      });
      if (item) created.push(item);
    }
    return created;
  }
}
