import { createTaskGraph, advanceTaskGraph, graphRecoveryBlock } from './task-graph.js';
const KEY = 'blackriver.agent.sessions.v1';

function clean(value = '', max = 1200) { return String(value || '').replace(/\s+/g, ' ').trim().slice(0, max); }

export class AgentSessionStore extends EventTarget {
  constructor() {
    super();
    this.sessions = this.load();
    let changed = false;
    for (const session of Object.values(this.sessions)) {
      if (session?.status === 'running') { session.status = 'interrupted'; session.interruptedAt = Date.now(); changed = true; }
    }
    if (changed) this.save();
  }

  load() { try { return JSON.parse(localStorage.getItem(KEY) || '{}') || {}; } catch { return {}; } }
  save() { localStorage.setItem(KEY, JSON.stringify(this.sessions)); this.dispatchEvent(new Event('change')); }

  get(conversationId) { return this.sessions[String(conversationId || '')] || null; }

  recoveryContext(conversationId) {
    const session = this.get(conversationId);
    if (!session || session.status !== 'interrupted') return '';
    const tools = (session.tools || []).slice(-12).map((item) => `- ${item.name}: ${item.status}`).join('\n');
    const graph = graphRecoveryBlock(session.taskGraph);
    return `BlackRiver durable session recovery: a previous Work run was interrupted.\nGoal: ${session.goal || 'unknown'}\nLast activity: ${session.activity || 'unknown'}${graph ? `\n${graph}` : ''}${tools ? `\nRecent tool activity:\n${tools}` : ''}\nContinue from verified persisted conversation/project state instead of blindly restarting. Re-check any operation whose success is uncertain.`;
  }

  resume(conversationId, data = {}) {
    const id = String(conversationId || ''); if (!id) return null;
    const session = this.sessions[id];
    if (!session) return this.begin(conversationId, data);
    session.status = 'running';
    session.model = clean(data.model || session.model, 160);
    session.greed = data.greed !== undefined ? !!data.greed : !!session.greed;
    session.crew = String(data.crew || session.crew || 'auto');
    session.activity = 'Continuing';
    session.resumedAt = Date.now();
    session.updatedAt = Date.now();
    this.save(); return session;
  }

  begin(conversationId, data = {}) {
    const id = String(conversationId || ''); if (!id) return null;
    const previous = this.sessions[id];
    this.sessions[id] = {
      id,
      status: 'running',
      goal: clean(data.goal, 1600),
      projectId: String(data.projectId || ''),
      model: clean(data.model, 160),
      greed: !!data.greed,
      crew: String(data.crew || 'auto'),
      activity: 'Starting',
      tools: [],
      taskGraph: createTaskGraph(data.goal, { hasProject: !!data.projectId }),
      startedAt: Date.now(),
      updatedAt: Date.now(),
      previousInterruptedAt: previous?.status === 'interrupted' ? previous.interruptedAt || previous.updatedAt : 0,
    };
    this.save(); return this.sessions[id];
  }

  noteState(conversationId, state = {}) {
    const session = this.get(conversationId); if (!session || session.status !== 'running') return;
    session.activity = clean(state.label || state.phase || session.activity, 240);
    session.updatedAt = Date.now(); this.save();
  }

  noteTool(conversationId, event = {}) {
    const session = this.get(conversationId); if (!session || session.status !== 'running') return;
    if (event.phase !== 'result') return;
    session.tools ||= [];
    session.tools.push({ name: String(event.name || 'tool'), status: event.result?.error ? `error: ${clean(event.result.error, 220)}` : event.result?.status || (event.result?.ok === false ? 'failed' : 'ok'), at: Date.now() });
    session.tools = session.tools.slice(-24);
    session.taskGraph = advanceTaskGraph(session.taskGraph || createTaskGraph(session.goal, { hasProject: !!session.projectId }), event);
    session.updatedAt = Date.now(); this.save();
  }

  pause(conversationId, { summary = '', reason = 'checkpoint' } = {}) {
    const session = this.get(conversationId); if (!session) return;
    session.status = 'interrupted';
    session.summary = clean(summary, 1800);
    session.pauseReason = clean(reason, 240);
    session.interruptedAt = Date.now();
    session.updatedAt = Date.now();
    this.save();
  }

  complete(conversationId, { summary = '', error = '' } = {}) {
    const session = this.get(conversationId); if (!session) return;
    session.status = error ? 'failed' : 'completed';
    session.summary = clean(summary, 1800);
    session.error = clean(error, 800);
    session.completedAt = Date.now(); session.updatedAt = Date.now(); this.save();
  }
}
