const STORAGE_KEY = 'blackriver.policy.engine.v1';

const READ_ONLY_TOOLS = new Set([
  'list_directory', 'file_glob_search', 'read_file', 'read_many_files', 'grep_search', 'get_info',
  'git_status', 'git_diff', 'find_symbol', 'find_references', 'project_intelligence', 'lsp_query', 'code_intelligence',
  'browser_inspect', 'browser_console', 'browser_snapshot', 'browser_get_state', 'browser_wait', 'worktree_list',
  'terminal_read', 'terminal_list', 'list_artifacts', 'read_artifact', 'inspect_artifact', 'read_document',
]);

const SAFE_COMMANDS = [
  /^git\s+(?:status|diff|log(?:\s|$)|show(?:\s|$))/i,
  /^(?:npm|pnpm|yarn|bun)\s+(?:test|run\s+(?:test|build|lint|check|typecheck))(?:\s|$)/i,
  /^(?:pytest|python(?:\.exe)?\s+-m\s+pytest)(?:\s|$)/i,
  /^cargo\s+(?:test|check|clippy)(?:\s|$)/i,
  /^go\s+test(?:\s|$)/i,
  /^dotnet\s+(?:test|build)(?:\s|$)/i,
];

const DANGEROUS_COMMAND = /(?:^|[;&|]\s*)(?:rm\s+-rf\b|rmdir\s+\/s\b|del\s+\/s\b|format\b|shutdown\b|reboot\b|git\s+reset\s+--hard\b|git\s+clean\s+-[a-z]*f|diskpart\b|reg\s+delete\b)|(?:curl|wget|irm|iwr)\b[^\n|;&]*(?:\||\|\s*(?:sh|bash|cmd|powershell))/i;
const SENSITIVE_PATH = /(?:^|\/)(?:\.env(?:\.|$)|\.npmrc$|\.pypirc$|id_rsa$|id_ed25519$|credentials?(?:\.|$)|secrets?(?:\.|$)|.*\.(?:pem|p12|pfx|key))$/i;

function normalizePath(value = '') { return String(value || '').replace(/\\/g, '/').replace(/^\.\//, ''); }
function load() { try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') || {}; } catch { return {}; } }

export class PolicyEngine extends EventTarget {
  constructor() {
    super();
    this.settings = { safeVerificationAutoAllow: true, localhostBrowserAutoAllow: true, rules: [], ...(load() || {}) };
    if (!Array.isArray(this.settings.rules)) this.settings.rules = [];
  }

  save() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.settings)); } catch {} this.dispatchEvent(new Event('change')); }
  update(patch = {}) { this.settings = { ...this.settings, ...patch }; this.save(); return this.settings; }

  ruleMatches(rule = {}, name = '', args = {}) {
    const wildcard = (pattern = '', value = '') => {
      if (!pattern) return true;
      const special = new Set('\\^$.*+?()[]{}|'.split(''));
      const escaped = [...String(pattern)].map((ch) => ch === '*' ? '.*' : ch === '?' ? '.' : special.has(ch) ? `\\${ch}` : ch).join('');
      try { return new RegExp(`^${escaped}$`, 'i').test(String(value || '')); } catch { return false; }
    };
    if (rule.tool && !wildcard(rule.tool, name)) return false;
    if (rule.path && !wildcard(rule.path, normalizePath(args.path || ''))) return false;
    if (rule.command && !wildcard(rule.command, String(args.command || ''))) return false;
    if (rule.host) {
      try { if (!wildcard(rule.host, new URL(String(args.url || '')).hostname)) return false; }
      catch { return false; }
    }
    return true;
  }

  decide({ tool = '', args = {}, projectNative = false } = {}) {
    const name = String(tool || '');
    // User/project policy rules are evaluated first and can refine the built-in
    // safe defaults without replacing BlackRiver's host boundary.
    for (const rule of this.settings.rules || []) {
      if (!['allow', 'ask', 'deny'].includes(rule?.decision) || !this.ruleMatches(rule, name, args)) continue;
      return { decision: rule.decision, reason: rule.reason || 'custom-rule', ruleId: rule.id || '' };
    }
    if (READ_ONLY_TOOLS.has(name)) return { decision: 'allow', reason: 'read-only' };

    if (['write_file', 'edit_file', 'replace_in_file'].includes(name)) {
      const path = normalizePath(args.path || '');
      if (SENSITIVE_PATH.test(path)) return { decision: 'deny', reason: 'sensitive-file' };
      return { decision: 'ask', reason: 'project-write' };
    }

    if (name === 'terminal_session') {
      const action = String(args.action || 'list');
      if (['list', 'read'].includes(action)) return { decision: 'allow', reason: 'terminal-read' };
      if (action === 'start') {
        const command = String(args.command || '');
        if (DANGEROUS_COMMAND.test(command)) return { decision: 'deny', reason: 'destructive-command' };
        if (this.settings.safeVerificationAutoAllow && SAFE_COMMANDS.some((pattern) => pattern.test(command.trim()))) return { decision: 'allow', reason: 'safe-verification' };
      }
      return { decision: 'ask', reason: 'terminal-control' };
    }
    if (name === 'worktree') {
      const action = String(args.action || 'list');
      if (['list', 'read', 'diff', 'status'].includes(action)) return { decision: 'allow', reason: 'isolated-worktree-read' };
      if (action === 'run') {
        const command = String(args.command || '');
        if (DANGEROUS_COMMAND.test(command)) return { decision: 'deny', reason: 'destructive-command' };
        if (this.settings.safeVerificationAutoAllow && SAFE_COMMANDS.some((pattern) => pattern.test(command.trim()))) return { decision: 'allow', reason: 'safe-verification' };
      }
      return { decision: 'ask', reason: 'git-worktree' };
    }

    if (name === 'run_command' || name === 'terminal_start') {
      const command = String(args.command || '');
      if (DANGEROUS_COMMAND.test(command)) return { decision: 'deny', reason: 'destructive-command' };
      if (this.settings.safeVerificationAutoAllow && SAFE_COMMANDS.some((pattern) => pattern.test(command.trim()))) return { decision: 'allow', reason: 'safe-verification' };
      return { decision: 'ask', reason: 'shell' };
    }

    if (['terminal_write', 'terminal_stop', 'worktree_create', 'worktree_remove'].includes(name)) return { decision: 'ask', reason: name.startsWith('worktree') ? 'git-worktree' : 'terminal-control' };

    if (name === 'browser_navigate') {
      try {
        const url = new URL(String(args.url || ''));
        if (!['http:', 'https:'].includes(url.protocol)) return { decision: 'deny', reason: 'unsupported-url' };
        if (this.settings.localhostBrowserAutoAllow && ['localhost', '127.0.0.1', '::1', '[::1]'].includes(url.hostname)) return { decision: 'allow', reason: 'localhost' };
      } catch { return { decision: 'deny', reason: 'invalid-url' }; }
      return { decision: 'ask', reason: 'network-navigation' };
    }

    if (['browser_click', 'browser_type', 'browser_key', 'browser_scroll'].includes(name)) return { decision: 'allow', reason: 'sandboxed-browser' };
    if (name.startsWith('create_') || name.startsWith('update_') || name === 'call_mcp_tool') return { decision: 'ask', reason: 'mutation-or-external-tool' };
    return { decision: 'ask', reason: projectNative ? 'native-action' : 'action' };
  }

  async authorize(request = {}, fallbackApprove = null) {
    const verdict = this.decide(request);
    if (verdict.decision === 'allow') return true;
    if (verdict.decision === 'deny') return false;
    if (typeof fallbackApprove !== 'function') return false;
    return fallbackApprove({ ...request.approval, policy: verdict });
  }
}
