import { WllamaRuntime } from './wllama-runtime.js';
import { AndroidLlamaRuntime } from './android-llama-runtime.js';

export class PlatformLocalRuntime extends EventTarget {
  constructor() {
    super();
    this.web = new WllamaRuntime();
    this.android = new AndroidLlamaRuntime();
    this.active = this.android.available ? this.android : this.web;
    for (const runtime of [this.web, this.android]) {
      for (const type of ['status', 'hardware', 'cache-error']) runtime.addEventListener(type, (event) => this.dispatchEvent(new CustomEvent(type, { detail: event.detail })));
    }
  }
  get isAndroidNative() { return this.active === this.android; }
  get sampling() { return this.active.sampling; }
  get runtimeParams() { return this.active.runtimeParams; }
  get modelManager() { return this.active.modelManager; }
  get hardware() { return this.active.hardware; }
  get loaded() { return this.active.loaded; }
  get reloadSpec() { return this.active.reloadSpec; }
  get isLoaded() { return this.active.isLoaded; }
  get contextSize() { return this.active.contextSize; }
  get loadedContextInfo() { return this.active.loadedContextInfo; }
  get capabilities() { return this.active.capabilities; }
  get supportsWebGPU() { return this.active.supportsWebGPU; }
  probeWebGPU(...args) { return this.active.probeWebGPU(...args); }
  listCachedModels(...args) { return this.active.listCachedModels(...args); }
  setRuntimeParams(...args) { return this.active.setRuntimeParams(...args); }
  setSampling(...args) { return this.active.setSampling(...args); }
  reasoningDescriptor(...args) { return this.active.reasoningDescriptor(...args); }
  reloadCurrent(...args) { return this.active.reloadCurrent(...args); }
  loadLocal(...args) { return this.active.loadLocal(...args); }
  loadFromUrls(...args) { return this.active.loadFromUrls(...args); }
  loadFromHF(...args) { return this.active.loadFromHF(...args); }
  chat(...args) { return this.active.chat(...args); }
  stop(...args) { return this.active.stop(...args); }
  unload(...args) { return this.active.unload(...args); }
  pickAndroidModel(...args) { return this.android.pickModel(...args); }
  pickAndroidModelDocument(...args) { return this.android.pickModelDocument(...args); }
  pickAndroidProjectorDocument(...args) { return this.android.pickProjectorDocument(...args); }
  loadAndroidSelectedProfile(...args) { return this.android.loadSelectedProfile(...args); }
  clearAndroidProjector(...args) { return this.android.clearProjector(...args); }
  androidSelectedProfile(...args) { return this.android.getSelectedProfile(...args); }
  androidInfo(...args) { return this.android.getDeviceInfo(...args); }
}
