export class ToolRegistry extends EventTarget {
  constructor() {
    super();
    this.sources = new Map();
  }

  registerSource(id, source) {
    if (!id || !source) throw new Error('Tool source id and source are required.');
    this.sources.set(id, source);
    this.dispatchEvent(new CustomEvent('change', { detail: { id, action: 'register' } }));
    return () => this.unregisterSource(id);
  }

  unregisterSource(id) {
    const removed = this.sources.delete(id);
    if (removed) this.dispatchEvent(new CustomEvent('change', { detail: { id, action: 'unregister' } }));
    return removed;
  }

  source(id) {
    return this.sources.get(id) || null;
  }


  gatewayDefinitions(id, context = {}) {
    const source = this.sources.get(id);
    if (!source) return [];
    const definitions = typeof source.gatewayDefinitions === 'function' ? source.gatewayDefinitions(context) : source.gatewayDefinitions;
    return Array.isArray(definitions) ? definitions : [];
  }

  definitions({ sourceIds = null, context = {} } = {}) {
    const allowed = sourceIds ? new Set(sourceIds) : null;
    const out = [];
    const seen = new Set();
    for (const [id, source] of this.sources) {
      if (allowed && !allowed.has(id)) continue;
      const definitions = typeof source.definitions === 'function' ? source.definitions(context) : source.definitions;
      for (const tool of definitions || []) {
        const name = tool?.function?.name;
        if (!name || seen.has(name)) continue;
        seen.add(name);
        out.push(tool);
      }
    }
    return out;
  }

  canExecute(name, { sourceIds = null, context = {} } = {}) {
    const allowed = sourceIds ? new Set(sourceIds) : null;
    for (const [id, source] of this.sources) {
      if (allowed && !allowed.has(id)) continue;
      if (typeof source.has === 'function' && source.has(name, context)) return true;
      const definitions = typeof source.definitions === 'function' ? source.definitions(context) : source.definitions;
      if ((definitions || []).some((tool) => tool?.function?.name === name)) return true;
    }
    return false;
  }

  async execute(name, args = {}, context = {}) {
    for (const [id, source] of this.sources) {
      if (context.sourceIds && !context.sourceIds.includes(id)) continue;
      const definitions = typeof source.definitions === 'function' ? source.definitions(context) : source.definitions;
      const owns = typeof source.has === 'function'
        ? source.has(name, context)
        : (definitions || []).some((tool) => tool?.function?.name === name);
      if (!owns) continue;
      if (typeof source.execute !== 'function') throw new Error(`Tool source ${id} cannot execute tools.`);
      return source.execute(name, args, context);
    }
    throw new Error(`Unknown BlackRiver tool: ${name}`);
  }

  describe() {
    return [...this.sources.entries()].map(([id, source]) => ({
      id,
      label: source.label || id,
      kind: source.kind || 'builtin',
      enabled: source.enabled !== false,
      tools: (typeof source.definitions === 'function' ? source.definitions({}) : source.definitions || []).length,
    }));
  }
}
