async function restoreNativeRendererState() {
  if (!nativeAvailable()) return;
  try {
    const backup = await loadNativeStateBackup();
    const entries = backup?.entries && typeof backup.entries === 'object' ? backup.entries : null;
    if (!entries) return;
    for (const [key, value] of Object.entries(entries)) {
      if (!String(key).startsWith('blackriver.')) continue;
      if (localStorage.getItem(key) == null) localStorage.setItem(key, String(value ?? ''));
    }
  } catch (error) {
    console.warn('[BlackRiver] renderer state backup restore skipped', error);
  }
}

