let rendererBackupTimer = 0;
function rendererStateSnapshot() {
  const entries = {};
  let total = 0;
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (!key?.startsWith('blackriver.')) continue;
    // Artifact preview localStorage belongs to generated apps and can be huge;
    // keep the durable Workspace configuration backup focused on product state.
    if (key.startsWith('blackriver.artifact.preview.storage.')) continue;
    const value = localStorage.getItem(key) ?? '';
    total += key.length + value.length;
    if (total > 6_000_000) break;
    entries[key] = value;
  }
  return { version: '4.0.0', entries };
}
function scheduleRendererStateBackup(delay = 850) {
  if (!nativeAvailable()) return;
  clearTimeout(rendererBackupTimer);
  rendererBackupTimer = setTimeout(() => { saveNativeStateBackup(rendererStateSnapshot()).catch(() => {}); }, delay);
}
for (const source of [store, artifacts, plugins, skills, memory, agentSessions, providerStore, policy, hooks]) source?.addEventListener?.('change', () => scheduleRendererStateBackup());
window.addEventListener('beforeunload', () => { if (nativeAvailable()) saveNativeStateBackup(rendererStateSnapshot()).catch(() => {}); });
