async function migrateRememberedProviderSecrets() {
  if (!accounts.isNative) return;
  for (const provider of providerStore.list()) {
    if (!provider.apiKey || !provider.rememberKey || provider.credentialId) continue;
    try {
      const credential = await accounts.saveApiKey(provider.flavor || 'api', provider.apiKey, provider.name || 'API provider', [new URL(provider.baseUrl).origin]);
      providerStore.upsert({ ...provider, apiKey: '', rememberKey: false, credentialId: credential.id, authMode: 'api-key-secure' });
    } catch {}
  }
}
async function retireRemovedProviderCredentials() {
  if (!accounts.isNative) return;
  for (const credentialId of providerStore.takeRetiredCredentialIds?.() || []) {
    try { await accounts.removeCredential(credentialId); } catch {}
  }
}
accounts.refresh({ includeCodex: runtime.selection?.kind === 'codex' }).then(async (state) => {
  await retireRemovedProviderCredentials();
  await migrateRememberedProviderSecrets();
  if (runtime.isCodex) {
    if (!state.codex?.connected) runtime.selectLocal();
    else { try { const models = await accounts.listCodexModels(); codexRuntime.setCatalog(models); runtime.syncSelection(); } catch {} }
  }
}).catch(() => {});

