function setMode(mode, { persist = true } = {}) {
  const value = mode === 'work' ? 'work' : 'chat';
  if (persist) store.switchMode(value);
  document.body.dataset.mode = value;
  document.querySelectorAll('.mode-tab').forEach((btn) => btn.classList.toggle('active', btn.dataset.mode === value));

  // Chat and Work are two context lanes over the SAME loaded Wllama model.
  // Switching tabs never unloads/reloads weights; only the active message history changes.
  if (value === 'chat') hideArtifactPane({ preserveActive: true });
  renderEmptyState();
  updatePlaceholder();
  syncReasoningUi();
  syncGreedUi();
  syncCrewUi();
  syncYoloUi();
  syncContextUi();
  syncArtifactReopenButton();
}

function updatePlaceholder() {
  els.promptInput.placeholder = store.state.mode === 'work' ? 'Work on anything' : 'Ask BlackRiver';
}

function renderEmptyState() {
  const conv = store.activeConversation;
  const empty = !conv || conv.messages.length === 0;
  els.emptyState.classList.toggle('hidden', !empty);
  if (store.state.mode === 'work') {
    els.emptyTitle.textContent = 'What should we work on?';
    els.emptySubtitle.textContent = project.root ? `Project connected: ${project.name}` : project.name ? `Project saved: ${project.name} · reconnect required.` : 'Create an artifact or connect a local project.';
  } else {
    els.emptyTitle.textContent = 'Ready when you are.';
    els.emptySubtitle.textContent = 'Private local intelligence, running on your hardware.';
  }
}

function renderRecents() {
  // Recents are global, exactly like the stable 1.6.5 shell. An active Project
  // scopes Work execution, not sidebar visibility. Updated conversations sort
  // to the top so returning to an old chat and continuing it promotes it.
  const items = store.recentConversations(20);
  els.recents.innerHTML = items.map((c) => {
    const isGenerating = generating && c.id === generationConversationId;
    const title = escapeHtml(c.title || 'New chat');
    const projectName = c.projectId ? project.projects.find((item) => item.id === c.projectId)?.name : '';
    const contextTitle = c.mode === 'work' ? ` · Work${projectName ? ` · ${projectName}` : ''}` : ' · Chat';
    return `
    <div class="recent-entry ${c.id === store.state.activeConversationId ? 'active' : ''} ${isGenerating ? 'generating' : ''}" data-recent-id="${c.id}">
      <button class="recent" data-conversation="${c.id}" title="${title}${escapeHtml(contextTitle)}${isGenerating ? ' · Generating' : ''}">
        <span>${title}</span>
      </button>
      ${isGenerating ? '<span class="recent-generation-indicator" role="status" aria-label="Generating response" title="Generating response"><span></span></span>' : ''}
      <button class="recent-more" data-conversation-menu="${c.id}" aria-label="Conversation options" title="Conversation options">${icon('more', 17)}</button>
    </div>`;
  }).join('');
  els.recents.querySelectorAll('[data-conversation]').forEach((btn) => {
    btn.onclick = async () => {
      closeFloatingMenu();
      const conv = store.activate(btn.dataset.conversation);
      if (conv?.mode === 'work') {
        if (conv.projectId) {
          try { await project.activate(conv.projectId, { requestPermission: true, quiet: true }); } catch {}
        } else if (project.id) await project.deactivate({ quiet: true });
      }
      artifacts.close();
      closeMobileSidebar();
      renderAll();
    };
  });
  els.recents.querySelectorAll('[data-conversation-menu]').forEach((btn) => {
    btn.onclick = (event) => {
      event.stopPropagation();
      openConversationMenu(btn.dataset.conversationMenu, btn);
    };
  });
}

function renderToolEvents(tools = []) {
  const rows = [];
  const pending = [];

  for (const tool of tools) {
    if (tool.phase === 'call') {
      pending.push(tool);
      continue;
    }
    if (tool.phase !== 'result') continue;

    // Pair the result with the most recent unresolved call of the same tool so
    // the UI shows one compact lifecycle row instead of a call/result duplicate.
    const idx = [...pending].reverse().findIndex((p) => p.name === tool.name);
    if (idx >= 0) pending.splice(pending.length - 1 - idx, 1);
    rows.push({ ...tool, pending: false });
  }
  rows.push(...pending.map((tool) => ({ ...tool, pending: true })));

  if (!rows.length) return '';
  return `<div class="tool-events">${rows.map((tool) => `
    <div class="tool-event ${tool.pending ? 'pending' : ''} ${tool.result?.error ? 'error' : ''}">
      <span class="tool-icon">${tool.pending ? '<span class="mini-spinner"></span>' : (tool.result?.error ? '!' : '✓')}</span>
      <span class="tool-copy"><strong>${escapeHtml(tool.pending ? toolPendingLabel(tool.name) : toolLabel(tool.name))}</strong>${toolDetail(tool) ? `<small>${escapeHtml(toolDetail(tool))}</small>` : ''}</span>
    </div>`).join('')}</div>`;
}

function formatCompactNumber(value = 0) {
  const n = Number(value) || 0;
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}m`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}k`;
  return String(Math.round(n));
}

function formatElapsed(ms = 0) {
  const seconds = Math.max(0, Number(ms) || 0) / 1000;
  return seconds < 10 ? `${seconds.toFixed(1)}s` : `${Math.round(seconds)}s`;
}

function isNearBottom() {
  const distance = els.scroller.scrollHeight - els.scroller.scrollTop - els.scroller.clientHeight;
  return distance < 130;
}

function scrollConversation({ force = false } = {}) {
  if (force || isNearBottom()) els.scroller.scrollTop = els.scroller.scrollHeight;
}

function reasoningHtml(message, { streaming = false } = {}) {
  const reasoning = String(message.reasoning || '').trim();
  const elapsed = formatElapsed(message.elapsedMs || 0);
  if (!reasoning) return '';
  const live = streaming && message.live;
  const summary = live ? `Thinking · ${elapsed}` : `Thought for ${elapsed}`;
  const ui = reasoningUiState.get(message.id) || { open: false, follow: true };
  return `<details class="reasoning ${live ? 'live' : ''}" data-reasoning-id="${message.id}" ${ui.open ? 'open' : ''}><summary><span class="thinking-dot"></span><span>${summary}</span></summary><div class="reasoning-body">${escapeHtml(reasoning)}</div></details>`;
}

function reasoningState(messageId) {
  let state = reasoningUiState.get(messageId);
  if (!state) {
    state = { open: false, follow: true };
    reasoningUiState.set(messageId, state);
  }
  return state;
}

function bindReasoningInteractions(root = document) {
  root.querySelectorAll?.('.reasoning[data-reasoning-id]').forEach((details) => {
    if (details.dataset.reasoningBound === '1') return;
    details.dataset.reasoningBound = '1';
    const messageId = details.dataset.reasoningId;
    const body = details.querySelector('.reasoning-body');
    const state = reasoningState(messageId);
    details.open = !!state.open;

    details.addEventListener('toggle', () => {
      state.open = details.open;
      if (details.open) {
        // Opening a live thought should immediately reveal the newest token and
        // then keep following it, exactly like a streaming terminal tail.
        state.follow = true;
        requestAnimationFrame(() => {
          const currentBody = details.querySelector('.reasoning-body');
          if (currentBody) currentBody.scrollTop = currentBody.scrollHeight;
        });
      }
    });

    body?.addEventListener('scroll', () => {
      const distance = body.scrollHeight - body.scrollTop - body.clientHeight;
      state.follow = distance < 28;
    }, { passive: true });
  });
}

function updateReasoningDom(row, message, { streaming = false } = {}) {
  const slot = row?.querySelector('.reasoning-slot');
  if (!slot) return;
  const text = String(message.reasoning || '').trim();
  if (!text) {
    slot.innerHTML = '';
    return;
  }

  const live = streaming && message.live;
  const elapsed = formatElapsed(message.elapsedMs || 0);
  const summaryText = live ? `Thinking · ${elapsed}` : `Thought for ${elapsed}`;
  let details = slot.querySelector('.reasoning[data-reasoning-id]');
  if (!details) {
    slot.innerHTML = reasoningHtml(message, { streaming });
    bindReasoningInteractions(slot);
    details = slot.querySelector('.reasoning[data-reasoning-id]');
  }
  if (!details) return;

  const state = reasoningState(message.id);
  details.classList.toggle('live', live);
  details.open = !!state.open;
  const summary = details.querySelector('summary span:nth-child(2)');
  if (summary) summary.textContent = summaryText;
  const body = details.querySelector('.reasoning-body');
  if (body && body.textContent !== text) {
    const previousTop = body.scrollTop;
    body.textContent = text;
    if (!state.follow) body.scrollTop = previousTop;
  }

  if (body && details.open && state.follow) {
    requestAnimationFrame(() => {
      // Do not replace the <details> node while tokens stream. Replacing it was
      // resetting the internal scrollbar to the top on every token.
      body.scrollTop = body.scrollHeight;
    });
  }
}

function activityHtml(message) {
  if (!message.live) return '';
  const label = escapeHtml(message.activity || 'Thinking');
  const phase = escapeHtml(message.phase || 'prefill');
  return `<div class="live-activity ${phase}"><span class="activity-orb"><span></span></span><span class="activity-label">${label}</span><span class="activity-elapsed">${formatElapsed(message.elapsedMs || 0)}</span></div>`;
}

function skillsHtml(message) {
  const skills = Array.isArray(message?.skills) ? message.skills.filter((item) => item?.name) : [];
  const memories = Array.isArray(message?.memories) ? message.memories.filter((item) => item?.content || item?.title) : [];
  const crew = Array.isArray(message?.crew) ? message.crew.filter((item) => item?.role && item?.status === 'done') : [];
  const blocks = [];
  if (skills.length) {
    const names = skills.map((item) => String(item.name)).slice(0, 6);
    const automatic = skills.filter((item) => item.reason === 'auto').length;
    const title = `${names.join(' · ')}${automatic ? ` · ${automatic} auto-selected` : ''}`;
    blocks.push(`<div class="message-skills" title="${escapeHtml(title)}">${icon('sparkles', 13)}<span>Skills</span><strong>${escapeHtml(names.join(' · '))}</strong></div>`);
  }
  if (memories.length) {
    const names = memories.slice(0, 4).map((item) => item.title || item.content).filter(Boolean);
    blocks.push(`<div class="message-skills message-memory" title="${escapeHtml(names.join(' · '))}">${icon('memory', 13)}<span>Memory</span><strong>${memories.length} recalled</strong></div>`);
  }
  if (crew.length) {
    const names = [...new Set(crew.map((item) => item.role))].slice(0, 4);
    blocks.push(`<div class="message-skills message-crew" title="${escapeHtml(names.join(' · '))}">${icon('work', 13)}<span>Crew</span><strong>${escapeHtml(names.join(' · '))}</strong></div>`);
  }
  return blocks.join('');
}

function formatInferenceCaption(metrics = lastInferenceMetrics) {
  if (!metrics) return runtime.inferenceLabel;
  const ctx = Number(metrics.contextSize || runtime.contextSize || 0);
  const used = Number(metrics.used || 0);
  const gen = Number(metrics.generationTpsLive || metrics.generationTps || 0);
  const prompt = Number(metrics.promptTps || 0);
  const speed = gen > 0 ? `${gen.toFixed(gen >= 100 ? 0 : 1)} tok/s` : prompt > 0 ? `${prompt.toFixed(prompt >= 100 ? 0 : 1)} tok/s prefill` : '';
  const context = ctx ? `${formatCompactNumber(used)} / ${formatCompactNumber(ctx)} ctx` : '';
  return [speed, context].filter(Boolean).join(' · ') || runtime.inferenceLabel;
}

function updateInferenceCaption(metrics = lastInferenceMetrics) {
  if (metrics) lastInferenceMetrics = { ...(lastInferenceMetrics || {}), ...metrics };
  els.composerCaption.textContent = formatInferenceCaption(lastInferenceMetrics);
  const m = lastInferenceMetrics;
  if (m) {
    const remaining = Number(m.remaining || 0);
    const cache = Number(m.cachedTokens || 0);
    const live = Number(m.generationTpsLive || 0);
    const average = Number(m.generationTpsAverage || m.generationTps || 0);
    els.composerCaption.title = [
      m.promptTps ? `Prefill ${m.promptTps.toFixed(1)} tok/s` : '',
      live ? `Generation ${live.toFixed(1)} tok/s live (3s)` : m.generationTps ? `Generation ${m.generationTps.toFixed(1)} tok/s` : '',
      live && average ? `Average ${average.toFixed(1)} tok/s` : '',
      cache ? `${formatCompactNumber(cache)} cached tokens` : '',
      m.contextSize ? `${formatCompactNumber(remaining)} context tokens remaining` : '',
    ].filter(Boolean).join(' · ');
  } else {
    els.composerCaption.title = '';
  }
  syncContextUi();
}

const CONTEXT_PRESETS = Object.freeze([8192, 16384, 32768, 65536, 131072, 262144]);

function currentContextSize() {
  return Number(lastInferenceMetrics?.contextSize || runtime.contextSize || (runtime.isLocal ? store.state.settings.context : 0)) || 0;
}

function syncContextSelect(value) {
  if (!els.contextSelect) return;
  const current = Number(value || 0);
  const values = [...CONTEXT_PRESETS];
  if (current > 0 && !values.includes(current)) values.push(current);
  values.sort((a, b) => a - b);
  els.contextSelect.innerHTML = values.map((size) => `<option value="${size}" ${size === current ? 'selected' : ''}>${formatCompactNumber(size)} tokens</option>`).join('');
}

function syncContextUi() {
  if (!els.contextMeterBtn) return;
  const ctx = currentContextSize();
  const used = Number(lastInferenceMetrics?.used || 0);
  const remaining = ctx > 0 ? Math.max(0, ctx - used) : 0;
  const pct = ctx > 0 ? Math.max(0, Math.min(100, (used / ctx) * 100)) : 0;
  const pctLabel = `${Math.round(pct)}%`;
  const output = runtime.isApi
    ? 0
    : Number(store.state.settings.maxTokens || runtime.sampling?.max_tokens || 0);
  const live = Number(lastInferenceMetrics?.generationTpsLive || lastInferenceMetrics?.generationTps || 0);
  const average = Number(lastInferenceMetrics?.generationTpsAverage || 0);

  els.contextMeterRing.style.setProperty('--ctx-pct', `${pct}%`);
  els.contextOverviewRing.style.setProperty('--ctx-pct', `${pct}%`);
  els.contextPercent.textContent = pctLabel;
  els.contextOverviewPct.textContent = pctLabel;
  els.contextUsed.textContent = used ? formatCompactNumber(used) : '0';
  els.contextRemaining.textContent = ctx ? formatCompactNumber(remaining) : '—';
  els.contextTotal.textContent = ctx ? formatCompactNumber(ctx) : '—';
  els.contextOutput.textContent = runtime.isCodex
    ? 'Account'
    : runtime.isOpenAICompatibleApi
      ? (runtime.api?.isLlamaCpp ? 'Server' : 'Provider')
      : (output ? formatCompactNumber(output) : '—');
  const cached = Number(lastInferenceMetrics?.cachedTokens || 0);
  const prefill = Number(lastInferenceMetrics?.promptTps || 0);
  els.contextCached.textContent = cached ? formatCompactNumber(cached) : '—';
  els.contextPrefill.textContent = prefill ? `${prefill.toFixed(prefill >= 100 ? 0 : 1)}/s` : '—';
  els.contextSpeed.textContent = live ? `${live.toFixed(1)} tok/s` : '—';
  els.contextAverageSpeed.textContent = average && live ? `avg ${average.toFixed(1)}` : '';
  els.contextMeterBtn.title = ctx
    ? `Context ${formatCompactNumber(used)} / ${formatCompactNumber(ctx)} · ${pctLabel}`
    : 'Context window';

  if (runtime.isCodex) {
    els.contextSource.textContent = `${runtime.codex?.modelMeta?.displayName || runtime.selection?.modelId || 'ChatGPT / Codex'} · account`;
    els.contextSetting.classList.add('readonly');
    els.contextSelect.disabled = true;
    els.contextApplyBtn.disabled = true;
    syncContextSelect(ctx || Number(store.state.settings.context || 32768));
    els.contextNote.textContent = 'Context and output policy are managed by the signed-in ChatGPT / Codex model. BlackRiver never forwards on-device local context, KV-cache, or max-output settings to this account runtime.';
  } else if (runtime.isOpenAICompatibleApi) {
    const isLlama = !!runtime.api?.isLlamaCpp;
    els.contextSource.textContent = isLlama ? `${runtime.api.provider?.name || 'llama.cpp'} · server` : `${runtime.api?.provider?.name || 'API'} · provider`;
    els.contextSetting.classList.add('readonly');
    els.contextSelect.disabled = true;
    els.contextApplyBtn.disabled = true;
    syncContextSelect(ctx || Number(store.state.settings.context || 32768));
    els.contextNote.textContent = isLlama
      ? (ctx ? 'Server context is read from llama.cpp. BlackRiver does not send the on-device local Context/Max output values to this API; your llama.cpp INI/preset remains authoritative.' : 'Context is owned by the llama.cpp server. BlackRiver does not override it; open this panel again after the model is ready to sync it.')
      : 'This provider owns its own context/output policy. On-device local Advanced limits are never forwarded to API providers.';
  } else {
    const loadedName = runtime.local?.loaded?.name || 'BlackRiver Local';
    const localRuntimeName = localRuntime.isAndroidNative ? 'llama.cpp Android' : 'Wllama';
    els.contextSource.textContent = runtime.local?.isLoaded ? `${loadedName} · ${localRuntimeName}` : 'BlackRiver Local · next load';
    els.contextSetting.classList.remove('readonly');
    els.contextSelect.disabled = false;
    els.contextApplyBtn.disabled = false;
    syncContextSelect(ctx || Number(store.state.settings.context || 32768));
    els.contextNote.textContent = `Changing the local window also sets Max output to the same value. A loaded ${localRuntime.isAndroidNative ? 'Android llama.cpp' : 'Wllama'} model must reload; conversations and artifacts stay saved.`;
  }
}

async function refreshContextInfo() {
  if (runtime.isApi) {
    await runtime.refreshActiveModelInfo().catch(() => null);
  }
  syncContextUi();
  syncReasoningUi();
}

function setContextPopover(open) {
  contextPopoverOpen = !!open;
  if (contextPopoverOpen) syncAndroidComposerPopoverAnchor();
  els.contextPopover.classList.toggle('hidden', !contextPopoverOpen);
  els.contextPopover.setAttribute('aria-hidden', String(!contextPopoverOpen));
  els.contextMeterBtn.setAttribute('aria-expanded', String(contextPopoverOpen));
  if (contextPopoverOpen) refreshContextInfo();
}

async function applyContextSelection() {
  if (runtime.isApi) return;
  if (generating) { toast('Stop generation before changing context.', 'info'); return; }
  const value = Math.max(1024, Number(els.contextSelect.value) || 32768);
  const current = Number(runtime.local?.contextSize || store.state.settings.context || 0);
  if (runtime.local?.isLoaded && value !== current) {
    const modelName = runtime.local.loaded?.name || 'the local model';
    const confirmed = window.confirm(`Change context to ${value.toLocaleString()} tokens?\n\n${modelName} must reload to apply the new context. Your Chat/Work conversations and artifacts stay saved.`);
    if (!confirmed) { syncContextUi(); return; }
  }

  store.updateSettings({ context: value, maxTokens: value });
  runtime.setRuntimeParams({ n_ctx: value });
  runtime.setSampling({ max_tokens: value });
  lastInferenceMetrics = null;
  setContextPopover(false);

  if (runtime.local?.isLoaded) {
    try {
      els.contextMeterBtn.disabled = true;
      await runtime.reloadLocalCurrent({ n_ctx: value });
      toast(`Context reloaded · ${formatCompactNumber(value)} tokens`, 'success');
    } catch (error) {
      toast(errorMessage(error), 'error');
    } finally {
      els.contextMeterBtn.disabled = false;
      syncContextUi();
    }
  } else {
    toast(`Context set to ${formatCompactNumber(value)} · applies on next local load`, 'success');
    syncContextUi();
  }
}

function startActivityTicker(message, conversationId = generationConversationId) {
  clearInterval(activityTicker);
  activityTicker = setInterval(() => {
    if (!message.live) return;
    message.elapsedMs = performance.now() - activeTurnStart;
    if (conversationId && store.state.activeConversationId !== conversationId) return;
    const row = document.querySelector(`[data-message-id="${CSS.escape(message.id)}"]`);
    row?.querySelectorAll('.activity-elapsed').forEach((el) => { el.textContent = formatElapsed(message.elapsedMs); });
    const summary = row?.querySelector('.reasoning.live summary span:nth-child(2)');
    if (summary) summary.textContent = `Thinking · ${formatElapsed(message.elapsedMs)}`;
  }, 100);
}

function stopActivityTicker() {
  clearInterval(activityTicker);
  activityTicker = null;
}

function conversationNavigatorSnippet(text, maxLength = 72) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (!clean) return 'Untitled turn';
  return clean.length <= maxLength ? clean : `${clean.slice(0, maxLength - 1).trimEnd()}…`;
}

function collectConversationNavigatorItems() {
  const conv = store.activeConversation;
  if (!conv) return [];
  return (conv.messages || [])
    .map((message, messageIndex) => ({ message, messageIndex }))
    .filter(({ message }) => message.role === 'user' && String(message.content || '').trim())
    .map(({ message, messageIndex }, turnIndex) => ({
      id: message.id,
      messageIndex,
      turnIndex,
      text: conversationNavigatorSnippet(message.content),
    }));
}

function conversationNavigatorMarkerTop(item, fallbackIndex = 0, total = 1) {
  const row = els.messages.querySelector(`[data-message-id="${CSS.escape(item.id)}"]`);
  if (row) {
    const max = Math.max(1, els.scroller.scrollHeight - row.offsetHeight);
    return Math.max(1, Math.min(99, (row.offsetTop / max) * 100));
  }
  return total <= 1 ? 50 : Math.max(1, Math.min(99, (fallbackIndex / (total - 1)) * 100));
}

function conversationNavigatorCurrentIndex() {
  if (!conversationNavItems.length) return -1;
  const anchor = els.scroller.scrollTop + Math.min(els.scroller.clientHeight * 0.34, 280);
  let best = 0;
  for (let i = 0; i < conversationNavItems.length; i += 1) {
    const row = els.messages.querySelector(`[data-message-id="${CSS.escape(conversationNavItems[i].id)}"]`);
    if (!row) continue;
    if (row.offsetTop <= anchor) best = i;
    else break;
  }
  return best;
}

function syncConversationNavigatorActive({ scrollList = false } = {}) {
  if (!conversationNavItems.length) return;
  const next = conversationNavigatorCurrentIndex();
  if (next < 0) return;
  conversationNavActiveIndex = next;
  els.conversationNavigatorRail.querySelectorAll('[data-conversation-nav-marker]').forEach((button, index) => {
    button.classList.toggle('active', index === next);
  });
  els.conversationNavigatorList.querySelectorAll('[data-conversation-nav-item]').forEach((button, index) => {
    button.classList.toggle('active', index === next);
  });
  if (scrollList && conversationNavOpen) {
    els.conversationNavigatorList.querySelector(`[data-conversation-nav-item="${next}"]`)?.scrollIntoView({ block: 'nearest' });
  }
}

function renderConversationNavigator() {
  conversationNavItems = collectConversationNavigatorItems();
  const count = conversationNavItems.length;
  const shouldShow = count > 1;
  els.conversationNavigatorRail.classList.toggle('hidden', !shouldShow);
  if (!shouldShow) {
    setConversationNavigator(false);
    els.conversationNavigatorRail.innerHTML = '';
    els.conversationNavigatorList.innerHTML = '';
    conversationNavActiveIndex = count ? 0 : -1;
    return;
  }

  conversationNavActiveIndex = conversationNavigatorCurrentIndex();
  els.conversationNavigatorRail.innerHTML = conversationNavItems.map((item, index) => (
    `<button type="button" class="conversation-navigator-marker ${index === conversationNavActiveIndex ? 'active' : ''}" style="top:${conversationNavigatorMarkerTop(item, index, count).toFixed(2)}%" data-conversation-nav-marker="${index}" tabindex="-1" aria-label="Jump to turn ${index + 1}"></button>`
  )).join('');

  els.conversationNavigatorList.innerHTML = conversationNavItems.map((item, index) => (
    `<button type="button" class="conversation-navigator-item ${index === conversationNavActiveIndex ? 'active' : ''}" data-conversation-nav-item="${index}" title="${escapeHtml(item.text)}">${escapeHtml(item.text)}</button>`
  )).join('');

  els.conversationNavigatorRail.querySelectorAll('[data-conversation-nav-marker]').forEach((button) => {
    button.onmouseenter = () => {
      clearTimeout(conversationNavCloseTimer);
      const index = Number(button.dataset.conversationNavMarker);
      if (Number.isFinite(index)) {
        conversationNavActiveIndex = index;
        setConversationNavigator(true, { scrollList: true });
      }
    };
    button.onclick = () => { setConversationNavigator(true, { scrollList: true }); goToConversationNavigatorItem(Number(button.dataset.conversationNavMarker)); };
  });
  els.conversationNavigatorList.querySelectorAll('[data-conversation-nav-item]').forEach((button) => {
    button.onclick = () => goToConversationNavigatorItem(Number(button.dataset.conversationNavItem));
  });
  syncConversationNavigatorActive({ scrollList: conversationNavOpen });
}

function queueConversationNavigatorRefresh() {
  if (conversationNavRefreshFrame) return;
  conversationNavRefreshFrame = requestAnimationFrame(() => {
    conversationNavRefreshFrame = 0;
    renderConversationNavigator();
  });
}

function setConversationNavigator(open, { scrollList = true } = {}) {
  conversationNavOpen = !!open && conversationNavItems.length > 1;
  clearTimeout(conversationNavCloseTimer);
  els.conversationNavigatorPanel.classList.toggle('hidden', !conversationNavOpen);
  els.conversationNavigatorPanel.setAttribute('aria-hidden', conversationNavOpen ? 'false' : 'true');
  els.conversationNavigatorRail.classList.toggle('panel-open', conversationNavOpen);
  if (conversationNavOpen && scrollList) {
    requestAnimationFrame(() => {
      els.conversationNavigatorList.querySelector(`[data-conversation-nav-item="${conversationNavActiveIndex}"]`)?.scrollIntoView({ block: 'nearest' });
    });
  }
}

function scheduleConversationNavigatorClose() {
  clearTimeout(conversationNavCloseTimer);
  conversationNavCloseTimer = setTimeout(() => setConversationNavigator(false), 260);
}

function openConversationNavigator() {
  if (conversationNavItems.length <= 1) renderConversationNavigator();
  if (conversationNavItems.length <= 1) return toast('Add another turn to use the conversation navigator.', 'info');
  syncConversationNavigatorActive();
  setConversationNavigator(true, { scrollList: true });
}

function goToConversationNavigatorItem(index, { smooth = true } = {}) {
  if (!conversationNavItems.length) return;
  const total = conversationNavItems.length;
  conversationNavActiveIndex = ((Number(index) || 0) % total + total) % total;
  const item = conversationNavItems[conversationNavActiveIndex];
  const row = els.messages.querySelector(`[data-message-id="${CSS.escape(item.id)}"]`);
  if (row) row.scrollIntoView({ block: 'center', behavior: smooth ? 'smooth' : 'auto' });
  els.conversationNavigatorRail.querySelectorAll('[data-conversation-nav-marker]').forEach((button, i) => button.classList.toggle('active', i === conversationNavActiveIndex));
  els.conversationNavigatorList.querySelectorAll('[data-conversation-nav-item]').forEach((button, i) => button.classList.toggle('active', i === conversationNavActiveIndex));
  els.conversationNavigatorList.querySelector(`[data-conversation-nav-item="${conversationNavActiveIndex}"]`)?.scrollIntoView({ block: 'nearest' });
}

function artifactPayloadBytes(item) {
  if (!item) return 0;
  if (item.type === 'document') { try { return renderDocumentBytes({ format: item.documentFormat, title: item.title, content: item.content }).byteLength; } catch { return new Blob([String(item.content || '')]).size; } }
  if (item.type === 'bundle') return (item.files || []).reduce((sum, file) => {
    if (file.mime === 'application/x-blackriver-document-ref') {
      const ref = String(file.content || '').split(':').slice(1).join(':');
      const doc = artifacts.get(ref);
      if (doc?.type === 'document') { try { return sum + renderDocumentBytes({ format: doc.documentFormat, title: doc.title, content: doc.content }).byteLength; } catch {} }
    }
    return sum + new Blob([String(file.content || '')]).size;
  }, 0);
  return new Blob([String(item.content || '')]).size;
}

function artifactDownloadMeta(item) {
  if (!item) return '';
  if (item.type === 'bundle') return `ZIP · ${(item.files || []).length} file${(item.files || []).length === 1 ? '' : 's'} · ${humanBytes(artifactPayloadBytes(item))}`;
  if (item.type === 'document') return `${String(item.documentFormat || 'doc').toUpperCase()} · ${humanBytes(artifactPayloadBytes(item))}`;
  const ext = String(item.filename || '').split('.').pop()?.toUpperCase() || item.type.toUpperCase();
  return `${ext} · ${humanBytes(artifactPayloadBytes(item))}`;
}

function base64Bytes(value = '') {
  const binary = atob(String(value || ''));
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

async function renderDocumentBlobAsync({ format, title, content, filename = '' } = {}) {
  const bridge = nativeCore();
  if (nativeAvailable() && typeof bridge?.createDocument === 'function') {
    const generated = await bridge.createDocument({ format, title, content, filename });
    if (generated?.base64) return new Blob([base64Bytes(generated.base64)], { type: generated.mime || documentMime(format) });
  }
  return documentBlob({ format, title, content });
}

async function renderDocumentBytesAsync(spec = {}) {
  const blob = await renderDocumentBlobAsync(spec);
  return new Uint8Array(await blob.arrayBuffer());
}

async function downloadArtifactItem(item) {
  if (!item) return;
  let blob;
  let filename;
  if (item.type === 'bundle') {
    const files = [];
    for (const file of item.files || []) {
      if (file.mime !== 'application/x-blackriver-document-ref') { files.push(file); continue; }
      const ref = String(file.content || '').split(':').slice(1).join(':');
      const doc = artifacts.get(ref);
      if (!doc || doc.type !== 'document') { files.push({ ...file, content: 'Missing BlackRiver document reference.' }); continue; }
      files.push({
        path: file.path || doc.filename,
        content: await renderDocumentBytesAsync({ format: doc.documentFormat, title: doc.title, content: doc.content, filename: doc.filename }),
        mime: documentMime(doc.documentFormat),
      });
    }
    blob = createZipBlob(files);
    const base = normalizeDownloadName(String(item.filename || item.title || 'artifact').replace(/\.zip$/i, ''));
    filename = `${base}.zip`;
  } else if (item.type === 'document') {
    blob = await renderDocumentBlobAsync({ format: item.documentFormat, title: item.title, content: item.content, filename: item.filename });
    const ext = String(item.documentFormat || 'pdf').toLowerCase();
    const base = String(item.filename || `${item.title || 'document'}.${ext}`);
    filename = normalizeDownloadName(base.replaceAll('/', '-'));
    if (!filename.toLowerCase().endsWith(`.${ext}`)) filename += `.${ext}`;
  } else if (item.type === 'file') {
    blob = new Blob([String(item.content || '')], { type: item.mime || 'application/octet-stream' });
    filename = normalizeDownloadName((item.filename || `${item.title || 'artifact'}.txt`).replaceAll('/', '-'));
  } else {
    const ext = item.type === 'html' ? 'html' : item.language || (item.type === 'markdown' ? 'md' : 'txt');
    blob = new Blob([item.content], { type: item.type === 'html' ? 'text/html' : 'text/plain' });
    filename = `${normalizeDownloadName(item.title)}.${ext}`;
  }
  if (localRuntime.isAndroidNative) {
    const mobile = androidMobilePlugin();
    if (!mobile?.saveFile) throw new Error('Android download bridge is unavailable in this build.');
    const base64 = await blobToBase64(blob);
    const saved = await mobile.saveFile({
      filename,
      mime: blob.type || 'application/octet-stream',
      base64,
    });
    toast(`Saved to ${saved?.location || `Downloads/BlackRiver/${filename}`}`, 'success');
    return;
  }

  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1200);
}

function downloadArtifactSafely(item) {
  downloadArtifactItem(item).catch((error) => toast(errorMessage(error, 'Artifact download failed.'), 'error'));
}

function messageArtifactCardsHtml(message) {
  const ids = Array.isArray(message?.artifactIds) ? [...new Set(message.artifactIds)] : [];
  const items = ids.map((id) => artifacts.get(id)).filter((item) => item && (item.type === 'file' || item.type === 'bundle' || item.type === 'document'));
  if (!items.length) return '';
  return `<div class="message-file-artifacts">${items.map((item) => `
    <button type="button" class="message-file-card" data-download-message-artifact="${escapeHtml(item.id)}" title="Download ${escapeHtml(item.filename || item.title)}">
      <span class="message-file-icon">${item.type === 'bundle' ? 'ZIP' : item.type === 'document' ? String(item.documentFormat || 'DOC').toUpperCase() : icon('file', 17)}</span>
      <span class="message-file-copy"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(artifactDownloadMeta(item))}</small></span>
      <span class="message-file-download">${icon('download', 16)}</span>
    </button>`).join('')}</div>`;
}

function bindMessageArtifactDownloads(root = document) {
  root.querySelectorAll?.('[data-download-message-artifact]').forEach((button) => {
    if (button.dataset.downloadBound === '1') return;
    button.dataset.downloadBound = '1';
    button.onclick = () => downloadArtifactSafely(artifacts.get(button.dataset.downloadMessageArtifact));
  });
}

function verificationEvidence(message) {
  const events = Array.isArray(message?.tools) ? message.tools : [];
  const successful = (name) => events.filter((event) => event.phase === 'result' && event.name === name && !event.result?.error);
  const project = successful('verify_project').some((event) => event.result?.ok === true);
  const browserNames = ['browser_click','browser_type','browser_key','browser_scroll','browser_wait','browser_snapshot','browser_inspect','browser_console'];
  const browser = browserNames.some((name) => successful(name).length);
  const waited = successful('browser_wait').length > 0;
  const consoleClean = successful('browser_console').some((event) => Array.isArray(event.result?.diagnostics) && !event.result.diagnostics.some((d) => String(d?.level || '').toLowerCase() === 'error'));
  const artifactChecks = events.filter((event) => event.phase === 'result' && ['create_artifact','update_artifact'].includes(event.name)).map((event) => event.result?.preview_check).filter(Boolean);
  const artifactHealthy = artifactChecks.some((check) => check.healthy === true);
  const verified = project || (artifactHealthy && browser && consoleClean);
  return { verified, project, browser, waited, consoleClean, artifactHealthy };
}

function workResultActionsHtml(message) {
  if (!message || message.live) return '';
  const conv = store.activeConversation;
  const projectId = conv?.projectId || project.id || '';
  const record = projectId ? project.store.get(projectId) : null;
  const checkpoint = message.checkpointId ? record?.checkpoints?.find((item) => item.id === message.checkpointId && item.files?.length) : null;
  const evidence = verificationEvidence(message);
  const verified = evidence.verified ? `<button type="button" class="verified-result" data-work-result="verified" data-evidence='${escapeHtml(JSON.stringify(evidence))}' title="Show verification evidence">✓<span>Verified</span></button>` : '';
  const changes = checkpoint ? `<button type="button" data-work-result="changes" data-checkpoint="${escapeHtml(checkpoint.id)}">${icon('edit', 13)}<span>${checkpoint.files.length} changed</span></button><button type="button" data-work-result="undo" data-checkpoint="${escapeHtml(checkpoint.id)}">${icon('refresh', 13)}<span>Undo</span></button>` : '';
  if (!verified && !changes) return '';
  return `<div class="work-result-actions" aria-label="Work result actions">${verified}${changes}</div>`;
}

async function activateConversationProjectForAction() {
  const projectId = store.activeConversation?.projectId || null;
  if (projectId && project.id !== projectId) await project.activate(projectId, { requestPermission: true, quiet: true });
  return projectId;
}

function bindWorkResultActions(root = document) {
  root.querySelectorAll?.('[data-work-result]').forEach((button) => {
    if (button.dataset.workResultBound === '1') return;
    button.dataset.workResultBound = '1';
    button.onclick = async () => {
      if (generating) return toast('Finish the current Work run first.', 'info');
      try {
        const projectId = await activateConversationProjectForAction();
        const checkpointId = button.dataset.checkpoint || '';
        if (button.dataset.workResult === 'verified') {
          const evidence = JSON.parse(button.dataset.evidence || '{}');
          return modalShell('Verified', `<div class="verified-sheet"><div class="verified-hero">✓ Verified by BlackRiver</div><div class="verified-grid"><div class="verified-row"><strong>Project checks</strong><span>Native project verification</span><em>${evidence.project ? 'Passed' : '—'}</em></div><div class="verified-row"><strong>Artifact runtime</strong><span>Latest saved Artifact revision</span><em>${evidence.artifactHealthy ? 'Healthy' : '—'}</em></div><div class="verified-row"><strong>Interaction QA</strong><span>Browser Lab observation</span><em>${evidence.browser ? 'Observed' : '—'}</em></div><div class="verified-row"><strong>Timed runtime</strong><span>Post-update behavioral wait</span><em>${evidence.waited ? 'Observed' : '—'}</em></div><div class="verified-row"><strong>Console</strong><span>Runtime diagnostics</span><em>${evidence.consoleClean ? 'Clean' : '—'}</em></div></div></div>`);
        }
        if (button.dataset.workResult === 'changes') return renderProjectsModal();
        const record = projectId ? project.store.get(projectId) : project.activeProject;
        const checkpoint = record?.checkpoints?.find((item) => item.id === checkpointId);
        if (!checkpoint?.files?.length) return toast('This checkpoint is no longer available.', 'info');
        if (!window.confirm(`Undo this BlackRiver Work session?

${checkpoint.files.length} file${checkpoint.files.length === 1 ? '' : 's'} will be restored.`)) return;
        await project.undoCheckpoint(checkpointId);
        renderAll();
        toast('Work session restored.', 'success');
      } catch (error) { toast(errorMessage(error), 'error'); }
    };
  });
}

function messageActionsHtml(message) {
  if (message.live) return '';
  if (message.role === 'user') {
    return `<div class="message-actions user-actions" aria-label="Message actions">
      <button type="button" data-message-action="copy" data-message-target="${message.id}" title="Copy" aria-label="Copy message">${icon('copy', 15)}</button>
      <button type="button" data-message-action="edit" data-message-target="${message.id}" title="Edit" aria-label="Edit message">${icon('edit', 15)}</button>
      <button type="button" data-message-action="delete" data-message-target="${message.id}" title="Delete" aria-label="Delete message">${icon('trash', 15)}</button>
    </div>`;
  }
  const continuation = message.maxTurnsReached ? `<span class="work-continuation-actions">
      <button type="button" class="continue-work-button" data-message-action="continue-work" data-message-target="${message.id}" title="Continue the current Work goal">Continue</button>
      <button type="button" class="yolo-work-button" data-message-action="yolo-work" data-message-target="${message.id}" title="Continue in YOLO mode until the goal is reached">YOLO run</button>
    </span>` : '';
  return `<div class="message-actions assistant-actions ${message.maxTurnsReached ? 'has-continuation' : ''}" aria-label="Response actions">
    ${continuation}
    <button type="button" data-message-action="copy" data-message-target="${message.id}" title="Copy" aria-label="Copy response">${icon('copy', 15)}</button>
    <button type="button" data-message-action="regenerate" data-message-target="${message.id}" title="Regenerate" aria-label="Regenerate response">${icon('refresh', 15)}</button>
    <button type="button" data-message-action="delete" data-message-target="${message.id}" title="Delete" aria-label="Delete response">${icon('trash', 15)}</button>
  </div>`;
}

function findActiveMessage(messageId) {
  const conv = store.activeConversation;
  const index = conv?.messages.findIndex((m) => m.id === messageId) ?? -1;
  return { conv, index, message: index >= 0 ? conv.messages[index] : null };
}

async function copyMessage(messageId) {
  const { message } = findActiveMessage(messageId);
  if (!message) return;
  try {
    await navigator.clipboard.writeText(String(message.content || ''));
    toast('Copied.', 'success');
  } catch {
    toast('Could not copy this message.', 'error');
  }
}

function editUserMessage(messageId) {
  if (generating) return toast('Stop the current generation before editing a message.', 'info');
  const { message } = findActiveMessage(messageId);
  if (!message || message.role !== 'user') return;
  const text = String(message.content || '');
  const hadAttachment = !!message.attachmentName;
  store.truncateFromMessage(messageId);
  els.promptInput.value = text;
  autoResizeComposer();
  renderConversation();
  els.promptInput.focus();
  els.promptInput.setSelectionRange?.(text.length, text.length);
  if (hadAttachment) toast('Message moved back to the composer. Reattach the original file if needed.', 'info');
}

function openDeleteMessage(messageId) {
  if (generating) return toast('Stop the current generation before deleting a message.', 'info');
  const { message } = findActiveMessage(messageId);
  if (!message) return;
  const isUser = message.role === 'user';
  modalShell(isUser ? 'Delete message and response?' : 'Delete response?', `
    <div class="confirm-dialog">
      <p>${isUser ? 'This user message and its following response will be removed from the conversation.' : 'This response will be removed from the conversation.'}</p>
      <div class="modal-actions">
        <button class="secondary-button" type="button" id="deleteMessageCancel">Cancel</button>
        <button class="danger-button" type="button" id="deleteMessageConfirm">Delete</button>
      </div>
    </div>`);
  document.getElementById('deleteMessageCancel').onclick = closeModal;
  document.getElementById('deleteMessageConfirm').onclick = () => {
    store.deleteMessage(messageId, { withResponse: isUser });
    reasoningUiState.delete(messageId);
    closeModal();
    renderConversation();
    toast('Message deleted.', 'success');
  };
}

function regenerateAssistant(messageId) {
  if (generating) return toast('A generation is already running.', 'info');
  const { conv, index, message } = findActiveMessage(messageId);
  if (!conv || !message || message.role !== 'assistant' || index < 1) return;
  let userIndex = index - 1;
  while (userIndex >= 0 && conv.messages[userIndex]?.role !== 'user') userIndex -= 1;
  const user = conv.messages[userIndex];
  if (!user) return toast('Could not find the user message for this response.', 'error');
  if (user.attachmentName) return toast('Reattach the original file before regenerating this response.', 'info');
  const text = String(user.content || '');
  store.truncateFromMessage(user.id);
  els.promptInput.value = text;
  autoResizeComposer();
  renderConversation();
  sendPrompt();
}

async function continueWorkFromMessage(messageId, { yolo = false } = {}) {
  if (generating) return toast('A Work run is already active.', 'info');
  const { conv, message } = findActiveMessage(messageId);
  if (!conv || !message || message.role !== 'assistant') return;
  if (conv.mode !== 'work') return toast('Continue is available for Work tasks.', 'info');
  if (yolo) {
    store.setYoloMode(true);
    syncYoloUi();
  }
  const goal = store.getConversationGoal(conv.id);
  const instruction = `Continue the current BlackRiver Work task from the exact existing state. Do not restart or redo completed work. Inspect the latest artifact/project state and prior tool outcomes, then continue until the user's ${goal ? `persistent goal (${goal})` : 'requested goal'} is actually completed and verified. ${yolo ? 'YOLO mode is enabled: keep working autonomously; do not stop just to report progress.' : 'Finish the remaining work and verify it before stopping.'}`;
  await sendPrompt({ internal: true, text: instruction });
}

function bindMessageActions(root = document) {
  root.querySelectorAll?.('[data-message-action]').forEach((button) => {
    if (button.dataset.messageActionBound === '1') return;
    button.dataset.messageActionBound = '1';
    button.onclick = (event) => {
      event.stopPropagation();
      const id = button.dataset.messageTarget;
      const action = button.dataset.messageAction;
      if (action === 'copy') copyMessage(id);
      else if (action === 'edit') editUserMessage(id);
      else if (action === 'regenerate') regenerateAssistant(id);
      else if (action === 'continue-work') continueWorkFromMessage(id);
      else if (action === 'yolo-work') continueWorkFromMessage(id, { yolo: true });
      else if (action === 'delete') openDeleteMessage(id);
    };
  });
}

function renderConversation() {
  const conv = store.activeConversation;
  const messages = (conv?.messages || []).filter((message) => !message.hidden);
  els.messages.innerHTML = messages.map((m) => {
    if (m.role === 'user') {
      return `<article class="message-row user-row" data-message-id="${m.id}">
        <div class="user-message-wrap">
          <div class="user-bubble">${escapeHtml(m.content || '')}${m.attachmentName ? `<div class="attached-name">${icon('clip', 14)} ${escapeHtml(m.attachmentName)}</div>` : ''}</div>
          ${messageActionsHtml(m)}
        </div>
      </article>`;
    }
    const activity = activityHtml(m);
    const reasoning = reasoningHtml(m, { streaming: !!m.live });
    const skills = skillsHtml(m);
    const tools = renderToolEvents(m.tools || []);
    return `<article class="message-row assistant-row ${m.live ? 'live-message' : ''}" data-message-id="${m.id}">
      <img src="/blackriver-mark.svg" alt="" class="assistant-mark" />
      <div class="assistant-content"><div class="activity-slot">${activity}</div><div class="reasoning-slot">${reasoning}</div><div class="skills-slot">${skills}</div><div class="tools-slot">${tools}</div><div class="markdown ${m.live ? 'streaming' : ''}">${renderMarkdown(m.content || '', { streaming: !!m.live })}</div><div class="message-artifacts-slot">${messageArtifactCardsHtml(m)}</div>${workResultActionsHtml(m)}${messageActionsHtml(m)}</div>
    </article>`;
  }).join('');
  renderEmptyState();
  requestAnimationFrame(() => scrollConversation({ force: true }));
  bindCopyButtons();
  bindMessageActions(els.messages);
  bindMessageArtifactDownloads(els.messages);
  bindWorkResultActions(els.messages);
  bindReasoningInteractions(els.messages);
  bindBlackRiverPeek(els.messages);
  queueConversationNavigatorRefresh();
}

function bindCopyButtons() {
  document.querySelectorAll('[data-copy-code]').forEach((btn) => {
    btn.onclick = async () => {
      const code = btn.closest('.code-block')?.querySelector('code')?.textContent || '';
      await navigator.clipboard?.writeText(code);
      btn.textContent = 'Copied';
      setTimeout(() => btn.textContent = 'Copy', 900);
    };
  });
}

function updateAssistantDom(message, { streaming = false, conversationId = null } = {}) {
  // A generation may keep running while the user browses another Chat/Work.
  // Never let background stream updates rebuild or scroll the conversation that
  // is currently on screen. The message object still updates in the store and
  // will render at its latest state when the user returns to that conversation.
  if (conversationId && store.state.activeConversationId !== conversationId) return;
  const row = document.querySelector(`[data-message-id="${CSS.escape(message.id)}"]`);
  if (!row) return renderConversation();
  const follow = isNearBottom();

  const activitySlot = row.querySelector('.activity-slot');
  const skillsSlot = row.querySelector('.skills-slot');
  const toolsSlot = row.querySelector('.tools-slot');
  const markdown = row.querySelector('.markdown');
  const artifactsSlot = row.querySelector('.message-artifacts-slot');
  if (!markdown) return renderConversation();

  row.classList.toggle('live-message', !!message.live);
  if (activitySlot) activitySlot.innerHTML = activityHtml(message);
  updateReasoningDom(row, message, { streaming });
  if (skillsSlot) skillsSlot.innerHTML = skillsHtml(message);
  if (toolsSlot) toolsSlot.innerHTML = renderToolEvents(message.tools || []);

  // Incremental Markdown, not a raw text dump. Incomplete fenced code blocks are
  // virtually closed for rendering so the stream stays formatted while tokens arrive.
  markdown.classList.toggle('streaming', streaming);
  markdown.innerHTML = renderMarkdown(message.content || '', { streaming });
  if (artifactsSlot) {
    artifactsSlot.innerHTML = messageArtifactCardsHtml(message);
    // A downloadable artifact can complete before the assistant's final text.
    // Bind the card immediately so the user can download it while the response
    // is still streaming instead of waiting for the whole turn to finish.
    bindMessageArtifactDownloads(artifactsSlot);
  }

  let actions = row.querySelector('.message-actions');
  if (!message.live && !actions) {
    row.querySelector('.assistant-content')?.insertAdjacentHTML('beforeend', messageActionsHtml(message));
    actions = row.querySelector('.message-actions');
  }
  if (message.live && actions) actions.remove();

  if (!streaming) {
    const existingWorkActions = row.querySelector('.work-result-actions');
    if (message.checkpointId && !existingWorkActions) {
      const slot = row.querySelector('.message-artifacts-slot');
      slot?.insertAdjacentHTML('afterend', workResultActionsHtml(message));
    }
    bindCopyButtons();
    bindMessageActions(row);
    bindMessageArtifactDownloads(row);
    bindWorkResultActions(row);
    bindBlackRiverPeek(row);
  }
  queueConversationNavigatorRefresh();
  if (follow) requestAnimationFrame(() => scrollConversation());
}

function queueAssistantDomUpdate(message, conversationId = generationConversationId) {
  if (conversationId && store.state.activeConversationId !== conversationId) return;
  if (streamFrames.has(message.id)) return;
  streamFrames.set(message.id, requestAnimationFrame(() => {
    streamFrames.delete(message.id);
    if (conversationId && store.state.activeConversationId !== conversationId) return;
    updateAssistantDom(message, { streaming: generating, conversationId });
  }));
}

function refreshRuntimeUi(detail = null) {
  const hardware = runtime.hardware;
  if (runtime.isLoaded) {
    els.modelName.textContent = runtime.autoEnabled ? 'Auto' : (runtime.loaded?.name || 'Loaded model');
    els.runtimeText.textContent = runtime.backendLabel;
    els.runtimeChip.classList.toggle('warning', runtime.isLocal && !hardware.adapter);
  } else {
    els.modelName.textContent = 'Choose model';
    els.runtimeText.textContent = runtime.isApi ? (runtime.backendLabel || 'API') : localRuntime.isAndroidNative ? 'Local · Android llama.cpp' : (hardware.checked ? (hardware.adapter ? 'Local · WebGPU' : 'Local') : 'Local');
    els.runtimeChip.classList.remove('warning');
  }
  if (detail?.state === 'downloading') {
    els.composerCaption.textContent = detail.message || 'Downloading model…';
  } else if (['loading', 'staging'].includes(detail?.state)) {
    els.composerCaption.textContent = detail.message || 'Loading model…';
  } else if (!generating) {
    updateInferenceCaption(lastInferenceMetrics);
  }
  syncContextUi();
}

function quickModelIsActive(item) {
  if (!item) return false;
  if (item.kind === 'auto') return !!runtime.autoEnabled;
  if (runtime.autoEnabled) return false;
  if (item.kind === 'local') return runtime.selection?.kind === 'wllama';
  if (item.kind === 'codex') return runtime.selection?.kind === 'codex' && runtime.selection?.modelId === item.modelId;
  return runtime.selection?.kind === 'api' && runtime.selection?.providerId === item.providerId && runtime.selection?.modelId === item.modelId;
}

function quickModelGroups() {
  const groups = [{ id: 'auto', label: 'Routing', items: [{ kind: 'auto', modelId: 'auto', label: 'Auto', detail: runtime.localIsLoaded ? 'Local-first · current provider fallback' : 'Current provider · automatic fallback' }] }];
  if (runtime.localIsLoaded && runtime.local?.loaded) {
    groups.push({
      id: 'local', label: 'On device',
      items: [{
        kind: 'local',
        modelId: runtime.local.loaded.name || 'Local model',
        label: runtime.local.loaded.name || 'Local model',
        detail: localRuntime.isAndroidNative
          ? `llama.cpp Android · ${String(runtime.local.hardware?.backend || runtime.local.loaded?.backend || 'cpu').toUpperCase()}`
          : (runtime.local.hardware?.adapter ? 'Wllama · WebGPU' : 'Wllama · Local'),
      }],
    });
  }

  for (const provider of providerStore.list()) {
    const models = Array.isArray(provider.modelIds) ? provider.modelIds : [];
    if (!models.length) continue;
    groups.push({
      id: `api:${provider.id}`,
      label: provider.name || 'API',
      items: models.map((modelId) => ({ kind: 'api', providerId: provider.id, modelId, label: modelId, detail: provider.flavor === 'ollama' ? 'Ollama' : provider.flavor === 'llama.cpp' ? 'llama.cpp' : 'API' })),
    });
  }

  const codexModels = Array.isArray(accounts.state.codex?.models) && accounts.state.codex.models.length
    ? accounts.state.codex.models
    : (Array.isArray(codexRuntime.catalog) ? codexRuntime.catalog : []);
  if (accounts.state.codex?.connected && codexModels.length) {
    groups.push({
      id: 'codex', label: 'ChatGPT / Codex',
      items: codexModels.map((meta) => {
        const modelId = String(meta.model || meta.id || '');
        return { kind: 'codex', modelId, meta, label: meta.displayName || modelId, detail: meta.description || 'ChatGPT account' };
      }).filter((item) => item.modelId),
    });
  }
  return groups;
}

function renderQuickModelMenu(filter = '') {
  if (!els.modelQuickList) return;
  const query = String(filter || '').trim().toLowerCase();
  const groups = quickModelGroups().map((group) => ({
    ...group,
    items: group.items.filter((item) => !query || `${item.label} ${item.detail || ''} ${group.label}`.toLowerCase().includes(query)),
  })).filter((group) => group.items.length);

  if (!groups.length) {
    els.modelQuickList.innerHTML = `<div class="model-quick-empty">${query ? 'No matching models' : 'No discovered models yet'}</div>`;
    return;
  }
  els.modelQuickList.innerHTML = groups.map((group) => `
    <section class="model-quick-group">
      <div class="model-quick-group-label">${escapeHtml(group.label)}</div>
      ${group.items.map((item) => `<button type="button" class="model-quick-item ${quickModelIsActive(item) ? 'active' : ''}" data-quick-kind="${escapeHtml(item.kind)}" data-quick-provider="${escapeHtml(item.providerId || '')}" data-quick-model="${escapeHtml(item.modelId)}">
        <span class="model-quick-check">${quickModelIsActive(item) ? '✓' : ''}</span>
        <span class="model-quick-copy"><strong>${escapeHtml(item.label)}</strong><small>${escapeHtml(String(item.detail || group.label).replace(/\s+/g, ' ').slice(0, 110))}</small></span>
      </button>`).join('')}
    </section>`).join('');

  els.modelQuickList.querySelectorAll('[data-quick-model]').forEach((button) => {
    button.onclick = async (event) => {
      event.stopPropagation();
      if (generating) return toast('Stop the current generation before switching models.', 'info');
      const kind = button.dataset.quickKind;
      const modelId = button.dataset.quickModel || '';
      const providerId = button.dataset.quickProvider || '';
      try {
        if (kind === 'auto') runtime.selectAuto();
        else if (kind === 'local') runtime.selectLocal();
        else if (kind === 'api') runtime.selectApi(providerId, modelId);
        else if (kind === 'codex') {
          const meta = (accounts.state.codex?.models || codexRuntime.catalog || []).find((entry) => String(entry.model || entry.id) === modelId) || null;
          runtime.selectCodex(modelId, meta);
        }
        refreshRuntimeUi();
        setModelQuickMenu(false);
        toast(kind === 'auto' ? `Auto enabled · ${runtime.loaded?.name || 'current model'}.` : `Using ${runtime.loaded?.name || modelId || 'model'}.`, 'success');
      } catch (error) { toast(errorMessage(error), 'error'); }
    };
  });
}

async function ensureQuickCodexModels() {
  if (!accounts.state.codex?.connected) return;
  if ((accounts.state.codex?.models || []).length || codexCatalogLoading) return;
  codexCatalogLoading = true;
  try {
    const models = await accounts.listCodexModels();
    codexRuntime.setCatalog(models);
    if (modelQuickMenuOpen) renderQuickModelMenu(els.modelQuickSearch?.value || '');
  } catch {}
  finally { codexCatalogLoading = false; }
}

function setModelQuickMenu(open) {
  modelQuickMenuOpen = !!open;
  els.modelChip?.setAttribute('aria-expanded', modelQuickMenuOpen ? 'true' : 'false');
  els.modelQuickMenu?.classList.toggle('hidden', !modelQuickMenuOpen);
  els.modelQuickMenu?.setAttribute('aria-hidden', modelQuickMenuOpen ? 'false' : 'true');
  if (!modelQuickMenuOpen) return;
  if (localRuntime.isAndroidNative && isCompactViewport()) els.promptInput?.blur();
  setReasoningPopover(false);
  setContextPopover(false);
  setTextRefinePopover(false);
  setVoiceModePopover(false);
  renderQuickModelMenu('');
  if (els.modelQuickSearch) els.modelQuickSearch.value = '';
  ensureQuickCodexModels();
  if (!(localRuntime.isAndroidNative && isCompactViewport())) requestAnimationFrame(() => els.modelQuickSearch?.focus());
}

function autoResizeComposer() {
  els.promptInput.style.height = 'auto';
  els.promptInput.style.height = `${Math.min(180, Math.max(28, els.promptInput.scrollHeight))}px`;
  if (reasoningPopoverOpen || contextPopoverOpen || textRefinePopoverOpen) requestAnimationFrame(syncAndroidComposerPopoverAnchor);
}

function setAttachment(file) {
  pendingAttachment = file || null;
  if (!file) {
    els.attachmentPreview.classList.add('hidden');
    els.attachmentPreview.innerHTML = '';
    return;
  }
  els.attachmentPreview.classList.remove('hidden');
  els.attachmentPreview.innerHTML = `<span>${icon('clip', 15)}<strong>${escapeHtml(file.name)}</strong><small>${humanBytes(file.size)}</small></span><button id="removeAttachment">${icon('x', 15)}</button>`;
  document.getElementById('removeAttachment').onclick = () => setAttachment(null);
}

function syncSeamlessContextUi() {
  const conv = store.activeConversation;
  const goal = store.state.mode === 'work' ? String(conv?.goal || '') : '';
  els.goalBar?.classList.toggle('hidden', !goal);
  if (els.goalBarText) els.goalBarText.textContent = goal;
  if (!els.seamlessContext) return;
  const pills = [];
  if (pendingArtifactInspect) pills.push(`<button type="button" class="context-pill" data-seamless-clear="inspect" title="Selected rendered element">${icon('edit', 12)}<span>${escapeHtml(pendingArtifactInspect.selector || pendingArtifactInspect.tag || 'Selected element')}</span><b>×</b></button>`);
  if (pendingArtifactCapture) pills.push(`<button type="button" class="context-pill" data-seamless-clear="capture" title="Current Artifact captured as context">${icon('file', 12)}<span>Artifact capture</span><b>×</b></button>`);
  els.seamlessContext.innerHTML = pills.join('');
  els.seamlessContext.classList.toggle('hidden', !pills.length);
  els.seamlessContext.querySelectorAll('[data-seamless-clear]').forEach((button) => button.onclick = () => {
    if (button.dataset.seamlessClear === 'inspect') pendingArtifactInspect = null;
    if (button.dataset.seamlessClear === 'capture') pendingArtifactCapture = null;
    syncSeamlessContextUi();
  });
}

function editConversationGoal() {
  if (store.state.mode !== 'work') { setMode('work'); renderAll(); }
  const conv = store.ensureConversation();
  modalShell('BlackRiver Goal', `<div class="goal-editor"><p>One durable success target for this Work conversation. BlackRiver keeps it across turns and uses it as a completion criterion.</p><textarea id="goalEditorInput" rows="4" placeholder="e.g. Make this app production-ready: responsive, polished, tested, clean runtime">${escapeHtml(conv.goal || '')}</textarea><div class="modal-actions"><button class="secondary-button" id="goalEditorClear" type="button">Clear</button><button class="primary-button" id="goalEditorSave" type="button">Save Goal</button></div></div>`);
  const input = document.getElementById('goalEditorInput');
  document.getElementById('goalEditorSave').onclick = () => { store.setConversationGoal(input.value, conv.id); closeModal(); syncSeamlessContextUi(); toast('Goal saved.', 'success'); };
  document.getElementById('goalEditorClear').onclick = () => { store.setConversationGoal('', conv.id); closeModal(); syncSeamlessContextUi(); toast('Goal cleared.', 'info'); };
  requestAnimationFrame(() => input?.focus());
}

function resumeWork() {
  if (generating) return toast('The current Work run is still active.', 'info');
  if (store.state.mode !== 'work') { setMode('work'); renderAll(); }
  const conv = store.ensureConversation();
  const goal = String(conv.goal || '').trim();
  els.promptInput.value = goal ? `Continue working toward the current Goal. Resume from the persisted Work state and verify what remains before declaring it complete.` : `Resume this Work from the persisted session, project, changed files, artifacts and verification state. Continue from where we left off.`;
  autoResizeComposer();
  sendPrompt();
}

function setArtifactInspectMode(enabled) {
  const item = artifacts.get(displayedArtifactId || artifacts.activeId);
  if (!item || item.type !== 'html' || els.artifactFrame?.classList.contains('hidden')) return toast('Open an HTML Artifact preview first.', 'info');
  artifactInspectMode = !!enabled;
  els.inspectArtifact?.classList.toggle('active', artifactInspectMode);
  try { els.artifactFrame.contentWindow?.postMessage({ bridge: ARTIFACT_PREVIEW_BRIDGE, type: 'inspect-mode', enabled: artifactInspectMode }, '*'); } catch {}
  if (artifactInspectMode) toast('Click exactly what you want BlackRiver to inspect.', 'info');
}

async function captureCurrentArtifact() {
  const item = artifacts.get(displayedArtifactId || artifacts.activeId);
  const conv = store.activeConversation;
  if (!item || item.type !== 'html' || item.conversationId !== conv?.id) return toast('Open an HTML Artifact first.', 'info');
  try {
    const result = await browserLab.snapshot({ artifact_id: item.id }, { conversationId: conv.id });
    const vision = result?.__blackriverVisionImage || null;
    const dom = { ...result }; delete dom.__blackriverVisionImage;
    pendingArtifactCapture = { dom, image: vision ? { type: 'image', mime: vision.mime || 'image/png', data: vision.data } : null };
    syncSeamlessContextUi();
    toast(vision ? 'Artifact captured with vision context.' : 'Artifact state captured as context.', 'success');
    els.promptInput.focus();
  } catch (error) { toast(errorMessage(error), 'error'); }
}

function fixCurrentArtifactRuntime() {
  const item = artifacts.get(displayedArtifactId || artifacts.activeId || artifacts.lastTouchedId);
  if (!item || item.type !== 'html') return toast('No HTML Artifact is active.', 'info');
  const diagnostics = artifacts.inspect(item.id)?.diagnostics || [];
  const visible = String(els.artifactPreviewErrorText?.textContent || '').trim();
  const details = visible || diagnostics.map((d) => d.message).filter(Boolean).slice(-4).join(' · ');
  if (store.state.mode !== 'work') { setMode('work'); renderAll(); }
  els.promptInput.value = `Fix the current Artifact runtime issue${details ? `: ${details}` : ''}. Edit the saved Artifact source, then verify the latest revision in Browser Lab. Do not patch only the live DOM.`;
  autoResizeComposer();
  closeModal();
  sendPrompt();
}

function hideBlackRiverPeek() {
  clearTimeout(peekTimer); peekToken += 1;
  els.blackriverPeek?.classList.add('hidden');
  els.blackriverPeek?.setAttribute('aria-hidden','true');
}

async function showBlackRiverPeek(code, target) {
  const token = ++peekToken;
  const value = String(code || '').trim();
  if (!value || value.length > 180 || store.state.mode !== 'work' || !store.activeConversation?.projectId) return;
  const rect = target.getBoundingClientRect();
  els.blackriverPeek.innerHTML = `<strong>${escapeHtml(value)}</strong><small>Looking up project context…</small>`;
  Object.assign(els.blackriverPeek.style, { left: `${Math.min(innerWidth-330, Math.max(12, rect.left))}px`, top: `${Math.min(innerHeight-220, rect.bottom+8)}px` });
  els.blackriverPeek.classList.remove('hidden'); els.blackriverPeek.setAttribute('aria-hidden','false');
  try {
    let result = null;
    if (/[/\\]|\.[a-z0-9]{1,8}$/i.test(value)) {
      result = await project.execute('read_file', { path: value.replace(/^@/,'') }, { projectId: store.activeConversation.projectId });
    } else if (project.isNative) {
      result = await project.execute('code_intelligence', { action: 'symbol', query: value, max_results: 6 }, { projectId: store.activeConversation.projectId });
    } else {
      result = await project.execute('grep_search', { query: value, max_results: 6 }, { projectId: store.activeConversation.projectId });
    }
    if (token !== peekToken) return;
    const content = result?.content ? String(result.content).slice(0,1800) : JSON.stringify(result?.matches || result?.results || result || {}, null, 2).slice(0,1800);
    els.blackriverPeek.innerHTML = `<div class="peek-head"><strong>${escapeHtml(value)}</strong><button type="button" data-peek-add>Add context</button></div><pre>${escapeHtml(content || 'No project match.')}</pre>`;
    els.blackriverPeek.querySelector('[data-peek-add]').onclick = () => { const current=els.promptInput.value.trimEnd(); els.promptInput.value=`${current}${current?' ':''}@${value} `; autoResizeComposer(); els.promptInput.focus(); hideBlackRiverPeek(); };
  } catch (error) { if (token === peekToken) els.blackriverPeek.innerHTML = `<strong>${escapeHtml(value)}</strong><small>${escapeHtml(errorMessage(error,'No project match.'))}</small>`; }
}

function bindBlackRiverPeek(root = document) {
  root.querySelectorAll?.('.markdown code:not(pre code)').forEach((code) => {
    if (code.dataset.peekBound === '1') return; code.dataset.peekBound='1';
    code.addEventListener('mouseenter', () => { clearTimeout(peekTimer); peekTimer=setTimeout(() => showBlackRiverPeek(code.textContent, code), 320); });
    code.addEventListener('mouseleave', () => { peekTimer=setTimeout(hideBlackRiverPeek, 220); });
  });
}

function renderSmartContext() {
  if (!els.smartContext) return;
  const record = project.activeProject;
  const query = String(els.promptInput?.value || '').trim();
  if (store.state.mode !== 'work' || !record || query.length < 2) {
    els.smartContext.classList.add('hidden');
    els.smartContext.innerHTML = '';
    return;
  }
  const files = (record.fileIndex || []).filter((entry) => entry.kind === 'file').map((entry) => entry.path);
  const ranked = rankProjectFiles(files, query, { recentFiles: record.recentFiles || [], changedFiles: record.changedFiles || [], limit: 3 });
  if (!ranked.length) {
    els.smartContext.classList.add('hidden');
    els.smartContext.innerHTML = '';
    return;
  }
  els.smartContext.innerHTML = `<span class="smart-context-label">Context</span>${ranked.map((path) => `<button type="button" class="smart-context-pill" data-context-path="${escapeHtml(path)}" title="Reference ${escapeHtml(path)}">${icon('file', 12)}<span>${escapeHtml(path.split('/').pop())}</span></button>`).join('')}`;
  els.smartContext.classList.remove('hidden');
  els.smartContext.querySelectorAll('[data-context-path]').forEach((button) => {
    button.onclick = () => {
      const token = `@${button.dataset.contextPath}`;
      const current = els.promptInput.value.trimEnd();
      if (!current.includes(token)) els.promptInput.value = `${current}${current ? ' ' : ''}${token} `;
      autoResizeComposer();
      els.promptInput.focus();
    };
  });
}

function commandPaletteItems() {
  const items = [
    { id: 'focus', label: 'Ask BlackRiver', detail: 'Focus composer', icon: 'compose', run: () => els.promptInput.focus() },
    { id: 'new', label: 'New chat', detail: 'Fresh conversation', icon: 'plus', run: () => { store.newConversation(store.state.mode); artifacts.close(); renderAll(); els.promptInput.focus(); } },
    { id: 'mode-work', label: 'Work mode', detail: 'Agent workspace', icon: 'sparkles', run: () => { setMode('work'); renderAll(); } },
    { id: 'mode-chat', label: 'Chat mode', detail: 'Conversation', icon: 'compose', run: () => { setMode('chat'); renderAll(); } },
    { id: 'projects', label: 'Projects', detail: project.name || 'Open or switch project', icon: 'folder', run: renderProjectsModal },
    { id: 'models', label: 'Models', detail: runtime.loaded?.name || 'Choose model', icon: 'model', run: () => renderModelsModal(runtime.isApi ? 'providers' : 'recommended') },
    { id: 'plugins', label: 'Plugins', detail: 'Tools and MCP', icon: 'plugin', run: renderPluginsModal },
  ];
  const activeArtifact = artifacts.get(artifacts.activeId || artifacts.lastTouchedId);
  if (activeArtifact) items.push({ id: 'artifact', label: 'Open artifact', detail: activeArtifact.title, icon: 'file', run: reopenArtifact });
  const record = project.activeProject;
  if (record?.changedFiles?.length) items.push({ id: 'changes', label: `What changed · ${record.changedFiles.length}`, detail: record.name, icon: 'edit', run: renderProjectsModal });
  const checkpoint = record ? project.store.latestCheckpoint(record.id) : null;
  if (checkpoint?.files?.length) items.push({ id: 'undo', label: 'Undo last Work', detail: `${checkpoint.files.length} changed file${checkpoint.files.length === 1 ? '' : 's'}`, icon: 'refresh', run: async () => {
    if (!window.confirm(`Undo the latest BlackRiver Work session?

${checkpoint.files.length} file${checkpoint.files.length === 1 ? '' : 's'} will be restored.`)) return;
    await project.undoCheckpoint(checkpoint.id); renderAll(); toast('Last Work session restored.', 'success');
  } });
  const conv = store.activeConversation;
  if (conv?.goal) items.push({ id: 'goal', label: 'Goal', detail: conv.goal, icon: 'sparkles', run: () => editConversationGoal() });
  if (conv?.mode === 'work' && conv.messages?.length) items.push({ id: 'resume', label: 'Resume', detail: conv.goal || conv.title || 'Continue this Work', icon: 'refresh', run: () => resumeWork() });
  return items;
}

function commandNaturalAction(query) {
  const q = String(query || '').trim().toLowerCase();
  if (!q) return null;
  if (/^(resume|continue|pick up|carry on)/.test(q)) return { id: 'natural-resume', label: 'Resume current Work', detail: 'Continue from saved session/project context', icon: 'refresh', run: () => resumeWork() };
  if (/goal|objective|success target/.test(q)) return { id: 'natural-goal', label: 'Set or edit Goal', detail: store.getConversationGoal() || 'Persistent success target', icon: 'sparkles', run: () => editConversationGoal() };
  if (/last (error|runtime)|fix (the )?(last|runtime)/.test(q)) return { id: 'natural-fix', label: 'Fix last runtime issue', detail: 'Continue in Work using current Artifact diagnostics', icon: 'edit', run: () => fixCurrentArtifactRuntime() };
  if (/artifact|preview/.test(q)) return { id: 'natural-artifact', label: 'Open current Artifact', detail: 'Preview and inspect', icon: 'file', run: reopenArtifact };
  if (/what changed|changed files|diff/.test(q)) return { id: 'natural-changes', label: 'Show changed files', detail: project.name || 'Current project', icon: 'edit', run: renderProjectsModal };
  return null;
}

function renderCommandPalette(filter = '') {
  if (!els.commandPaletteList) return;
  const query = String(filter || '').trim().toLowerCase();
  let items = commandPaletteItems().filter((item) => !query || `${item.label} ${item.detail}`.toLowerCase().includes(query));
  const natural = commandNaturalAction(query); if (natural && !items.some((item) => item.id === natural.id)) items = [natural, ...items];
  els.commandPaletteList.innerHTML = items.length ? items.map((item, index) => `<button type="button" class="command-palette-item${index === 0 ? ' selected' : ''}" data-command-id="${escapeHtml(item.id)}"><span class="command-palette-icon">${icon(item.icon, 16)}</span><span><strong>${escapeHtml(item.label)}</strong><small>${escapeHtml(item.detail || '')}</small></span></button>`).join('') : '<div class="command-palette-empty">No matching command</div>';
  els.commandPaletteList.querySelectorAll('[data-command-id]').forEach((button) => {
    button.onclick = async () => {
      const item = commandPaletteItems().find((entry) => entry.id === button.dataset.commandId) || commandNaturalAction(els.commandPaletteInput?.value || '');
      setCommandPalette(false);
      try { await item?.run?.(); } catch (error) { toast(errorMessage(error), 'error'); }
    };
  });
}

function setCommandPalette(open) {
  commandPaletteOpen = !!open;
  els.commandPaletteBackdrop?.classList.toggle('hidden', !commandPaletteOpen);
  els.commandPaletteBackdrop?.setAttribute('aria-hidden', commandPaletteOpen ? 'false' : 'true');
  if (!commandPaletteOpen) return;
  setModelQuickMenu(false); setContextPopover(false); setReasoningPopover(false); setTextRefinePopover(false); setVoiceModePopover(false);
  if (els.commandPaletteInput) els.commandPaletteInput.value = '';
  renderCommandPalette('');
  requestAnimationFrame(() => els.commandPaletteInput?.focus());
}

function textAttachmentPayload(file) {
  const name = String(file?.name || '').toLowerCase();
  return !!file && file.size <= 512 * 1024 && (/^(?:text\/|application\/(?:json|xml|javascript))/i.test(file.type || '') || /\.(?:txt|md|json|jsonl|js|mjs|cjs|ts|tsx|jsx|html|css|scss|py|rs|go|java|kt|toml|ya?ml|ini|log|csv|xml|svg|sql|graphql|gql|bat|cmd|ps1|sh)$/i.test(name));
}

function messagesWithTextAttachments(messages = []) {
  return messages.map((message) => {
    if (message.role !== 'user') return message;
    const additions = [];
    if (message.attachmentText) additions.push(`[Attached file: ${message.attachmentName || 'file'}]\n${message.attachmentText}`);
    if (message.contextExtras) additions.push(String(message.contextExtras));
    return additions.length ? { ...message, content: `${message.content || ''}\n\n${additions.join('\n\n')}`.trim() } : message;
  });
}


function normalizeArtifactStorageSnapshot(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const out = {};
  let bytes = 0;
  let count = 0;
  for (const [rawKey, rawValue] of Object.entries(value)) {
    if (count >= 128) break;
    const key = String(rawKey).slice(0, 512);
    const entry = String(rawValue).slice(0, 32_768);
    const cost = key.length + entry.length;
    if (bytes + cost > 128 * 1024) break;
    out[key] = entry;
    bytes += cost;
    count += 1;
  }
  return out;
}

function readArtifactLocalStorage(artifactId) {
  try {
    return normalizeArtifactStorageSnapshot(JSON.parse(localStorage.getItem(`${ARTIFACT_STORAGE_PREFIX}${artifactId}`) || '{}'));
  } catch {
    return {};
  }
}

function writeArtifactLocalStorage(artifactId, snapshot) {
  try {
    localStorage.setItem(`${ARTIFACT_STORAGE_PREFIX}${artifactId}`, JSON.stringify(normalizeArtifactStorageSnapshot(snapshot)));
  } catch {
    // Preview storage is best-effort. The artifact must still remain runnable if
    // browser storage is unavailable or full.
  }
}

function inlineScriptJson(value) {
  return JSON.stringify(value)
    .replaceAll('<', '\\u003c')
    .replaceAll('>', '\\u003e')
    .replaceAll('&', '\\u0026')
    .replace(/\u2028/g, '\\u2028')
    .replace(/\u2029/g, '\\u2029');
}

