function artifactPreviewDocument(item) {
  if (item.type !== 'html') {
    return `<html><body style="margin:0;background:#fff;color:#111;font:16px/1.5 system-ui;padding:32px;white-space:pre-wrap">${escapeHtml(item.content)}</body></html>`;
  }

  const bootstrap = artifactPreviewBootstrap(item);
  const html = String(item.content || '');
  const headOpen = html.match(/<head(?:\s[^>]*)?>/i);
  if (headOpen?.index != null) {
    const insertion = headOpen.index + headOpen[0].length;
    return `${html.slice(0, insertion)}${bootstrap}${html.slice(insertion)}`;
  }
  const htmlOpen = html.match(/<html(?:\s[^>]*)?>/i);
  if (htmlOpen?.index != null) {
    const insertion = htmlOpen.index + htmlOpen[0].length;
    return `${html.slice(0, insertion)}<head>${bootstrap}</head>${html.slice(insertion)}`;
  }
  return `<!doctype html><html><head>${bootstrap}</head><body>${html}</body></html>`;
}

function clearArtifactPreviewError({ resetSignature = false } = {}) {
  clearTimeout(artifactPreviewErrorTimer);
  artifactPreviewErrorTimer = 0;
  els.artifactPreviewError?.classList.add('hidden');
  if (els.artifactPreviewErrorText) els.artifactPreviewErrorText.textContent = '';
  if (resetSignature) artifactPreviewLastError = { signature: '', shownAt: 0 };
}

function showArtifactPreviewError(message) {
  if (!els.artifactPreviewError || artifactViewMode !== 'preview') return;
  const text = String(message || 'Artifact script error').trim().slice(0, 500);
  const now = Date.now();
  // Runtime errors are diagnostics, not a permanent modal. Interactive artifacts
  // can recover from a startup exception and continue running; keeping a large
  // blocking card forever made a healthy preview look broken. Show each unique
  // error briefly, suppress hot-loop duplicates, and let Retry remain available
  // while the notice is visible.
  if (artifactPreviewLastError.signature === text && now - artifactPreviewLastError.shownAt < 15000) return;
  artifactPreviewLastError = { signature: text, shownAt: now };
  clearTimeout(artifactPreviewErrorTimer);
  els.artifactPreviewErrorText.textContent = text;
  els.artifactPreviewError.classList.remove('hidden');
  artifactPreviewErrorTimer = setTimeout(() => {
    artifactPreviewErrorTimer = 0;
    els.artifactPreviewError?.classList.add('hidden');
  }, 6500);
}

function notifyArtifactPreviewResize() {
  if (!els.artifactFrame?.contentWindow || els.artifactFrame.classList.contains('hidden')) return;
  cancelAnimationFrame(artifactPreviewResizeFrame);
  artifactPreviewResizeFrame = requestAnimationFrame(() => {
    artifactPreviewResizeFrame = 0;
    try {
      els.artifactFrame.contentWindow.postMessage({ bridge: ARTIFACT_PREVIEW_BRIDGE, type: 'host-resize' }, '*');
    } catch {}
  });
}

function handleArtifactPreviewBridge(event) {
  const data = event.data;
  if (!data || data.bridge !== ARTIFACT_PREVIEW_BRIDGE || typeof data.artifactId !== 'string') return;
  const verifier = artifactVerificationFrames.get(data.artifactId);
  const fromVisible = event.source === els.artifactFrame?.contentWindow;
  const fromVerifier = verifier && event.source === verifier.contentWindow;
  if (!fromVisible && !fromVerifier) return;
  const item = artifacts.get(data.artifactId);
  if (!item) return;
  if (Number(data.artifactUpdatedAt || 0) !== Number(item.updatedAt || 0)) return;

  if (data.type === 'inspect-selection' && fromVisible) {
    artifactInspectMode = false;
    pendingArtifactInspect = { artifact_id: item.id, artifact_updated_at: item.updatedAt, title: item.title, ...(data.selection || {}) };
    syncSeamlessContextUi();
    els.promptInput?.focus();
    toast('Element selected. Tell BlackRiver what to change.', 'success');
    return;
  }
  if (data.type === 'storage') {
    const snapshot = normalizeArtifactStorageSnapshot(data.snapshot);
    if (data.area === 'local') writeArtifactLocalStorage(item.id, snapshot);
    if (data.area === 'session') artifactSessionStorage.set(item.id, snapshot);
    return;
  }
  if (data.type === 'runtime-error' || data.type === 'console-error') {
    artifacts.setDiagnostic(item.id, { level: 'error', message: data.message });
    if (fromVisible) showArtifactPreviewError(data.message);
    return;
  }
  if (data.type === 'console-warning') {
    artifacts.setDiagnostic(item.id, { level: 'warning', message: data.message });
    return;
  }
  if (data.type === 'bootstrap-ready') {
    artifacts.markPreviewReady(item.id);
    if (fromVisible) notifyArtifactPreviewResize();
  }
}

function runArtifactVerification(item) {
  if (!item || item.type !== 'html') return;
  const existing = artifactVerificationFrames.get(item.id);
  if (existing) { try { existing.remove(); } catch {} artifactVerificationFrames.delete(item.id); }
  artifacts.clearDiagnostics(item.id);
  const frame = document.createElement('iframe');
  frame.setAttribute('sandbox', 'allow-scripts allow-forms allow-modals allow-pointer-lock allow-popups allow-downloads');
  frame.setAttribute('aria-hidden', 'true');
  frame.tabIndex = -1;
  // Keep a real layout viewport while remaining completely off-screen; canvas
  // and responsive artifacts should be tested under representative dimensions.
  Object.assign(frame.style, { position: 'fixed', left: '-12000px', top: '0', width: '1024px', height: '768px', opacity: '0', pointerEvents: 'none', border: '0' });
  artifactVerificationFrames.set(item.id, frame);
  document.body.appendChild(frame);
  frame.srcdoc = artifactPreviewDocument(item);
  setTimeout(() => {
    if (artifactVerificationFrames.get(item.id) !== frame) return;
    artifactVerificationFrames.delete(item.id);
    try { frame.remove(); } catch {}
  }, 4500);
}

function scheduleArtifactPreview(item, { force = false } = {}) {
  if (!item || !els.artifactFrame) return;
  artifacts.clearDiagnostics(item.id);
  const signature = `${item.id}:${item.updatedAt}:${item.content.length}`;
  if (!force && artifactPreviewSignature === signature && els.artifactFrame.srcdoc) {
    els.artifactPreviewLoading?.classList.add('hidden');
    notifyArtifactPreviewResize();
    return;
  }

  const renderToken = ++artifactPreviewRenderToken;
  artifactPreviewSignature = signature;
  clearArtifactPreviewError({ resetSignature: true });
  els.artifactPreviewLoading?.classList.remove('hidden');

  // The artifact pane changes the Work grid from one column to two. Loading an
  // iframe in the very same frame can give responsive/canvas artifacts a zero or
  // stale viewport on Chromium. Wait until the split layout has committed before
  // creating the srcdoc document; the preview bridge then fires a second resize
  // once the sandboxed document itself is ready.
  requestAnimationFrame(() => {
    if (renderToken !== artifactPreviewRenderToken) return;
    els.artifactPane.getBoundingClientRect();
    requestAnimationFrame(() => {
      if (renderToken !== artifactPreviewRenderToken) return;
      els.artifactFrame.dataset.artifactId = item.id;
      els.artifactFrame.dataset.artifactUpdatedAt = String(item.updatedAt);
      els.artifactFrame.srcdoc = artifactPreviewDocument(item);
    });
  });
}

function renderArtifact(item = artifacts.get(artifacts.activeId), { force = false } = {}) {
  const activeConv = store.activeConversation;
  if (item && !['html', 'code', 'text', 'markdown'].includes(item.type)) {
    syncArtifactReopenButton();
    return;
  }
  if (!item || store.state.mode !== 'work' || item.conversationId !== activeConv?.id) {
    hideArtifactPane({ preserveActive: true });
    syncArtifactReopenButton();
    return;
  }
  if (!force && artifactDismissedConversations.has(activeConv.id)) {
    hideArtifactPane({ preserveActive: true });
    syncArtifactReopenButton();
    return;
  }
  if (force) artifactDismissedConversations.delete(activeConv.id);
  // Keep the UI-selected artifact explicit. ArtifactStore.activeId can change as
  // background Work creates artifacts in another conversation; the viewer that
  // is already on screen must keep pointing at the item the user is looking at.
  displayedArtifactId = item.id;
  artifacts.activeId = item.id;
  els.artifactPane.classList.remove('hidden');
  els.workbench.classList.add('artifact-open');
  els.artifactResizeHandle.classList.toggle('hidden', artifactFullscreen || window.matchMedia('(max-width: 900px)').matches);
  syncArtifactSplit();
  els.artifactTitle.textContent = item.title;
  syncArtifactPicker(item);
  const allArtifacts = activeConversationArtifacts();
  const artifactIndex = Math.max(0, allArtifacts.findIndex((entry) => entry.id === item.id));
  const position = allArtifacts.length > 1 ? `Artifact ${artifactIndex + 1}/${allArtifacts.length} · ` : '';
  els.artifactMeta.textContent = `${position}${item.type.toUpperCase()}${item.language ? ` · ${item.language}` : ''} · ${humanBytes(new Blob([item.content]).size)}`;
  els.artifactCode.querySelector('code').textContent = item.content;
  setArtifactView(artifactViewMode, { item, forcePreview: force });
  syncArtifactReopenButton();
}

function setArtifactView(mode, { item = artifacts.get(artifacts.activeId), forcePreview = false } = {}) {
  artifactViewMode = mode === 'code' ? 'code' : 'preview';
  document.querySelectorAll('[data-artifact-view]').forEach((btn) => btn.classList.toggle('active', btn.dataset.artifactView === artifactViewMode));
  els.artifactFrame.classList.toggle('hidden', artifactViewMode !== 'preview');
  els.artifactCode.classList.toggle('hidden', artifactViewMode !== 'code');
  els.artifactPreviewLoading?.classList.toggle('hidden', artifactViewMode !== 'preview');
  if (artifactViewMode === 'preview' && item) scheduleArtifactPreview(item, { force: forcePreview });
}

function activeConversationArtifacts() {
  const conv = store.activeConversation;
  return conv ? artifacts.list(conv.id).filter((item) => ['html', 'code', 'text', 'markdown'].includes(item.type)) : [];
}

function setArtifactPicker(open) {
  const items = activeConversationArtifacts();
  artifactPickerOpen = !!open && items.length > 1;
  els.artifactPickerPopover.classList.toggle('hidden', !artifactPickerOpen);
  els.artifactPickerPopover.setAttribute('aria-hidden', String(!artifactPickerOpen));
  els.artifactPickerBtn.setAttribute('aria-expanded', String(artifactPickerOpen));
}

function syncArtifactPicker(activeItem = artifacts.get(artifacts.activeId)) {
  const items = activeConversationArtifacts();
  const index = activeItem ? items.findIndex((item) => item.id === activeItem.id) : -1;
  const multiple = items.length > 1;
  els.artifactEyebrow.textContent = multiple && index >= 0 ? `Artifact ${index + 1} of ${items.length}` : 'Artifact';
  els.artifactPickerChevron.classList.toggle('hidden', !multiple);
  els.artifactPickerBtn.classList.toggle('has-multiple', multiple);
  els.artifactPickerBtn.title = multiple ? 'Switch artifact' : (activeItem?.title || 'Artifact');
  els.artifactPickerPopover.innerHTML = items.map((item, itemIndex) => `
    <button type="button" class="artifact-picker-item ${item.id === activeItem?.id ? 'active' : ''}" data-artifact-id="${escapeHtml(item.id)}">
      <span class="artifact-picker-index">${itemIndex + 1}</span>
      <span class="artifact-picker-copy"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.type.toUpperCase())}${item.language ? ` · ${escapeHtml(item.language)}` : ''} · ${formatDate(item.updatedAt)}</small></span>
      <span class="artifact-picker-check">${item.id === activeItem?.id ? '✓' : ''}</span>
    </button>`).join('');
  els.artifactPickerPopover.querySelectorAll('[data-artifact-id]').forEach((button) => {
    button.onclick = (event) => {
      event.stopPropagation();
      setArtifactPicker(false);
      artifacts.open(button.dataset.artifactId);
    };
  });
  if (!multiple) setArtifactPicker(false);
}

function syncArtifactReopenButton() {
  if (!els.artifactReopenBtn) return;
  const conv = store.activeConversation;
  const items = store.state.mode === 'work' && conv ? artifacts.list(conv.id).filter((item) => ['html', 'code', 'text', 'markdown'].includes(item.type)) : [];
  const paneOpen = !els.artifactPane.classList.contains('hidden');
  const show = store.state.mode === 'work' && !!items.length && !paneOpen;
  const androidNative = localRuntime.isAndroidNative || document.documentElement.classList.contains('android-native');
  const showTopbar = show && !androidNative;
  const showFloating = show && androidNative;

  // Desktop/web keeps the compact topbar reopen action. Android uses a
  // standalone viewport-level control so the action cannot be clipped by the
  // intentionally narrow topbar action lane.
  els.artifactReopenBtn.classList.toggle('hidden', !showTopbar);
  els.artifactReopenFloatingBtn?.classList.toggle('hidden', !showFloating);
  els.artifactReopenBtn.parentElement?.classList.toggle('artifact-reopen-visible', showTopbar);

  if (show) {
    const active = artifacts.get(artifacts.activeId);
    const candidate = active?.conversationId === conv.id ? active : items[0];
    const title = candidate ? `Open ${candidate.title}` : 'Open artifact';
    els.artifactReopenLabel.textContent = candidate?.title || 'Artifact';
    els.artifactReopenBtn.title = title;
    if (els.artifactReopenFloatingBtn) {
      els.artifactReopenFloatingBtn.title = title;
      els.artifactReopenFloatingBtn.setAttribute('aria-label', title);
    }
  }
}

function syncArtifactSplit() {
  if (!els.workbench?.classList.contains('artifact-open') || window.matchMedia('(max-width: 900px)').matches || artifactFullscreen) return;
  const rect = els.workbench.getBoundingClientRect();
  if (!rect.width) return;
  const minLeft = 320;
  const minRight = 340;
  const usable = Math.max(1, rect.width - 7);
  let left = artifactLeftWidthPx || Math.round(usable * artifactSplitRatio);
  left = Math.max(minLeft, Math.min(left, usable - minRight));
  artifactLeftWidthPx = left;
  artifactSplitRatio = Math.max(0.28, Math.min(0.72, left / usable));
  els.workbench.style.setProperty('--artifact-left', `${left}px`);
  els.artifactResizeHandle?.setAttribute('aria-valuenow', String(Math.round(artifactSplitRatio * 100)));
  els.artifactResizeHandle?.setAttribute('aria-valuetext', `${Math.round(artifactSplitRatio * 100)}% conversation · ${Math.round((1 - artifactSplitRatio) * 100)}% artifact`);
}

function resetArtifactSplit() {
  artifactSplitRatio = 0.45;
  artifactLeftWidthPx = 0;
  try { localStorage.setItem('blackriver.artifact.split.ratio.v1', String(artifactSplitRatio)); } catch {}
  syncArtifactSplit();
  requestAnimationFrame(() => {
    notifyArtifactPreviewResize();
    requestAnimationFrame(notifyArtifactPreviewResize);
  });
}

function adjustArtifactSplit(deltaPx) {
  if (window.matchMedia('(max-width: 900px)').matches || artifactFullscreen || !els.workbench.classList.contains('artifact-open')) return;
  const rect = els.workbench.getBoundingClientRect();
  const usable = Math.max(1, rect.width - 7);
  const minLeft = 320;
  const minRight = 340;
  const base = artifactLeftWidthPx || Math.round(usable * artifactSplitRatio);
  artifactLeftWidthPx = Math.max(minLeft, Math.min(base + deltaPx, usable - minRight));
  artifactSplitRatio = Math.max(0.28, Math.min(0.72, artifactLeftWidthPx / usable));
  try { localStorage.setItem('blackriver.artifact.split.ratio.v1', String(artifactSplitRatio)); } catch {}
  syncArtifactSplit();
  notifyArtifactPreviewResize();
}

function setArtifactFullscreen(open) {
  artifactFullscreen = !!open && !els.artifactPane.classList.contains('hidden');
  if (artifactFullscreen && localRuntime.isAndroidNative && artifactViewMode !== 'preview') setArtifactView('preview');
  document.body.classList.toggle('artifact-fullscreen', artifactFullscreen);
  els.artifactPane.classList.toggle('fullscreen', artifactFullscreen);
  els.artifactResizeHandle.classList.toggle('hidden', artifactFullscreen || els.artifactPane.classList.contains('hidden'));
  els.artifactFullscreenExit?.classList.toggle('hidden', !artifactFullscreen);
  if (els.fullscreenArtifact) {
    els.fullscreenArtifact.innerHTML = icon(artifactFullscreen ? 'shrink' : 'expand', 17);
    els.fullscreenArtifact.title = artifactFullscreen ? 'Exit full screen' : 'Expand artifact';
    els.fullscreenArtifact.setAttribute('aria-label', els.fullscreenArtifact.title);
  }
  if (localRuntime.isAndroidNative) {
    const mobile = androidMobilePlugin();
    if (mobile?.setImmersive) mobile.setImmersive({ enabled: artifactFullscreen }).catch(() => null);
  }
  requestAnimationFrame(() => {
    notifyArtifactPreviewResize();
    requestAnimationFrame(notifyArtifactPreviewResize);
  });
}

function startArtifactResize(event) {
  if (window.matchMedia('(max-width: 900px)').matches || artifactFullscreen) return;
  event.preventDefault();
  artifactResizeActive = true;
  document.body.classList.add('artifact-resizing');
  els.artifactResizeHandle.setPointerCapture?.(event.pointerId);
  const move = (moveEvent) => {
    if (!artifactResizeActive) return;
    const rect = els.workbench.getBoundingClientRect();
    const usable = Math.max(1, rect.width - 7);
    const minLeft = 320;
    const minRight = 340;
    const left = Math.max(minLeft, Math.min(moveEvent.clientX - rect.left, usable - minRight));
    artifactLeftWidthPx = left;
    artifactSplitRatio = Math.max(0.28, Math.min(0.72, left / usable));
    els.workbench.style.setProperty('--artifact-left', `${left}px`);
    notifyArtifactPreviewResize();
  };
  const end = () => {
    if (!artifactResizeActive) return;
    artifactResizeActive = false;
    document.body.classList.remove('artifact-resizing');
    try { localStorage.setItem('blackriver.artifact.split.ratio.v1', String(artifactSplitRatio)); } catch {}
    window.removeEventListener('pointermove', move);
    window.removeEventListener('pointerup', end);
    window.removeEventListener('pointercancel', end);
    notifyArtifactPreviewResize();
  };
  window.addEventListener('pointermove', move);
  window.addEventListener('pointerup', end);
  window.addEventListener('pointercancel', end);
}

