function exportPayloadText(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  try { return JSON.stringify(value, null, 2); } catch { return String(value); }
}

function conversationExportMarkdown(conv) {
  const title = String(conv?.title || 'BlackRiver conversation').trim() || 'BlackRiver conversation';
  const lines = [`# ${title}`, '', `Exported from BlackRiver Workspace`, ''];
  for (const message of conv?.messages || []) {
    if (!['user', 'assistant'].includes(message.role) || message.hidden) continue;
    lines.push(`## ${message.role === 'user' ? 'User' : 'BlackRiver'}`, '', String(message.content || '').trim() || '_No visible text_', '');
    if (message.role === 'assistant' && String(message.reasoning || '').trim()) {
      lines.push('### Reasoning', '', `_Thought for ${formatElapsed(message.elapsedMs || 0)} · profile: ${message.reasoningProfile || 'auto'}_`, '', String(message.reasoning).trim(), '');
    }
    if (message.role === 'assistant' && Array.isArray(message.tools) && message.tools.length) {
      lines.push('### Tool trace', '');
      message.tools.forEach((tool, index) => {
        const phase = String(tool.phase || 'event');
        lines.push(`#### ${index + 1}. ${tool.name || 'tool'} · ${phase}`, '');
        if (tool.args != null) lines.push('**Arguments**', '', '```json', exportPayloadText(tool.args), '```', '');
        if (tool.result != null) lines.push('**Result**', '', '```json', exportPayloadText(tool.result), '```', '');
      });
    }
    if (Array.isArray(message.skills) && message.skills.length) lines.push(`_Skills: ${message.skills.map((skill) => skill.name || skill.id).filter(Boolean).join(', ')}_`, '');
    if (Array.isArray(message.memories) && message.memories.length) lines.push(`_Memory recalled: ${message.memories.map((item) => item.title || item.scope).filter(Boolean).slice(0, 6).join(', ')}_`, '');
    if (Array.isArray(message.crew) && message.crew.some((item) => item.status === 'done')) lines.push(`_Crew: ${[...new Set(message.crew.filter((item) => item.status === 'done').map((item) => item.role))].join(', ')}_`, '');
  }
  return lines.join('\n').trim() + '\n';
}

function conversationExportHtml(conv) {
  const title = escapeHtml(conv?.title || 'BlackRiver conversation');
  const turns = (conv?.messages || []).filter((m) => ['user', 'assistant'].includes(m.role) && !m.hidden).map((m) => {
    const reasoning = m.role === 'assistant' && String(m.reasoning || '').trim()
      ? `<details class="reasoning" open><summary>Reasoning · ${escapeHtml(formatElapsed(m.elapsedMs || 0))} · ${escapeHtml(m.reasoningProfile || 'auto')}</summary><div>${renderMarkdown(String(m.reasoning || ''))}</div></details>` : '';
    const toolTrace = m.role === 'assistant' && Array.isArray(m.tools) && m.tools.length
      ? `<details class="tools" open><summary>Tool trace · ${m.tools.length} events</summary>${m.tools.map((tool, index) => `<section class="tool"><h3>${index + 1}. ${escapeHtml(tool.name || 'tool')} · ${escapeHtml(tool.phase || 'event')}</h3>${tool.args != null ? `<strong>Arguments</strong><pre>${escapeHtml(exportPayloadText(tool.args))}</pre>` : ''}${tool.result != null ? `<strong>Result</strong><pre>${escapeHtml(exportPayloadText(tool.result))}</pre>` : ''}</section>`).join('')}</details>` : '';
    const meta = [
      Array.isArray(m.skills) && m.skills.length ? `Skills: ${m.skills.map((skill) => skill.name || skill.id).filter(Boolean).join(', ')}` : '',
      Array.isArray(m.crew) && m.crew.some((item) => item.status === 'done') ? `Crew: ${[...new Set(m.crew.filter((item) => item.status === 'done').map((item) => item.role))].join(', ')}` : '',
    ].filter(Boolean).map((line) => `<p class="meta">${escapeHtml(line)}</p>`).join('');
    return `<article class="turn ${m.role}"><h2>${m.role === 'user' ? 'User' : 'BlackRiver'}</h2><div>${renderMarkdown(String(m.content || ''))}</div>${reasoning}${toolTrace}${meta}</article>`;
  }).join('');
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>body{max-width:980px;margin:48px auto;padding:0 28px;background:#fff;color:#111827;font:16px/1.65 system-ui,-apple-system,Segoe UI,sans-serif}h1{font-size:28px}h2{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#64748b}.turn{padding:20px 0;border-top:1px solid #e5e7eb}.turn:first-of-type{border-top:0}details{margin:16px 0;padding:12px 14px;border:1px solid #e5e7eb;border-radius:10px;background:#fafafa}summary{cursor:pointer;font-weight:650}.tool{margin-top:14px}.tool h3{font-size:13px}.meta{color:#64748b;font-size:13px}pre{overflow:auto;background:#f3f4f6;padding:14px;border-radius:8px;white-space:pre-wrap}code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}</style></head><body><h1>${title}</h1><p>Exported from BlackRiver Workspace · includes visible reasoning and persisted tool trace.</p>${turns}</body></html>`;
}

function triggerBlobDownload(blob, filename) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = normalizeDownloadName(filename);
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1500);
}

async function exportConversation(format = 'md') {
  const conv = store.activeConversation;
  if (!conv?.messages?.length) return toast('There is no conversation to export yet.', 'info');
  const base = normalizeDownloadName(conv.title || 'blackriver-conversation');
  const markdown = conversationExportMarkdown(conv);
  const html = conversationExportHtml(conv);
  const documentContent = markdown.replace(/^# .+?\n+/, '');
  if (format === 'md') return triggerBlobDownload(new Blob([markdown], { type: 'text/markdown' }), `${base}.md`);
  if (format === 'json') return triggerBlobDownload(new Blob([JSON.stringify(conv, null, 2)], { type: 'application/json' }), `${base}.json`);
  if (format === 'html') return triggerBlobDownload(new Blob([html], { type: 'text/html' }), `${base}.html`);
  if (format === 'pdf' || format === 'docx') {
    const blob = await renderDocumentBlobAsync({ format, title: conv.title || 'BlackRiver conversation', content: documentContent, filename: `${base}.${format}` });
    return triggerBlobDownload(blob, `${base}.${format}`);
  }
  if (format === 'zip') {
    const [pdf, docx] = await Promise.all([
      renderDocumentBytesAsync({ format: 'pdf', title: conv.title || 'BlackRiver conversation', content: documentContent, filename: `${base}.pdf` }),
      renderDocumentBytesAsync({ format: 'docx', title: conv.title || 'BlackRiver conversation', content: documentContent, filename: `${base}.docx` }),
    ]);
    const files = [
      { path: `${base}.md`, content: markdown },
      { path: `${base}.json`, content: JSON.stringify(conv, null, 2) },
      { path: `${base}.html`, content: html },
      { path: `${base}.pdf`, content: pdf },
      { path: `${base}.docx`, content: docx },
    ];
    return triggerBlobDownload(createZipBlob(files), `${base}-export.zip`);
  }
}

