const STORAGE_KEY = 'blackriver.workspace.v07';
const LEGACY_KEYS = ['blackriver.workspace.v06', 'blackriver.workspace.v05'];
const NO_PROJECT = '__none__';

function uid() {
  return crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function projectLaneKey(projectId) {
  return projectId || NO_PROJECT;
}

function normalizeState(saved) {
  const conversations = Array.isArray(saved?.conversations) ? saved.conversations.map((conversation) => ({
    ...conversation,
    mode: conversation?.mode === 'work' ? 'work' : 'chat',
    projectId: conversation?.mode === 'work' ? (conversation.projectId || null) : null,
    goal: String(conversation?.goal || ''),
    goalUpdatedAt: Number(conversation?.goalUpdatedAt || 0),
  })).sort((a, b) => (Number(b.updatedAt) || Number(b.createdAt) || 0) - (Number(a.updatedAt) || Number(a.createdAt) || 0)) : [];
  const mode = saved?.mode === 'work' ? 'work' : 'chat';
  const activeProjectId = saved?.activeProjectId || null;
  const activeConversationId = saved?.activeConversationId || null;
  const activeByMode = {
    chat: saved?.activeByMode?.chat || null,
    work: saved?.activeByMode?.work || null,
  };
  const activeByProject = { ...(saved?.activeByProject || {}) };

  const oldActive = conversations.find((c) => c.id === activeConversationId);
  if (oldActive?.id) {
    const lane = oldActive.mode === 'work' ? 'work' : 'chat';
    activeByMode[lane] = oldActive.id;
    if (lane === 'work') activeByProject[projectLaneKey(oldActive.projectId)] = oldActive.id;
  }

  if (!activeByMode.chat || !conversations.some((c) => c.id === activeByMode.chat && c.mode === 'chat')) {
    activeByMode.chat = conversations.find((c) => c.mode === 'chat')?.id || null;
  }

  for (const conversation of conversations.filter((c) => c.mode === 'work')) {
    const key = projectLaneKey(conversation.projectId);
    if (!activeByProject[key] || !conversations.some((c) => c.id === activeByProject[key] && c.mode === 'work' && projectLaneKey(c.projectId) === key)) {
      activeByProject[key] = conversation.id;
    }
  }
  activeByMode.work = activeByProject[projectLaneKey(activeProjectId)] || conversations.find((c) => c.mode === 'work' && (c.projectId || null) === activeProjectId)?.id || null;

  return {
    conversations,
    activeConversationId: mode === 'work' ? activeByMode.work : activeByMode.chat,
    activeByMode,
    activeByProject,
    activeProjectId,
    mode,
    settings: {
      context: saved?.settings?.context || 32768,
      maxTokens: saved?.settings?.maxTokens || 8192,
      temperature: saved?.settings?.temperature ?? 0.7,
      cacheTypeK: ['', 'f32', 'f16', 'q8_0', 'q5_1', 'q5_0', 'q4_1', 'q4_0'].includes(saved?.settings?.cacheTypeK) ? saved.settings.cacheTypeK : '',
      cacheTypeV: ['', 'f32', 'f16', 'q8_0', 'q5_1', 'q5_0', 'q4_1', 'q4_0'].includes(saved?.settings?.cacheTypeV) ? saved.settings.cacheTypeV : '',
      reasoningByMode: {
        chat: ['auto', 'off', 'low', 'medium', 'high'].includes(saved?.settings?.reasoningByMode?.chat) ? saved.settings.reasoningByMode.chat : 'auto',
        work: ['auto', 'off', 'low', 'medium', 'high'].includes(saved?.settings?.reasoningByMode?.work) ? saved.settings.reasoningByMode.work : 'auto',
      },
      greedByMode: {
        chat: !!saved?.settings?.greedByMode?.chat,
        work: !!saved?.settings?.greedByMode?.work,
      },
      crewByMode: {
        chat: ['off', 'auto', 'on'].includes(saved?.settings?.crewByMode?.chat) ? saved.settings.crewByMode.chat : 'off',
        work: ['off', 'auto', 'on'].includes(saved?.settings?.crewByMode?.work) ? saved.settings.crewByMode.work : 'auto',
      },
      yoloWork: !!saved?.settings?.yoloWork,
    },
  };
}

export class WorkspaceStore extends EventTarget {
  constructor() { super(); this.state = this.load(); }

  load() {
    for (const key of [STORAGE_KEY, ...LEGACY_KEYS]) {
      try {
        const saved = JSON.parse(localStorage.getItem(key) || 'null');
        if (saved?.conversations) {
          const normalized = normalizeState(saved);
          if (key !== STORAGE_KEY) localStorage.setItem(STORAGE_KEY, JSON.stringify(normalized));
          return normalized;
        }
      } catch {}
    }
    return normalizeState(null);
  }

  save() { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.state)); this.dispatchEvent(new Event('change')); }

  get activeConversation() { return this.state.conversations.find((c) => c.id === this.state.activeConversationId) || null; }

  promoteConversation(id) {
    const index = this.state.conversations.findIndex((c) => c.id === id);
    if (index <= 0) return this.state.conversations[index] || null;
    const [conversation] = this.state.conversations.splice(index, 1);
    this.state.conversations.unshift(conversation);
    return conversation;
  }

  recentConversations(limit = 20) {
    return [...this.state.conversations]
      .sort((a, b) => (Number(b.updatedAt) || Number(b.createdAt) || 0) - (Number(a.updatedAt) || Number(a.createdAt) || 0))
      .slice(0, Math.max(0, Number(limit) || 0));
  }

  conversationsForProject(projectId = this.state.activeProjectId) {
    return this.state.conversations.filter((c) => c.mode === 'work' && (c.projectId || null) === (projectId || null));
  }

  setActiveProject(projectId = null) {
    const id = projectId || null;
    this.state.activeProjectId = id;
    const key = projectLaneKey(id);
    let active = this.state.activeByProject?.[key] || null;
    if (!active || !this.state.conversations.some((c) => c.id === active && c.mode === 'work' && (c.projectId || null) === id)) {
      active = this.conversationsForProject(id)[0]?.id || null;
    }
    this.state.activeByProject ||= {};
    this.state.activeByProject[key] = active;
    this.state.activeByMode.work = active;
    if (this.state.mode === 'work') this.state.activeConversationId = active;
    this.save();
    return this.activeConversation;
  }

  switchMode(mode) {
    const lane = mode === 'work' ? 'work' : 'chat';
    this.state.mode = lane;
    this.state.activeConversationId = lane === 'work'
      ? (this.state.activeByProject?.[projectLaneKey(this.state.activeProjectId)] || null)
      : (this.state.activeByMode?.chat || null);
    this.state.activeByMode.work = this.state.activeByProject?.[projectLaneKey(this.state.activeProjectId)] || null;
    this.save();
    return this.activeConversation;
  }

  newConversation(mode = this.state.mode) {
    const lane = mode === 'work' ? 'work' : 'chat';
    const conversation = { id: uid(), title: 'New chat', mode: lane, projectId: lane === 'work' ? (this.state.activeProjectId || null) : null, goal: '', goalUpdatedAt: 0, createdAt: Date.now(), updatedAt: Date.now(), messages: [] };
    this.state.conversations.unshift(conversation);
    this.state.activeByMode ||= { chat: null, work: null };
    this.state.activeByMode[lane] = conversation.id;
    if (lane === 'work') {
      this.state.activeByProject ||= {};
      this.state.activeByProject[projectLaneKey(conversation.projectId)] = conversation.id;
    }
    this.state.activeConversationId = conversation.id;
    this.state.mode = lane;
    this.save();
    return conversation;
  }

  activate(id) {
    const conv = this.state.conversations.find((c) => c.id === id) || null;
    if (!conv) return null;
    const lane = conv.mode === 'work' ? 'work' : 'chat';
    if (lane === 'work') {
      this.state.activeProjectId = conv.projectId || null;
      this.state.activeByProject ||= {};
      this.state.activeByProject[projectLaneKey(conv.projectId)] = id;
    }
    this.state.activeConversationId = id;
    this.state.activeByMode ||= { chat: null, work: null };
    this.state.activeByMode[lane] = id;
    this.state.mode = lane;
    this.save();
    return conv;
  }

  deleteConversation(id) {
    const conv = this.state.conversations.find((c) => c.id === id);
    this.state.conversations = this.state.conversations.filter((c) => c.id !== id);
    if (conv) {
      const lane = conv.mode === 'work' ? 'work' : 'chat';
      if (lane === 'work') {
        const key = projectLaneKey(conv.projectId);
        if (this.state.activeByProject?.[key] === id) this.state.activeByProject[key] = this.state.conversations.find((c) => c.mode === 'work' && projectLaneKey(c.projectId) === key)?.id || null;
        this.state.activeByMode.work = this.state.activeByProject?.[projectLaneKey(this.state.activeProjectId)] || null;
      } else if (this.state.activeByMode?.chat === id) {
        this.state.activeByMode.chat = this.state.conversations.find((c) => c.mode === 'chat')?.id || null;
      }
    }
    this.state.activeConversationId = this.state.mode === 'work' ? (this.state.activeByMode.work || null) : (this.state.activeByMode.chat || null);
    this.save();
  }

  detachProject(projectId) {
    if (!projectId) return;
    for (const conv of this.state.conversations) {
      if (conv.mode === 'work' && conv.projectId === projectId) conv.projectId = null;
    }
    if (this.state.activeByProject) delete this.state.activeByProject[projectLaneKey(projectId)];
    const noneKey = projectLaneKey(null);
    this.state.activeByProject ||= {};
    if (!this.state.activeByProject[noneKey]) this.state.activeByProject[noneKey] = this.state.conversations.find((c) => c.mode === 'work' && !c.projectId)?.id || null;
    if (this.state.activeProjectId === projectId) this.state.activeProjectId = null;
    this.state.activeByMode.work = this.state.activeByProject[projectLaneKey(this.state.activeProjectId)] || null;
    if (this.state.mode === 'work') this.state.activeConversationId = this.state.activeByMode.work;
    this.save();
  }

  renameConversation(id, title) {
    const conv = this.state.conversations.find((c) => c.id === id); if (!conv) return null;
    const next = String(title || '').replace(/\s+/g, ' ').trim().slice(0, 120); if (!next) return conv;
    conv.title = next; conv.updatedAt = Date.now(); this.promoteConversation(conv.id); this.save(); return conv;
  }

  deleteMessage(id, { withResponse = false } = {}) {
    const conv = this.activeConversation; if (!conv) return false;
    const index = conv.messages.findIndex((m) => m.id === id); if (index < 0) return false;
    let deleteCount = 1;
    if (withResponse && conv.messages[index]?.role === 'user') { let cursor = index + 1; while (cursor < conv.messages.length && conv.messages[cursor]?.role !== 'user') cursor += 1; deleteCount = Math.max(1, cursor - index); }
    conv.messages.splice(index, deleteCount); conv.updatedAt = Date.now(); this.save(); return true;
  }

  truncateFromMessage(id) {
    const conv = this.activeConversation; if (!conv) return false; const index = conv.messages.findIndex((m) => m.id === id); if (index < 0) return false; conv.messages.splice(index); conv.updatedAt = Date.now(); this.save(); return true;
  }

  ensureConversation() {
    const active = this.activeConversation;
    if (active && (active.mode === 'work' ? 'work' : 'chat') === this.state.mode && (this.state.mode !== 'work' || (active.projectId || null) === (this.state.activeProjectId || null))) return active;
    return this.newConversation(this.state.mode);
  }

  addMessage(message) {
    const conv = this.ensureConversation(); conv.messages.push({ id: uid(), createdAt: Date.now(), ...message }); conv.updatedAt = Date.now();
    if (message.role === 'user' && conv.title === 'New chat') conv.title = message.content.replace(/\s+/g, ' ').trim().slice(0, 52) || 'New chat';
    this.promoteConversation(conv.id);
    this.save(); return conv.messages[conv.messages.length - 1];
  }

  updateMessage(id, patch) { const conv = this.activeConversation; const msg = conv?.messages.find((m) => m.id === id); if (!msg) return; Object.assign(msg, patch); conv.updatedAt = Date.now(); this.promoteConversation(conv.id); this.save(); }

  getReasoningEffort(mode = this.state.mode) { const lane = mode === 'work' ? 'work' : 'chat'; return this.state.settings?.reasoningByMode?.[lane] || 'auto'; }

  setReasoningEffort(value, mode = this.state.mode) {
    const lane = mode === 'work' ? 'work' : 'chat'; const effort = ['auto', 'off', 'low', 'medium', 'high'].includes(value) ? value : 'auto'; this.state.settings ||= {};
    this.state.settings.reasoningByMode = { chat: this.state.settings.reasoningByMode?.chat || 'auto', work: this.state.settings.reasoningByMode?.work || 'auto', [lane]: effort }; this.save(); return effort;
  }

  getGreedMode(mode = this.state.mode) { const lane = mode === 'work' ? 'work' : 'chat'; return !!this.state.settings?.greedByMode?.[lane]; }

  setGreedMode(value, mode = this.state.mode) {
    const lane = mode === 'work' ? 'work' : 'chat'; this.state.settings ||= {};
    this.state.settings.greedByMode = { chat: !!this.state.settings.greedByMode?.chat, work: !!this.state.settings.greedByMode?.work, [lane]: !!value };
    this.save(); return !!value;
  }

  getCrewMode(mode = this.state.mode) {
    const lane = mode === 'work' ? 'work' : 'chat';
    return ['off', 'auto', 'on'].includes(this.state.settings?.crewByMode?.[lane]) ? this.state.settings.crewByMode[lane] : (lane === 'work' ? 'auto' : 'off');
  }

  setCrewMode(value, mode = this.state.mode) {
    const lane = mode === 'work' ? 'work' : 'chat';
    const next = ['off', 'auto', 'on'].includes(value) ? value : (lane === 'work' ? 'auto' : 'off');
    this.state.settings ||= {};
    this.state.settings.crewByMode = { chat: this.state.settings.crewByMode?.chat || 'off', work: this.state.settings.crewByMode?.work || 'auto', [lane]: next };
    this.save(); return next;
  }

  getYoloMode() { return !!this.state.settings?.yoloWork; }

  setYoloMode(value) {
    this.state.settings ||= {};
    this.state.settings.yoloWork = !!value;
    this.save(); return !!value;
  }


  setConversationGoal(goal, id = this.state.activeConversationId) {
    const conv = this.state.conversations.find((c) => c.id === id); if (!conv) return '';
    conv.goal = String(goal || '').replace(/\s+/g, ' ').trim().slice(0, 500);
    conv.goalUpdatedAt = Date.now(); conv.updatedAt = Date.now(); this.save(); return conv.goal;
  }

  getConversationGoal(id = this.state.activeConversationId) {
    return String(this.state.conversations.find((c) => c.id === id)?.goal || '');
  }

  updateSettings(patch) {
    this.state.settings = { ...this.state.settings, ...patch, ...(patch.reasoningByMode ? { reasoningByMode: { ...(this.state.settings.reasoningByMode || { chat: 'auto', work: 'auto' }), ...patch.reasoningByMode } } : {}) }; this.save();
  }
}
