const KEY = 'blackriver.hooks.v1';

function loadHooks() {
  try { const value = JSON.parse(localStorage.getItem(KEY) || '[]'); return Array.isArray(value) ? value : []; }
  catch { return []; }
}

export class HookEngine extends EventTarget {
  constructor() {
    super();
    this.hooks = loadHooks();
    this.handlers = new Map();
    this.executor = null;
  }

  setExecutor(fn) { this.executor = typeof fn === 'function' ? fn : null; }
  list() { return [...this.hooks]; }
  save() { try { localStorage.setItem(KEY, JSON.stringify(this.hooks.slice(0, 128))); } catch {} this.dispatchEvent(new Event('change')); }
  upsert(hook = {}) {
    const clean = { id: String(hook.id || crypto.randomUUID?.() || Date.now()), event: String(hook.event || ''), enabled: hook.enabled !== false, tool: String(hook.tool || ''), args: hook.args && typeof hook.args === 'object' ? hook.args : {} };
    const index = this.hooks.findIndex((item) => item.id === clean.id);
    if (index >= 0) this.hooks[index] = clean; else this.hooks.push(clean);
    this.save(); return clean;
  }
  remove(id) { const before = this.hooks.length; this.hooks = this.hooks.filter((item) => item.id !== id); if (this.hooks.length !== before) this.save(); return this.hooks.length !== before; }
  onInternal(event, fn) { const list = this.handlers.get(event) || new Set(); list.add(fn); this.handlers.set(event, list); return () => list.delete(fn); }

  async emit(event, payload = {}) {
    const envelope = { event, at: Date.now(), ...payload };
    for (const fn of this.handlers.get(event) || []) { try { await fn(envelope); } catch {} }
    this.dispatchEvent(new CustomEvent('hook', { detail: envelope }));
    if (!this.executor) return [];
    const results = [];
    for (const hook of this.hooks.filter((item) => item.enabled && item.event === event && item.tool)) {
      try { results.push({ id: hook.id, ok: true, result: await this.executor(hook.tool, { ...hook.args, __hook_event: event }, envelope) }); }
      catch (error) { results.push({ id: hook.id, ok: false, error: error?.message || String(error) }); }
    }
    return results;
  }
}
