import { nativeAvailable, nativeFetch } from '../native/native-bridge.js';
const STORAGE_KEY = 'blackriver.workspace.plugins.v1';
const MCP_LATEST = '2026-07-28';
const MCP_LEGACY = '2025-11-25';

function uid() {
  return crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function safeName(value = '') {
  return String(value || 'plugin').toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'plugin';
}

function parseSsePayload(text = '') {
  const chunks = String(text).split(/\r?\n/).filter((line) => line.startsWith('data:')).map((line) => line.slice(5).trim()).filter(Boolean);
  for (let i = chunks.length - 1; i >= 0; i--) {
    try { return JSON.parse(chunks[i]); } catch {}
  }
  return null;
}

export class PluginStore extends EventTarget {
  constructor() { super(); this.items = this.load(); }

  load() {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      return Array.isArray(parsed) ? parsed.map((item) => ({
        id: String(item.id || uid()), name: String(item.name || 'MCP server'), url: String(item.url || ''), enabled: item.enabled !== false,
        status: 'disconnected', error: '', tools: [], sessionId: '', protocolVersion: '',
        approval: ['allow', 'ask', 'deny'].includes(item.approval) ? item.approval : 'ask',
      })) : [];
    } catch { return []; }
  }

  save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.items.map(({ tools, status, error, sessionId, protocolVersion, ...item }) => item)));
    this.dispatchEvent(new Event('change'));
  }

  list() { return [...this.items]; }
  get(id) { return this.items.find((item) => item.id === id) || null; }

  add({ name, url }) {
    const plugin = { id: uid(), name: String(name || 'MCP server').slice(0, 100), url: String(url || '').trim(), enabled: true, status: 'disconnected', error: '', tools: [], sessionId: '', protocolVersion: '', approval: 'ask' };
    if (!/^https?:\/\//i.test(plugin.url)) throw new Error('MCP URL must start with http:// or https://');
    this.items.push(plugin); this.save(); return plugin;
  }

  update(id, patch = {}) {
    const plugin = this.get(id); if (!plugin) return null;
    if (patch.name !== undefined) plugin.name = String(patch.name || plugin.name).slice(0, 100);
    if (patch.url !== undefined) plugin.url = String(patch.url || plugin.url).trim();
    if (patch.enabled !== undefined) plugin.enabled = !!patch.enabled;
    if (patch.approval !== undefined && ['allow', 'ask', 'deny'].includes(patch.approval)) plugin.approval = patch.approval;
    this.save(); return plugin;
  }

  remove(id) { this.items = this.items.filter((item) => item.id !== id); this.save(); }
  disconnect(id) { const plugin = this.get(id); if (!plugin) return; plugin.status = 'disconnected'; plugin.error = ''; plugin.tools = []; plugin.sessionId = ''; plugin.protocolVersion = ''; this.dispatchEvent(new Event('change')); }

  async request(plugin, method, params = {}, { notification = false, protocolVersion = plugin.protocolVersion || MCP_LATEST } = {}) {
    const modern = protocolVersion === MCP_LATEST;
    const meta = modern ? { 'io.modelcontextprotocol/clientInfo': { name: 'BlackRiver Workspace', version: '3.0.1' } } : null;
    const requestParams = modern ? { ...(params || {}), _meta: { ...(params?._meta || {}), ...meta } } : params;
    const body = { jsonrpc: '2.0', method, ...(notification ? {} : { id: `${Date.now()}-${Math.random()}` }), ...(requestParams ? { params: requestParams } : {}) };
    const headers = { 'content-type': 'application/json', accept: 'application/json, text/event-stream' };
    if (modern) {
      headers['MCP-Protocol-Version'] = MCP_LATEST;
      headers['Mcp-Method'] = method;
      if (method === 'tools/call' && params?.name) headers['Mcp-Name'] = String(params.name);
    } else if (plugin.sessionId) {
      headers['Mcp-Session-Id'] = plugin.sessionId;
    }
    const requestInit = { method: 'POST', headers, body: JSON.stringify(body) };
    const response = nativeAvailable() ? await nativeFetch(plugin.url, requestInit) : await fetch(plugin.url, requestInit);
    if (!response.ok) throw new Error(`MCP ${response.status}: ${response.statusText}`);
    const sessionId = response.headers.get('mcp-session-id');
    if (sessionId) plugin.sessionId = sessionId;
    if (notification || response.status === 202 || response.status === 204) return null;
    const type = response.headers.get('content-type') || '';
    const json = type.includes('text/event-stream') ? parseSsePayload(await response.text()) : await response.json();
    if (!json) return null;
    if (json.error) throw new Error(json.error.message || 'MCP error');
    return json.result;
  }

  async connectModern(plugin) {
    plugin.protocolVersion = MCP_LATEST;
    // 2026-07-28 is stateless and no longer has initialize/initialized.
    const result = await this.request(plugin, 'tools/list', {}, { protocolVersion: MCP_LATEST });
    plugin.tools = Array.isArray(result?.tools) ? result.tools : [];
    return plugin;
  }

  async connectLegacy(plugin) {
    plugin.protocolVersion = MCP_LEGACY;
    const result = await this.request(plugin, 'initialize', { protocolVersion: MCP_LEGACY, capabilities: {}, clientInfo: { name: 'BlackRiver Workspace', version: '3.0.1' } }, { protocolVersion: MCP_LEGACY });
    if (result?.protocolVersion) plugin.protocolVersion = result.protocolVersion;
    await this.request(plugin, 'notifications/initialized', {}, { notification: true, protocolVersion: plugin.protocolVersion }).catch(() => null);
    const listed = await this.request(plugin, 'tools/list', {}, { protocolVersion: plugin.protocolVersion });
    plugin.tools = Array.isArray(listed?.tools) ? listed.tools : [];
    return plugin;
  }

  async connect(id) {
    const plugin = this.get(id); if (!plugin) throw new Error('Plugin not found.');
    plugin.status = 'connecting'; plugin.error = ''; plugin.tools = []; plugin.sessionId = ''; this.dispatchEvent(new Event('change'));
    try {
      try { await this.connectModern(plugin); }
      catch (modernError) {
        plugin.sessionId = '';
        try { await this.connectLegacy(plugin); }
        catch (legacyError) { throw new Error(`MCP 2026-07-28 failed (${modernError.message}); legacy fallback failed (${legacyError.message})`); }
      }
      plugin.status = 'connected'; plugin.error = ''; this.dispatchEvent(new Event('change')); return plugin;
    } catch (error) {
      plugin.status = 'error'; plugin.error = error?.message || String(error); plugin.tools = []; plugin.sessionId = ''; plugin.protocolVersion = '';
      this.dispatchEvent(new Event('change')); throw error;
    }
  }

  gatewayDefinitions() {
    return [
      {
        type: 'function',
        function: {
          name: 'list_mcp_tools',
          description: 'List connected BlackRiver MCP/plugin tools. Use this only when the current task needs an external plugin and the exact tool is not already exposed directly.',
          parameters: { type: 'object', properties: { query: { type: 'string', description: 'Optional short capability filter such as github pull request, slack, calendar, or browser.' } } },
        },
      },
      {
        type: 'function',
        function: {
          name: 'call_mcp_tool',
          description: 'Call one MCP/plugin tool returned by list_mcp_tools. arguments_json must be one JSON object encoded as a string.',
          parameters: {
            type: 'object',
            properties: {
              tool_name: { type: 'string', description: 'Exact exposed BlackRiver MCP tool name returned by list_mcp_tools.' },
              arguments_json: { type: 'string', description: 'JSON object string containing the tool arguments.' },
            },
            required: ['tool_name', 'arguments_json'],
          },
        },
      },
    ];
  }

  listGatewayTools(query = '') {
    const q = String(query || '').trim().toLowerCase();
    const words = [...new Set(q.match(/[a-z0-9][a-z0-9_-]{2,}/g) || [])].filter((word) => !['the','and','for','with','this','that','from','into','tool','tools','plugin','mcp'].includes(word));
    const domainHints = [
      [/\b(github|pull request|\bpr\b|issue|commit|branch|repository|repo)\b/i, /github|pull|issue|commit|branch|repo/i],
      [/\b(slack|channel|message)\b/i, /slack|channel|message/i],
      [/\b(calendar|meeting|event)\b/i, /calendar|meeting|event/i],
      [/\b(email|gmail|mail)\b/i, /gmail|email|mail/i],
      [/\b(browser|web|url|website|search online)\b/i, /browser|web|url|search/i],
    ];
    return this.toolDefinitions().map((tool) => {
      const entry = { name: tool.function.name, description: tool.function.description || '', parameters: tool.function.parameters || { type: 'object', properties: {} } };
      const haystack = `${entry.name} ${entry.description}`.toLowerCase();
      let score = q ? 0 : 1;
      for (const word of words) { if (entry.name.toLowerCase().includes(word)) score += 7; else if (haystack.includes(word)) score += 3; }
      for (const [promptRe, toolRe] of domainHints) if (promptRe.test(q) && toolRe.test(haystack)) score += 18;
      return { ...entry, score };
    }).filter((tool) => tool.score > 0).sort((a, b) => b.score - a.score || a.name.localeCompare(b.name)).slice(0, 24).map(({ score, ...tool }) => tool);
  }

  toolDefinitions() {
    const out = [];
    for (const plugin of this.items) {
      if (!plugin.enabled || plugin.status !== 'connected') continue;
      for (const tool of plugin.tools) out.push({ type: 'function', function: { name: `mcp__${safeName(plugin.id)}__${safeName(tool.name)}`.slice(0, 120), description: `[${plugin.name}] ${tool.description || tool.name}`, parameters: tool.inputSchema || { type: 'object', properties: {} } } });
    }
    return out;
  }

  resolveTool(name) {
    for (const plugin of this.items) {
      if (!plugin.enabled || plugin.status !== 'connected') continue;
      for (const tool of plugin.tools) {
        const exposed = `mcp__${safeName(plugin.id)}__${safeName(tool.name)}`.slice(0, 120);
        if (exposed === name) return { plugin, tool };
      }
    }
    return null;
  }

  async execute(name, args = {}, { approve } = {}) {
    if (name === 'list_mcp_tools') return { tools: this.listGatewayTools(args.query || '') };
    if (name === 'call_mcp_tool') {
      const toolName = String(args.tool_name || '');
      let parsed = {};
      try { parsed = JSON.parse(String(args.arguments_json || '{}')); } catch { throw new Error('arguments_json must be valid JSON.'); }
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('arguments_json must encode one JSON object.');
      return this.execute(toolName, parsed, { approve });
    }
    const resolved = this.resolveTool(name); if (!resolved) throw new Error(`MCP tool not found: ${name}`);
    const { plugin, tool } = resolved;
    if (plugin.approval === 'deny') return { status: 'denied', tool: tool.name };
    if (plugin.approval === 'ask') { const ok = await approve?.({ name, args, summary: `${plugin.name}: ${tool.name}` }); if (ok === false) return { status: 'denied', tool: tool.name }; }
    return (await this.request(plugin, 'tools/call', { name: tool.name, arguments: args }, { protocolVersion: plugin.protocolVersion })) || { status: 'ok' };
  }
}
