import { Capacitor, CapacitorHttp, registerPlugin } from '@capacitor/core';
import { nativeAvailable, nativeFetch } from '../native/native-bridge.js';
import { legacyReasoningProfile, llamaCppReasoningRequest, ollamaReasoningRequest, openAIReasoningRequest, reasoningUiDescriptor } from './reasoning-adapter.js';
function messageOf(error, fallback = 'API request failed.') {
  if (!error) return fallback;
  if (typeof error === 'string') return error;
  return error.message || String(error) || fallback;
}

function isCapacitorAndroid() {
  try { return Capacitor.getPlatform() === 'android'; } catch { return false; }
}

function normalizedHeaderObject(headers = {}) {
  const out = {};
  if (headers instanceof Headers) {
    headers.forEach((value, key) => { out[key] = value; });
    return out;
  }
  for (const [key, value] of Object.entries(headers || {})) {
    if (value != null) out[key] = String(value);
  }
  return out;
}

function responseBodyText(data, headers = {}) {
  if (data == null) return '';
  if (typeof data === 'string') return data;
  const contentType = String(headers?.['content-type'] || headers?.['Content-Type'] || '').toLowerCase();
  if (contentType.includes('application/json') || typeof data === 'object') {
    try { return JSON.stringify(data); } catch {}
  }
  return String(data);
}

const BlackRiverHttpStream = registerPlugin('BlackRiverHttpStream');
let androidStreamSequence = 0;

async function capacitorHttpStreamFetch(url, init = {}) {
  const requestId = `brstream_${Date.now().toString(36)}_${(++androidStreamSequence).toString(36)}`;
  const headers = normalizedHeaderObject(init.headers);
  const method = String(init.method || 'GET').toUpperCase();
  const body = init.body == null ? '' : String(init.body);
  const encoder = new TextEncoder();
  const signal = init.signal;
  let streamController = null;
  let ended = false;
  let receivedLength = 0;
  let deliveryChain = Promise.resolve();
  const listenerHandles = [];

  const cleanup = () => {
    for (const handle of listenerHandles.splice(0)) {
      try { handle?.remove?.(); } catch {}
    }
    document.removeEventListener?.('visibilitychange', onVisibilityChange);
    window.removeEventListener?.('focus', onVisibilityChange);
  };
  const finish = (error = null) => {
    if (ended) return;
    ended = true;
    try {
      if (error) streamController?.error(error);
      else streamController?.close();
    } catch {}
    cleanup();
    signal?.removeEventListener?.('abort', abort);
  };

  const enqueueAt = (text, start = receivedLength) => {
    if (ended) return;
    let value = String(text ?? '');
    let offset = Number.isFinite(Number(start)) ? Number(start) : receivedLength;
    if (!value) return;
    if (offset < receivedLength) {
      const overlap = receivedLength - offset;
      if (overlap >= value.length) return;
      value = value.slice(overlap);
      offset = receivedLength;
    }
    // If Android/WebView paused JavaScript while the app was backgrounded, a
    // native event can arrive with a gap. Do not invent text; snapshot() below
    // fills the retained native buffer before this event is committed.
    if (offset > receivedLength) return;
    try {
      streamController?.enqueue(encoder.encode(value));
      receivedLength += value.length;
    } catch {}
  };

  const reconcileSnapshot = async ({ settle = false } = {}) => {
    if (ended) return null;
    const snapshot = await BlackRiverHttpStream.snapshot({ requestId, from: receivedLength }).catch(() => null);
    if (!snapshot || snapshot?.missing) return snapshot;
    enqueueAt(String(snapshot.text || ''), Number(snapshot.start ?? receivedLength));
    if (settle && snapshot.done) {
      const message = String(snapshot.error || '').trim();
      if (message && !snapshot.cancelled) finish(new Error(message));
      else finish();
    }
    return snapshot;
  };

  const queue = (task) => {
    deliveryChain = deliveryChain.then(task).catch((error) => finish(error));
    return deliveryChain;
  };

  const onVisibilityChange = () => {
    if (document.visibilityState === 'visible' && !ended) queue(() => reconcileSnapshot({ settle: true }));
  };

  const stream = new ReadableStream({
    start(controller) { streamController = controller; },
    cancel() {
      if (!ended) BlackRiverHttpStream.cancel({ requestId }).catch(() => null);
      finish();
    },
  });

  listenerHandles.push(await BlackRiverHttpStream.addListener('chunk', (event) => {
    if (ended || event?.requestId !== requestId) return;
    queue(async () => {
      const start = Number(event?.start ?? receivedLength);
      if (start > receivedLength) await reconcileSnapshot({ settle: false });
      enqueueAt(String(event?.text ?? ''), start);
    });
  }));
  listenerHandles.push(await BlackRiverHttpStream.addListener('end', (event) => {
    if (event?.requestId !== requestId) return;
    queue(async () => {
      const snapshot = await reconcileSnapshot({ settle: false });
      const message = String(snapshot?.error || '').trim();
      if (message && !snapshot?.cancelled) finish(new Error(message));
      else finish();
    });
  }));
  listenerHandles.push(await BlackRiverHttpStream.addListener('error', (event) => {
    if (event?.requestId !== requestId) return;
    queue(async () => {
      const snapshot = await reconcileSnapshot({ settle: false });
      const message = String(snapshot?.error || event?.message || 'Android streaming request failed.');
      finish(new Error(message));
    });
  }));
  document.addEventListener?.('visibilitychange', onVisibilityChange);
  window.addEventListener?.('focus', onVisibilityChange);

  const abort = () => {
    BlackRiverHttpStream.cancel({ requestId }).catch(() => null);
    const error = new DOMException('The operation was aborted.', 'AbortError');
    finish(error);
  };
  if (signal?.aborted) {
    abort();
    throw new DOMException('The operation was aborted.', 'AbortError');
  }
  signal?.addEventListener?.('abort', abort, { once: true });

  try {
    const response = await BlackRiverHttpStream.request({
      requestId,
      url: String(url),
      method,
      headers,
      body,
      connectTimeout: 15_000,
      readTimeout: 60 * 60_000,
    });
    const responseHeaders = normalizedHeaderObject(response?.headers || {});
    // Pull once after the headers arrive. This also catches an ultra-fast local
    // response that completed before the renderer listeners had a chance to run.
    queue(() => reconcileSnapshot({ settle: true }));
    return new Response(stream, {
      status: Number(response?.status || 0) || 200,
      headers: responseHeaders,
    });
  } catch (error) {
    finish(error);
    throw error;
  }
}

async function capacitorHttpFetch(url, init = {}) {
  const method = String(init.method || 'GET').toUpperCase();
  const headers = normalizedHeaderObject(init.headers);
  const options = {
    url: String(url),
    method,
    headers,
    connectTimeout: 12_000,
    // Local inference can legitimately take minutes before the final body is returned.
    readTimeout: 10 * 60_000,
  };
  if (init.body != null && method !== 'GET' && method !== 'HEAD') {
    const body = init.body;
    if (typeof body === 'string' && /application\/json/i.test(headers['Content-Type'] || headers['content-type'] || '')) {
      try { options.data = JSON.parse(body); } catch { options.data = body; }
    } else {
      options.data = body;
    }
  }
  const nativeResponse = await CapacitorHttp.request(options);
  const responseHeaders = normalizedHeaderObject(nativeResponse?.headers || {});
  if (nativeResponse?.data && typeof nativeResponse.data === 'object' && !responseHeaders['content-type'] && !responseHeaders['Content-Type']) {
    responseHeaders['content-type'] = 'application/json';
  }
  return new Response(responseBodyText(nativeResponse?.data, responseHeaders), {
    status: Number(nativeResponse?.status || 0) || 200,
    headers: responseHeaders,
  });
}

async function platformFetch(url, init = {}) {
  const stream = !!init.__blackriverStream;
  const cleanInit = { ...init };
  delete cleanInit.__blackriverStream;
  if (isCapacitorAndroid()) return stream ? capacitorHttpStreamFetch(url, cleanInit) : capacitorHttpFetch(url, cleanInit);
  return fetch(url, cleanInit);
}

function baseRoot(baseUrl = '') {
  return String(baseUrl || '').trim().replace(/\/+$/, '').replace(/\/v1$/i, '');
}

function endpoint(baseUrl, path) {
  return `${baseRoot(baseUrl)}/v1/${String(path).replace(/^\/+/, '')}`;
}

function rootEndpoint(baseUrl, path) {
  return `${baseRoot(baseUrl)}/${String(path).replace(/^\/+/, '')}`;
}

function ollamaRoot(baseUrl = '') {
  return String(baseUrl || '').trim().replace(/\/+$/, '').replace(/\/(?:api|v1)$/i, '');
}

function ollamaEndpoint(baseUrl, path) {
  return `${ollamaRoot(baseUrl)}/api/${String(path).replace(/^\/+/, '')}`;
}

function headersFor(apiKey = '', accept = 'text/event-stream, application/json') {
  const headers = { 'Content-Type': 'application/json', Accept: accept };
  if (apiKey) headers.Authorization = `Bearer ${apiKey}`;
  return headers;
}

function hostOf(provider = {}) {
  try { return new URL(provider.baseUrl).hostname.toLowerCase(); }
  catch { return ''; }
}

function isLocalLlamaCpp(provider = {}) {
  if (provider?.flavor === 'llama.cpp') return true;
  return /llama\.?cpp/i.test(String(provider.name || ''));
}

function isOllamaProvider(provider = {}) {
  if (provider?.flavor === 'ollama') return true;
  if (hostOf(provider) === 'ollama.com') return true;
  if (/^ollama(?:\s|$)/i.test(String(provider.name || '').trim())) return true;
  try {
    const url = new URL(provider.baseUrl);
    if (url.port === '11434' && ['127.0.0.1', 'localhost', '::1'].includes(url.hostname)) return true;
  } catch {}
  return false;
}

function isOllamaCloud(provider = {}) {
  return hostOf(provider) === 'ollama.com';
}

function isOpenAIProvider(provider = {}) {
  try {
    const host = new URL(provider.baseUrl).hostname.toLowerCase();
    if (host === 'api.openai.com' || host.endsWith('.openai.com')) return true;
  } catch {}
  return /^openai(?:\s|$)/i.test(String(provider.name || '').trim());
}

function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  const step = 0x8000;
  for (let i = 0; i < bytes.length; i += step) binary += String.fromCharCode(...bytes.subarray(i, i + step));
  return btoa(binary);
}

function arrayBufferToDataUrl(buffer, mime = 'application/octet-stream') {
  return `data:${mime};base64,${arrayBufferToBase64(buffer)}`;
}

function normalizeMessages(messages = []) {
  return messages.map((message) => {
    if (!Array.isArray(message.content)) return message;
    const content = message.content.map((part) => {
      if (part?.type === 'text') return { type: 'text', text: String(part.text || '') };
      if (part?.type === 'image' && part.data instanceof ArrayBuffer) {
        return { type: 'image_url', image_url: { url: arrayBufferToDataUrl(part.data, part.mime || 'image/png') } };
      }
      if (part?.type === 'audio') throw new Error('Audio attachments are not enabled for API providers yet. Use BlackRiver Voice for speech input.');
      return part;
    });
    return { ...message, content };
  });
}

function dataUrlPayload(url = '') {
  const match = String(url || '').match(/^data:[^;,]+;base64,(.+)$/i);
  return match ? match[1] : '';
}

function safeObject(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string' || !value.trim()) return {};
  try { return JSON.parse(value); } catch { return {}; }
}

function normalizeOllamaMessages(messages = []) {
  const toolNames = new Map();
  return messages.map((message) => {
    const out = { role: message.role, content: '' };
    const images = [];

    if (Array.isArray(message.content)) {
      const text = [];
      for (const part of message.content) {
        if (part?.type === 'text') text.push(String(part.text || ''));
        else if (part?.type === 'image' && part.data instanceof ArrayBuffer) images.push(arrayBufferToBase64(part.data));
        else if (part?.type === 'image_url') {
          const payload = dataUrlPayload(part.image_url?.url || '');
          if (payload) images.push(payload);
        } else if (part?.type === 'audio') {
          throw new Error('Audio attachments are not enabled for Ollama providers yet. Use BlackRiver Voice for speech input.');
        }
      }
      out.content = text.join('\n');
    } else {
      out.content = message.content == null ? '' : String(message.content);
    }

    if (images.length) out.images = images;
    if (message.reasoning_content) out.thinking = String(message.reasoning_content);
    else if (message.reasoning) out.thinking = String(message.reasoning);

    if (Array.isArray(message.tool_calls) && message.tool_calls.length) {
      out.tool_calls = message.tool_calls.map((call) => {
        const name = String(call?.function?.name || '');
        if (call?.id && name) toolNames.set(call.id, name);
        return {
          type: 'function',
          function: {
            name,
            arguments: safeObject(call?.function?.arguments),
          },
        };
      });
    }

    if (message.role === 'tool') {
      out.tool_name = String(message.tool_name || toolNames.get(message.tool_call_id) || 'tool');
    }

    return out;
  });
}

function extractError(payload, status) {
  const message = payload?.error?.message || payload?.error || payload?.message || payload?.detail || '';
  return (typeof message === 'string' && message) || `API request failed with HTTP ${status}.`;
}

async function jsonIfPossible(res) {
  try { return await res.json(); } catch { return null; }
}

function browserOllamaRelayUrls(path) {
  if (typeof window === 'undefined' || !window.location?.origin) return [];
  const clean = String(path || '').replace(/^\/+/, '');
  const rewrite = new URL(`/__blackriver/ollama/${clean}`, window.location.origin).toString();
  const legacy = new URL('/api/ollama-cloud', window.location.origin);
  legacy.searchParams.set('path', clean);
  return [rewrite, legacy.toString()];
}

function isLoopbackUrl(url) {
  try {
    const host = new URL(url).hostname.toLowerCase();
    return host === '127.0.0.1' || host === 'localhost' || host === '::1' || host === '[::1]';
  } catch { return false; }
}

async function fetchBridgeUrl(url, init = {}) {
  if (!isLoopbackUrl(url)) return fetch(url, init);

  // Chromium 145+ distinguishes loopback access from normal Internet access.
  // Explicitly tagging the target lets the browser apply the Apps-on-device /
  // loopback permission and relax HTTPS->HTTP mixed-content blocking once the
  // user grants that permission. Unknown RequestInit keys are ignored by older
  // engines, and we retain a plain-CORS fallback for them.
  const localInit = { ...init, mode: 'cors', credentials: 'omit', targetAddressSpace: 'loopback' };
  // RequestInit is a WebIDL dictionary, so older engines ignore an unknown
  // targetAddressSpace member. Do not retry POST requests here: a CORS-visible
  // failure can happen after the upstream already received the body, and a
  // blind retry could create a duplicate inference.
  return fetch(url, localInit);
}

async function isMissingBridgeResponse(res) {
  if (!res) return false;
  const type = String(res.headers?.get?.('content-type') || '').toLowerCase();
  // Static SPA hosts often return index.html with HTTP 200 for unknown routes.
  // Treat HTML from a supposed JSON/SSE bridge as a missing bridge too.
  if (type.includes('text/html')) return true;
  if (res.status !== 404) return false;
  if (type.includes('text/plain')) return true;
  try {
    const text = await res.clone().text();
    return /page could not be found|not_found|404/i.test(text);
  } catch {
    return false;
  }
}

async function fetchFirstAvailableBridge(urls, init, label) {
  let lastError = null;
  for (const url of urls) {
    try {
      const res = await fetchBridgeUrl(url, init);
      if (await isMissingBridgeResponse(res)) {
        lastError = new Error(`${label} bridge route is not deployed at ${new URL(url).pathname}.`);
        continue;
      }
      return res;
    } catch (error) {
      lastError = error;
    }
  }
  const error = new Error(`${label} could not reach a browser-safe cloud transport. Use BlackRiver Desktop for native provider networking, or deploy the optional web relay routes.`);
  error.cause = lastError;
  throw error;
}

export class OpenAICompatibleRuntime extends EventTarget {
  constructor() {
    super();
    this.abortController = null;
    this.provider = null;
    this.modelId = '';
    this.contextHint = 0;
    this.modelInfo = null;
    this.modelInfoModelId = '';
    this.sampling = { temperature: 0.7, top_p: 0.95, top_k: 20, min_p: 0 };
  }

  configure(provider, modelId = '') {
    const nextProvider = provider ? { ...provider } : null;
    const nextModelId = String(modelId || provider?.lastModelId || provider?.modelIds?.[0] || '');
    const changed = this.provider?.id !== nextProvider?.id || this.modelId !== nextModelId;
    this.provider = nextProvider;
    this.modelId = nextModelId;
    if (changed) { this.contextHint = 0; this.modelInfo = null; this.modelInfoModelId = ''; }
    return this;
  }

  get isLoaded() { return !!(this.provider?.baseUrl && this.modelId); }

  get loaded() {
    if (!this.isLoaded) return null;
    return {
      source: 'api',
      name: this.modelId,
      modelId: this.modelId,
      providerId: this.provider.id,
      providerName: this.provider.name,
      baseUrl: this.provider.baseUrl,
    };
  }

  get contextSize() { return this.contextHint || 0; }
  get isLlamaCpp() { return isLocalLlamaCpp(this.provider); }
  get isOllama() { return isOllamaProvider(this.provider); }
  get capabilities() { return { image: true, audio: false, chatTemplate: true, multithread: true, threads: 0, tools: true, api: true, reasoning: true }; }

  setSampling(patch = {}) { this.sampling = { ...this.sampling, ...patch }; }

  async refreshModelInfo({ autoload = false } = {}) {
    if (!this.isLoaded) return null;
    if (this.isOllama) return this.refreshOllamaModelInfo();
    if (!this.isLlamaCpp) return null;
    try {
      const url = new URL(rootEndpoint(this.provider.baseUrl, 'props'));
      url.searchParams.set('model', this.modelId);
      url.searchParams.set('autoload', autoload ? 'true' : 'false');
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), autoload ? 180_000 : 6_000);
      try {
        const res = await platformFetch(url, {
          method: 'GET',
          headers: headersFor(this.provider.apiKey),
          signal: controller.signal,
        });
        if (!res.ok) return null;
        const payload = await res.json();
        this.modelInfo = payload;
        this.modelInfoModelId = this.modelId;
        const settings = payload?.default_generation_settings || payload?.defaultGenerationSettings || {};
        const nCtx = Number(settings.n_ctx ?? payload?.n_ctx ?? payload?.context_size ?? 0) || 0;
        if (nCtx > 0) {
          this.contextHint = nCtx;
          this.dispatchEvent(new CustomEvent('context', { detail: { contextSize: nCtx, source: 'server', payload } }));
        }
        return { contextSize: this.contextHint, payload };
      } finally {
        clearTimeout(timeout);
      }
    } catch {
      return null;
    }
  }

  async refreshOllamaModelInfo() {
    if (!this.isLoaded || !this.isOllama) return null;
    if (this.modelInfo && this.modelInfoModelId === this.modelId) return { contextSize: this.contextHint, payload: this.modelInfo };
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 8000);
    try {
      const res = await this.fetchOllama('show', {
        method: 'POST',
        headers: headersFor(this.provider.apiKey, 'application/json'),
        body: JSON.stringify({ model: this.modelId, verbose: false }),
        signal: controller.signal,
      });
      const payload = await jsonIfPossible(res);
      if (!res.ok) return null;
      this.modelInfo = payload || {};
      this.modelInfoModelId = this.modelId;
      const info = payload?.model_info || {};
      const contextEntry = Object.entries(info).find(([key]) => /context_length$/i.test(key));
      const nCtx = Number(contextEntry?.[1] || 0) || 0;
      if (nCtx > 0) {
        this.contextHint = nCtx;
        this.dispatchEvent(new CustomEvent('context', { detail: { contextSize: nCtx, source: 'ollama', payload } }));
      }
      return { contextSize: this.contextHint, payload };
    } catch {
      return null;
    } finally {
      clearTimeout(timeout);
    }
  }

  reasoningDescriptor(profile = 'auto') {
    if (this.isLlamaCpp) return reasoningUiDescriptor({ provider: 'llama.cpp', profile, modelId: this.modelId, payload: this.modelInfo || {} });
    if (this.isOllama) return reasoningUiDescriptor({ provider: 'ollama', profile, modelId: this.modelId, modelInfo: this.modelInfo || null });
    return reasoningUiDescriptor({ provider: 'openai', profile, modelId: this.modelId });
  }

  async fetchOllama(path, init = {}, provider = this.provider) {
    const directUrl = ollamaEndpoint(provider.baseUrl, path);
    if (nativeAvailable()) return nativeFetch(directUrl, init, { credentialId: provider?.credentialId || '' });
    const transport = provider.transport || (isOllamaCloud(provider) ? 'auto' : 'direct');
    const tryDirect = transport !== 'relay';
    let directError = null;

    if (tryDirect) {
      try {
        return await platformFetch(directUrl, init);
      } catch (error) {
        directError = error;
        if (transport === 'direct' || !isOllamaCloud(provider)) throw error;
      }
    }

    if (!isOllamaCloud(provider)) throw directError || new Error('Ollama relay is only available for ollama.com.');
    const relays = browserOllamaRelayUrls(path);
    if (!relays.length) throw directError || new Error('The optional Ollama web relay is unavailable outside the browser build.');
    return fetchFirstAvailableBridge(relays, init, 'Ollama Cloud');
  }

  async fetchOpenAI(path, init = {}, provider = this.provider) {
    const directUrl = endpoint(provider.baseUrl, path);
    if (nativeAvailable()) return nativeFetch(directUrl, init, { credentialId: provider?.credentialId || '' });
    return platformFetch(directUrl, init);
  }

  async discoverModels(provider = this.provider) {
    if (!provider?.baseUrl) throw new Error('Enter an API base URL first.');
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 12_000);
    try {
      if (isOllamaProvider(provider)) {
        const res = await this.fetchOllama('tags', {
          method: 'GET',
          headers: headersFor(provider.apiKey, 'application/json'),
          signal: controller.signal,
        }, provider);
        const payload = await jsonIfPossible(res);
        if (!res.ok) throw new Error(extractError(payload, res.status));
        const data = Array.isArray(payload?.models) ? payload.models : [];
        const models = data
          .map((entry) => typeof entry === 'string' ? { id: entry } : ({ id: entry?.name || entry?.model || '', meta: entry }))
          .filter((entry) => entry.id)
          .map((entry) => ({ id: String(entry.id), ownedBy: 'ollama', meta: entry.meta || null }));
        if (!models.length) throw new Error('Connected to Ollama, but /api/tags returned no model IDs.');
        return models;
      }

      const res = await this.fetchOpenAI('models', {
        method: 'GET',
        headers: headersFor(provider.apiKey, 'application/json'),
        signal: controller.signal,
      }, provider);
      const payload = await jsonIfPossible(res);
      if (!res.ok) throw new Error(extractError(payload, res.status));
      const data = Array.isArray(payload?.data) ? payload.data : Array.isArray(payload) ? payload : [];
      const models = data
        .map((entry) => typeof entry === 'string' ? { id: entry } : entry)
        .filter((entry) => entry?.id)
        .map((entry) => ({ id: String(entry.id), ownedBy: String(entry.owned_by || entry.ownedBy || ''), meta: entry.meta || entry.metadata || null }));
      if (!models.length) throw new Error('Connected, but /v1/models returned no model IDs.');
      return models;
    } catch (error) {
      if (error?.name === 'AbortError') throw new Error('Connection timed out. Check the provider URL and network access.');
      if (/failed to fetch|networkerror/i.test(messageOf(error))) {
        if (isOllamaCloud(provider)) throw new Error('Ollama Cloud is blocked by browser networking/CORS. Use BlackRiver Desktop for account-native networking, or configure the optional web relay.');
        throw new Error(isCapacitorAndroid() ? 'Could not reach this API from Android native HTTP. Check the server URL, Wi-Fi/LAN reachability, and that the server is listening on 0.0.0.0 rather than localhost only.' : 'Could not reach this API from the browser. Check that the server is running and allows this Workspace origin through CORS.');
      }
      throw error;
    } finally {
      clearTimeout(timeout);
    }
  }

  async chatOllama(params, onChunk = null) {
    const messages = normalizeOllamaMessages(params.messages);
    if (!this.modelInfo || this.modelInfoModelId !== this.modelId) await this.refreshOllamaModelInfo();
    const profile = legacyReasoningProfile(params, 'auto');
    const reasoning = ollamaReasoningRequest({ profile, modelId: this.modelId, modelInfo: this.modelInfo });

    const request = {
      model: this.modelId,
      messages,
      stream: true,
      ...(params.tools?.length ? { tools: params.tools } : {}),
      ...reasoning.request,
      options: {
        temperature: params.temperature ?? this.sampling.temperature,
        top_p: params.top_p ?? this.sampling.top_p,
      },
    };

    const startedAt = performance.now();
    const emitOllama = (chunk) => {
      const message = chunk?.message || {};
      const toolCalls = Array.isArray(message.tool_calls) ? message.tool_calls.map((tc, index) => ({
        index,
        id: tc.id || `ollama_call_${Date.now().toString(36)}_${index}`,
        type: 'function',
        function: {
          name: String(tc?.function?.name || ''),
          arguments: typeof tc?.function?.arguments === 'string' ? tc.function.arguments : JSON.stringify(tc?.function?.arguments || {}),
        },
      })) : [];
      const promptTokens = Number(chunk?.prompt_eval_count || 0) || 0;
      const completionTokens = Number(chunk?.eval_count || 0) || 0;
      const elapsedSec = Math.max(0.001, (performance.now() - startedAt) / 1000);
      const evalDurationSec = Number(chunk?.eval_duration || 0) / 1e9;
      const tps = completionTokens && evalDurationSec > 0 ? completionTokens / evalDurationSec : completionTokens / elapsedSec;
      onChunk?.({
        model: chunk?.model || this.modelId,
        choices: [{
          delta: {
            ...(message.content ? { content: message.content } : {}),
            ...(message.thinking ? { reasoning_content: message.thinking } : {}),
            ...(toolCalls.length ? { tool_calls: toolCalls } : {}),
          },
          finish_reason: chunk?.done ? (chunk?.done_reason || 'stop') : null,
        }],
        usage: promptTokens || completionTokens ? {
          prompt_tokens: promptTokens,
          completion_tokens: completionTokens,
          total_tokens: promptTokens + completionTokens,
        } : undefined,
        timings: {
          predicted_n: completionTokens,
          predicted_per_second: tps || 0,
        },
      });
    };

    try {
      const res = await this.fetchOllama('chat', {
        method: 'POST',
        headers: headersFor(this.provider.apiKey, 'application/x-ndjson, application/json'),
        body: JSON.stringify(request),
        signal: this.abortController.signal,
        __blackriverStream: isCapacitorAndroid(),
      });
      if (!res.ok) {
        const payload = await jsonIfPossible(res);
        throw new Error(extractError(payload, res.status));
      }
      // Ollama Cloud can stream newline-delimited JSON while reporting a generic
      // application/json content type. Do not call res.json() here: one JSON
      // object per line is valid for Ollama streaming but invalid as one document.
      // The line parser below also handles a normal single JSON response as its tail.
      if (!res.body) throw new Error('Ollama returned no response stream.');

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      while (true) {
        const { value, done } = await reader.read();
        buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
        let newline;
        while ((newline = buffer.indexOf('\n')) >= 0) {
          const line = buffer.slice(0, newline).trim();
          buffer = buffer.slice(newline + 1);
          if (!line) continue;
          try { emitOllama(JSON.parse(line)); } catch {}
        }
        if (done) break;
      }
      const tail = buffer.trim();
      if (tail) {
        try { emitOllama(JSON.parse(tail)); } catch {}
      }
    } catch (error) {
      if (error?.name === 'AbortError') {
        const abortError = new Error('Request cancelled.');
        abortError.name = 'AbortError';
        throw abortError;
      }
      if (/failed to fetch|networkerror/i.test(messageOf(error))) {
        if (nativeAvailable()) throw new Error('Ollama could not be reached by BlackRiver Desktop. Check that the Ollama app is running, then retry.');
        if (isOllamaCloud(this.provider)) throw new Error('Ollama Cloud is blocked by browser networking/CORS. Use BlackRiver Desktop for the account-native Ollama path, or configure the optional web relay.');
        throw new Error('Ollama connection failed. Check the provider URL, CORS policy, and whether Ollama is running.');
      }
      throw error;
    }
  }

  async chat(params, onChunk = null) {
    if (!this.isLoaded) throw new Error('Choose an API model first.');
    this.abortController = new AbortController();
    const llamaCpp = isLocalLlamaCpp(this.provider);
    if (llamaCpp && !this.contextHint) await this.refreshModelInfo({ autoload: true });
    if (isOllamaProvider(this.provider)) {
      try { return await this.chatOllama(params, onChunk); }
      finally { this.abortController = null; }
    }

    const messages = normalizeMessages(params.messages);
    const request = {
      model: this.modelId,
      messages,
      temperature: params.temperature ?? this.sampling.temperature,
      top_p: params.top_p ?? this.sampling.top_p,
      stream: true,
      ...(params.tools?.length ? { tools: params.tools, tool_choice: params.tool_choice || 'auto' } : {}),
    };

    if (!llamaCpp && Number.isFinite(Number(params.max_tokens)) && Number(params.max_tokens) > 0) request.max_tokens = Number(params.max_tokens);

    if (llamaCpp) {
      request.stream_options = { include_usage: true };
      if (Number.isFinite(params.top_k ?? this.sampling.top_k)) request.top_k = params.top_k ?? this.sampling.top_k;
      if (Number.isFinite(params.min_p ?? this.sampling.min_p)) request.min_p = params.min_p ?? this.sampling.min_p;
      const profile = legacyReasoningProfile(params, 'auto');
      const reasoning = llamaCppReasoningRequest({ profile, modelId: this.modelId, payload: this.modelInfo || {} });
      Object.assign(request, reasoning.request);
      request.cache_prompt = true;
      request.return_progress = true;
      request.timings_per_token = true;
    } else if (isOpenAIProvider(this.provider)) {
      request.stream_options = { include_usage: true };
      const profile = legacyReasoningProfile(params, 'auto');
      Object.assign(request, openAIReasoningRequest({ profile }).request);
    }

    const startedAt = performance.now();
    let completionTokens = 0;
    let promptTokens = 0;
    const speedSamples = [];
    try {
      const res = await this.fetchOpenAI('chat/completions', {
        method: 'POST',
        headers: headersFor(this.provider.apiKey),
        body: JSON.stringify(request),
        signal: this.abortController.signal,
        __blackriverStream: isCapacitorAndroid(),
      }, this.provider);
      if (!res.ok) {
        const payload = await jsonIfPossible(res);
        throw new Error(extractError(payload, res.status));
      }
      const contentType = res.headers.get('content-type') || '';
      if (/application\/json/i.test(contentType)) {
        const payload = await res.json();
        const choice = payload?.choices?.[0];
        const message = choice?.message;
        if (message) {
          const delta = {};
          if (message.content != null) delta.content = message.content;
          if (message.reasoning_content != null) delta.reasoning_content = message.reasoning_content;
          else if (message.reasoning != null) delta.reasoning = message.reasoning;
          if (Array.isArray(message.tool_calls)) delta.tool_calls = message.tool_calls.map((tc, index) => ({ ...tc, index: tc.index ?? index }));
          onChunk?.({ ...payload, choices: [{ ...choice, delta }] });
        } else onChunk?.(payload);
        return;
      }
      if (!res.body) throw new Error('The API returned no response stream.');

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      const emit = (chunk) => {
        const usage = chunk?.usage;
        if (usage) {
          promptTokens = Number(usage.prompt_tokens || promptTokens) || promptTokens;
          completionTokens = Number(usage.completion_tokens || completionTokens) || completionTokens;
        }
        const delta = chunk?.choices?.[0]?.delta || {};
        if (delta.content) completionTokens += Math.max(1, Math.round(String(delta.content).length / 4));
        const now = performance.now();
        const elapsedSec = Math.max(0.001, (now - startedAt) / 1000);
        const predictedN = Number(chunk?.timings?.predicted_n ?? completionTokens) || completionTokens;
        if (predictedN >= 0) {
          speedSamples.push({ t: now, n: predictedN });
          while (speedSamples.length > 2 && speedSamples[1].t < now - 3000) speedSamples.shift();
        }
        let rollingTps = 0;
        if (speedSamples.length >= 2) {
          const first = speedSamples[0];
          const last = speedSamples[speedSamples.length - 1];
          const dt = (last.t - first.t) / 1000;
          const dn = last.n - first.n;
          if (dt >= 0.20 && dn > 0) rollingTps = dn / dt;
        }
        onChunk?.({
          ...chunk,
          usage: usage || (promptTokens || completionTokens ? { prompt_tokens: promptTokens, completion_tokens: completionTokens, total_tokens: promptTokens + completionTokens } : undefined),
          timings: {
            ...(chunk?.timings || {}),
            predicted_n: predictedN,
            predicted_per_second: Number(chunk?.timings?.predicted_per_second ?? (completionTokens / elapsedSec)) || 0,
            predicted_per_second_3s: rollingTps,
          },
        });
      };

      while (true) {
        const { value, done } = await reader.read();
        buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
        if (buffer.includes('\r')) buffer = buffer.replace(/\r\n/g, '\n');
        let boundary;
        while ((boundary = buffer.indexOf('\n\n')) >= 0) {
          const event = buffer.slice(0, boundary);
          buffer = buffer.slice(boundary + 2);
          for (const line of event.split(/\r?\n/)) {
            const trimmed = line.trim();
            if (!trimmed.startsWith('data:')) continue;
            const data = trimmed.slice(5).trim();
            if (!data || data === '[DONE]') continue;
            try { emit(JSON.parse(data)); } catch {}
          }
        }
        if (done) break;
      }
    } catch (error) {
      if (error?.name === 'AbortError') {
        const abortError = new Error('Request cancelled.');
        abortError.name = 'AbortError';
        throw abortError;
      }
      if (/failed to fetch|networkerror/i.test(messageOf(error))) {
        if (nativeAvailable()) throw new Error('The provider could not be reached by BlackRiver Desktop. Check the provider URL and whether the service is available.');
        if (isCapacitorAndroid()) throw new Error('The provider could not be reached from Android native HTTP. Check LAN reachability and the server bind address.');
        throw new Error('API connection failed. Check the provider URL, CORS policy, and whether the server is still running.');
      }
      throw error;
    } finally {
      this.abortController = null;
    }
  }

  stop() {
    this.abortController?.abort();
    this.abortController = null;
  }
}

export { isOllamaProvider, isOllamaCloud };
