const VALID_MODES = new Set(['auto', 'on', 'off']);

function cleanId(value = '') {
  return String(value || 'skill').toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 64) || 'skill';
}

function stripQuotes(value = '') {
  const text = String(value || '').trim();
  if ((text.startsWith('"') && text.endsWith('"')) || (text.startsWith("'") && text.endsWith("'"))) return text.slice(1, -1);
  return text;
}

function parseFrontmatter(markdown = '', filename = 'skill.md') {
  const source = String(markdown || '').replace(/^\uFEFF/, '');
  let body = source;
  const meta = {};
  const match = source.match(/^---\s*\r?\n([\s\S]*?)\r?\n---\s*(?:\r?\n|$)/);
  if (match) {
    body = source.slice(match[0].length).trim();
    for (const line of match[1].split(/\r?\n/)) {
      const pair = line.match(/^([A-Za-z0-9_-]+)\s*:\s*(.*)$/);
      if (!pair) continue;
      meta[pair[1].toLowerCase()] = stripQuotes(pair[2]);
    }
  }
  const fallbackName = String(filename || 'skill').replace(/\.md$/i, '').replace(/^skill$/i, 'Imported skill').replace(/[-_]+/g, ' ').trim();
  const heading = body.match(/^#\s+(.+)$/m)?.[1]?.trim();
  const firstProse = body.split(/\r?\n/).map((line) => line.trim()).find((line) => line && !/^#|^[-*]\s|^```/.test(line));
  const name = (meta.name || heading || fallbackName || 'Imported skill').slice(0, 80);
  const description = (meta.description || firstProse || `Imported from ${filename}`).replace(/\s+/g, ' ').slice(0, 260);
  const triggerText = meta.triggers || meta.keywords || '';
  const triggers = triggerText ? triggerText.split(/[,|]/).map((item) => item.trim().toLowerCase()).filter(Boolean).slice(0, 32) : [];
  return { name, description, body: body || source.trim(), triggers };
}

function tokens(value = '') {
  return [...new Set(String(value || '').toLowerCase().match(/[a-z0-9][a-z0-9+.#_-]{2,}/g) || [])];
}

function signal(text = '', pattern) {
  return !!pattern && pattern.test(String(text || ''));
}

function autoGate(skillId, text, { mode = 'chat' } = {}) {
  if (mode !== 'work') return true;
  const creation = /\b(create|build|make|implement|write|generate|develop|produce|craft|code|design|prototype|simulation|simulator)\b/i.test(text);
  const three = /\b(three\.?js|threejs|webgl|3d scene|3d world|procedural 3d)\b/i.test(text);
  const fps = /\b(fps|first[- ]person shooter|shooter|gun|weapon|hitscan|recoil|crosshair|ammo|reload|muzzle flash|zombie fps|subway fps|metro fps)\b/i.test(text);
  const horror = /\b(zombie|undead|survival horror|horror|monster|liminal|dark corridor|wave survival)\b/i.test(text);
  const environment = /\b(procedural (?:environment|world|city|terrain)|environment|scenery|landscape|city|subway|metro|temple|pagoda|torii|forest|ruins|terrain|no external assets|no assets)\b/i.test(text);
  const camera = /\b(camera|orbit|flythrough|fly through|first[- ]person camera|third[- ]person camera|camera shake|dolly|cinematic)\b/i.test(text);
  const shader = /\b(shader|glsl|vfx|particles?|fog|water|ripple|waves?|fire|smoke|rain|snow|bloom|post[- ]?processing|reflection|refraction)\b/i.test(text);
  const physics = /\b(physics|wave propagation|simulation|60 ?fps|90 ?hz|120 ?hz|144 ?hz|refresh rate|delta time|fixed timestep|collision|velocity|acceleration)\b/i.test(text);
  const audio = /\b(web ?audio|audio|sound design|sound effects|sfx|music|ambience|procedural audio|spatial audio)\b/i.test(text);
  const level = /\b(procedural level|level generation|dungeon|maze|rooms|spawn system|random map|map generation|level design)\b/i.test(text);
  const mobile = /\b(android|ios|mobile|phone|tablet|touch controls|safe area|orientation|background resume|visibilitychange|high refresh)\b/i.test(text);
  const perf = /\b(performance|optimi[sz]|frame time|draw calls|instancing|gpu|512x512|512×512|subdivisions?|height ?field|render targets?|ping[- ]pong|real[- ]time|simulation|particles?)\b/i.test(text);
  const explicitBenchmark = /\b(benchmark|one[- ]shot|single[- ]prompt|twitter benchmark|x benchmark|youtube benchmark|coding benchmark)\b/i.test(text);
  const constrainedOneShot = creation && three
    && /\b(single html|single[- ]file|single file|everything in (?:a )?single|no external librar|no external assets|no assets)\b/i.test(text);

  switch (skillId) {
    case 'threejs-worldsmith': return three;
    case 'fps-combat-engineer': return fps;
    case 'survival-horror-director': return horror;
    case 'procedural-environment-architect': return environment;
    case 'cinematic-camera-director': return camera || (three && explicitBenchmark);
    case 'shader-vfx-smith': return shader;
    case 'procedural-level-designer': return level;
    case 'game-feel-physics': return physics;
    case 'web-audio-sound-designer': return audio;
    case 'webgl-performance-engineer': return three && perf;
    case 'benchmark-one-shot-director': return explicitBenchmark || constrainedOneShot;
    case 'mobile-game-runtime': return mobile;
    case 'release-commander': return /\b(release|zip|archive|package|installer|changelog|migration|baseline|deploy|ship|distribution|apk|desktop build|android build)\b/i.test(text);
    default: return true;
  }
}

