function normalizedBuiltin(item, saved = {}) {
  return { ...item, builtin: true, mode: VALID_MODES.has(saved.mode) ? saved.mode : 'auto' };
}

export class SkillStore extends EventTarget {
  constructor() {
    super();
    this.custom = [];
    this.builtinModes = {};
    this.load();
  }

  load() {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
      this.builtinModes = parsed.builtinModes && typeof parsed.builtinModes === 'object' ? parsed.builtinModes : {};
      this.custom = Array.isArray(parsed.custom) ? parsed.custom.map((item) => ({
        id: cleanId(item.id || item.name), name: String(item.name || 'Imported skill').slice(0, 80),
        description: String(item.description || '').slice(0, 260), instructions: String(item.instructions || '').slice(0, 120000),
        triggers: Array.isArray(item.triggers) ? item.triggers.map(String).slice(0, 32) : [],
        mode: VALID_MODES.has(item.mode) ? item.mode : 'auto', builtin: false, importedAt: Number(item.importedAt || Date.now()),
      })).filter((item) => item.instructions) : [];
    } catch { this.builtinModes = {}; this.custom = []; }
  }

  save() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify({ builtinModes: this.builtinModes, custom: this.custom })); } catch {}
    this.dispatchEvent(new Event('change'));
  }

  list() {
    return [
      ...BUILTINS.map((item) => normalizedBuiltin(item, { mode: this.builtinModes[item.id] })),
      ...this.custom.map((item) => ({ ...item })),
    ];
  }

  get(id) { return this.list().find((item) => item.id === id) || null; }

  setMode(id, mode) {
    if (!VALID_MODES.has(mode)) return null;
    const builtin = BUILTINS.find((item) => item.id === id);
    if (builtin) this.builtinModes[id] = mode;
    else {
      const item = this.custom.find((entry) => entry.id === id);
      if (!item) return null;
      item.mode = mode;
    }
    this.save();
    return this.get(id);
  }

  remove(id) {
    const before = this.custom.length;
    this.custom = this.custom.filter((item) => item.id !== id);
    if (this.custom.length !== before) this.save();
    return this.custom.length !== before;
  }

  importMarkdown(filename, markdown) {
    const source = String(markdown || '');
    if (!source.trim()) throw new Error('The skill file is empty.');
    if (source.length > 120000) throw new Error('Skill files are limited to 120 KB to keep context predictable.');
    const parsed = parseFrontmatter(source, filename);
    const base = cleanId(parsed.name);
    let id = base;
    let suffix = 2;
    const reserved = new Set(this.list().map((item) => item.id));
    while (reserved.has(id)) id = `${base.slice(0, 58)}-${suffix++}`;
    const item = {
      id, name: parsed.name, description: parsed.description,
      instructions: parsed.body.slice(0, 120000), triggers: parsed.triggers,
      mode: 'auto', builtin: false, importedAt: Date.now(), filename: String(filename || 'SKILL.md').slice(0, 160),
    };
    this.custom.push(item);
    this.save();
    return { ...item };
  }

  resolve(prompt, { mode = 'chat', hasProject = false, hasArtifacts = false, maxAuto = 4 } = {}) {
    const text = String(prompt || '').toLowerCase();
    const promptTokens = new Set(tokens(text));
    const active = [];
    const auto = [];
    const namedGameIntent = /\b(space invaders?|flappy bird|tetris|pong|snake|pac[- ]?man|breakout|asteroids|frogger)\b/i.test(text);
    const threeJsIntent = /\b(three\.?js|threejs|webgl|3d scene|3d world|pagoda|torii|japanese temple|procedural 3d)\b/i.test(text);
    const fpsIntent = /\b(fps|first[- ]person shooter|zombie fps|subway zombie|metro zombie|hitscan|crosshair|reload|muzzle flash|gun|weapon)\b/i.test(text);
    const proceduralWorldIntent = /\b(no external assets|procedural (?:world|environment|level|city|terrain)|subway|metro|temple|pagoda|landscape)\b/i.test(text);
    const explicitBenchmarkIntent = /\b(benchmark|one[- ]shot|single[- ]prompt|twitter benchmark|x benchmark|youtube benchmark|coding benchmark)\b/i.test(text);
    const constrainedOneShotIntent = mode === 'work' && threeJsIntent
      && /\b(single html|single[- ]file|single file|everything in (?:a )?single|no external librar|no external assets|no assets)\b/i.test(text)
      && /\b(create|build|make|implement|write|generate|develop|simulation|simulator)\b/i.test(text);
    const benchmarkIntent = explicitBenchmarkIntent || constrainedOneShotIntent;
    const highRefreshIntent = /\b(60 ?fps|90 ?hz|120 ?hz|144 ?hz|refresh rate|delta time|fixed timestep|wave propagation|physics)\b/i.test(text);
    const shaderIntent = /\b(shader|glsl|vfx|water|ripple|waves?|particles?|fog|fire|smoke|reflection|refraction)\b/i.test(text);
    const webglPerfIntent = threeJsIntent && /\b(512x512|512×512|subdivisions?|simulation|height ?field|render targets?|ping[- ]pong|real[- ]time|performance|gpu|particles?)\b/i.test(text);

    for (const skill of this.list()) {
      if (skill.mode === 'off') continue;
      if (skill.mode === 'on') { active.push({ ...skill, reason: 'on' }); continue; }
      if (!autoGate(skill.id, text, { mode })) continue;

      let score = 0;
      for (const trigger of skill.triggers || []) {
        const t = String(trigger).toLowerCase().trim();
        if (!t) continue;
        // Auto Skills v2: single-word triggers are exact tokens. The old substring
        // fallback could activate UI from “build” (contains “ui”) and similar noise.
        const matched = t.includes(' ') ? text.includes(t) : promptTokens.has(t);
        if (matched) score += t.length > 7 ? 3 : 2;
      }
      // Description/name similarity is only a tie-breaker after a real trigger hit.
      // This prevents specialist personas from activating on generic metadata words.
      if (score > 0) {
        const metaWords = tokens(`${skill.name} ${skill.description}`).filter((word) => word.length >= 5);
        for (const word of metaWords) if (promptTokens.has(word)) score += 1;
      }

      if (mode === 'work' && namedGameIntent && skill.id === 'indie-game-director') score += 7;
      if (mode === 'work' && namedGameIntent && skill.id === 'artifact-forge') score += 5;
      if (mode === 'work' && threeJsIntent && skill.id === 'threejs-worldsmith') score += 10;
      if (mode === 'work' && shaderIntent && skill.id === 'shader-vfx-smith') score += 8;
      if (mode === 'work' && webglPerfIntent && skill.id === 'webgl-performance-engineer') score += 11;
      if (mode === 'work' && threeJsIntent && explicitBenchmarkIntent && skill.id === 'cinematic-camera-director') score += 5;
      if (mode === 'work' && proceduralWorldIntent && skill.id === 'procedural-environment-architect') score += 8;
      if (mode === 'work' && fpsIntent && skill.id === 'fps-combat-engineer') score += 10;
      if (mode === 'work' && /\b(zombie|horror|undead|monster)\b/i.test(text) && skill.id === 'survival-horror-director') score += 8;
      if (mode === 'work' && benchmarkIntent && skill.id === 'benchmark-one-shot-director') score += constrainedOneShotIntent ? 11 : 9;
      if (mode === 'work' && highRefreshIntent && skill.id === 'game-feel-physics') score += 9;

      if (score > 0 && hasProject && ['code-surgeon','repo-cartographer','verification-gate'].includes(skill.id)) score += 1;
      if (score > 0 && mode === 'work' && ['artifact-forge','indie-game-director','interface-finisher'].includes(skill.id)) score += 1;
      if (score >= 2) auto.push({ ...skill, score, reason: 'auto' });
    }

    auto.sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));
    const seen = new Set(active.map((item) => item.id));
    for (const item of auto) {
      if (seen.has(item.id) || active.filter((entry) => entry.reason === 'auto').length >= maxAuto) continue;
      active.push(item); seen.add(item.id);
      if (active.filter((entry) => entry.reason === 'auto').length >= maxAuto) break;
    }
    return active;
  }

}

export { BUILTINS, parseFrontmatter };
