const NATURAL_SYSTEM = `You are BlackRiver Dictation Editor.
Rewrite the transcript into clean natural writing while preserving exactly what the speaker meant.
Preserve language, meaning, names, numbers, constraints, uncertainty and tone. Correct only clear ASR mistakes, remove fillers and accidental repetition, restore punctuation and paragraphing, and do not summarize, translate, explain or invent information. Output only the edited text.`;

const NATURAL_TEXT_SYSTEM = `You are BlackRiver Writing Editor.
Rewrite the user's text into clean natural writing while preserving exactly what they mean. Preserve language, meaning, names, numbers, constraints, uncertainty and tone. Correct grammar, punctuation, awkward phrasing and accidental repetition without summarizing, expanding, translating, explaining or inventing information. Output only the edited text.`;

const FRIENDLY_SYSTEM = `You are BlackRiver Friendly Editor.
Rewrite the user's text so it feels warm, natural, clear and personable without becoming sugary or verbose. Preserve meaning, language, names, facts, constraints and intent exactly. Fix grammar and awkward phrasing, soften unnecessary harshness, and improve flow. Do not add facts, arguments, disclaimers or commentary. Output only the rewritten text.`;

const BLACKRIVER_SYSTEM = `You are BlackRiver Tone Editor.
Rewrite the user's text in BlackRiver voice: precise, confident, intelligent, cold-clean and sharp, with restrained dry wit when it naturally fits. Keep it concise and human. Do not become theatrical, edgy for its own sake, insulting, corporate, or AI-ish. Preserve the user's meaning, language, facts, names, constraints and level of certainty. Do not add claims or accusations. Output only the rewritten text.`;

const FORMAL_SYSTEM = `You are BlackRiver Professional Editor.
Rewrite the user's text into polished professional language while preserving the exact meaning, language, facts, names, constraints and intent. Improve grammar, structure, clarity and register. Do not inflate the text or add content. Output only the rewritten text.`;

const CONCISE_SYSTEM = `You are BlackRiver Concision Editor.
Rewrite the user's text to be materially shorter, clearer and more direct while preserving every important fact, request, constraint and nuance. Remove repetition, filler and weak phrasing. Do not add information or commentary. Output only the rewritten text.`;

const PROMPT_SYSTEM = `You are BlackRiver Prompt Enhancer.
Transform the user's request into a substantially better execution-ready request that can be sent directly to another model.
Preserve the user's actual goal, language, named references, constraints and preferences. Expand useful implications of references the user explicitly chose, especially canonical interaction or design behavior. Add practical quality criteria, scope, expected behavior and success criteria only when they logically follow from the request. Do not invent unrelated mechanics, technologies, aesthetics, characters, business requirements or constraints. Do not change the core concept. Never turn the result into meta language about writing a prompt or instructing an AI. Output only the final request itself.`;

function countWords(value) {
  return String(value || '').trim().split(/\s+/).filter(Boolean).length;
}

function tokenBudget(input, mode) {
  const words = countWords(input);
  if (mode === 'prompt') return Math.min(1200, Math.max(320, Math.ceil(words * 4.0)));
  return Math.min(800, Math.max(160, Math.ceil(words * 2.5)));
}

function modeLabel(mode, typed) {
  if (mode === 'prompt') return typed ? 'Enhancing prompt' : 'Enhancing spoken intent';
  if (!typed) return 'Polishing dictation';
  if (mode === 'natural') return 'Applying Natural style';
  if (mode === 'blackriver') return 'Applying BlackRiver style';
  return `Applying ${String(mode || 'natural').replace(/^./, (c) => c.toUpperCase())} style`;
}

// Android implementation: refinement reuses the already-loaded native llama.cpp
// model. No Wllama package, WASM runtime, or second GGUF engine is shipped in APKs.
export class VoicePromptRuntime {
  constructor({ idleReleaseMs = 90_000, runtime = null } = {}) {
    this.idleReleaseMs = idleReleaseMs;
    this.runtime = runtime;
    this.running = false;
  }

  async refine({ brief, mode = 'natural', destination = 'chat', styling = 'auto', structure = 'auto', language = 'auto', source = 'speech' } = {}, onText = null, onStatus = null) {
    const input = String(brief || '').trim();
    if (!input) return '';
    if (!this.runtime?.isLoaded) {
      onStatus?.({ phase: 'ready', label: 'Transcript ready · local refinement skipped', progress: 1, nativeAndroid: true, skipped: true });
      return input;
    }

    const typed = source === 'typed';
    const systems = {
      natural: typed ? NATURAL_TEXT_SYSTEM : NATURAL_SYSTEM,
      prompt: PROMPT_SYSTEM,
      friendly: FRIENDLY_SYSTEM,
      blackriver: BLACKRIVER_SYSTEM,
      formal: FORMAL_SYSTEM,
      concise: CONCISE_SYSTEM,
    };
    const controls = [
      `Destination: ${destination === 'work' ? 'Work' : 'Chat'}`,
      styling && styling !== 'auto' ? `Requested style: ${styling}` : '',
      structure && structure !== 'auto' ? `Requested structure: ${structure}` : '',
      language && language !== 'auto' ? `Language hint: ${language}` : '',
    ].filter(Boolean).join('\n');
    const sourceLabel = mode === 'prompt' ? (typed ? 'Original user request' : 'Original spoken request') : (typed ? 'Original text' : 'Transcript');

    onStatus?.({ phase: 'refining', label: modeLabel(mode, typed), progress: null, nativeAndroid: true });
    this.running = true;
    let visible = '';
    try {
      await this.runtime.chat({
        messages: [
          { role: 'system', content: systems[mode] || systems.natural },
          { role: 'user', content: `${controls ? `${controls}\n\n` : ''}${sourceLabel}:\n${input}` },
        ],
        sampling: {
          temperature: mode === 'prompt' ? 0.22 : 0.15,
          top_p: 0.9,
          top_k: 20,
          min_p: 0,
          max_tokens: tokenBudget(input, mode),
        },
      }, (chunk) => {
        const delta = chunk?.choices?.[0]?.delta?.content || '';
        if (!delta) return;
        visible += delta;
        onText?.(visible, delta, chunk);
      });
      const result = visible.trim();
      if (!result) throw new Error('The Android local model returned an empty refinement.');
      return result;
    } finally {
      this.running = false;
    }
  }

  stop() {
    if (this.running) this.runtime?.stop?.();
    this.running = false;
  }

  async release({ reason = 'manual' } = {}) {
    // This adapter shares the main native model. Releasing the refiner must never
    // unload that model; it only clears an in-flight refinement if one exists.
    if (this.running) this.stop();
    return reason;
  }
}
