function core() {
  return typeof window !== 'undefined' ? window.blackriverNative : null;
}

export function nativeAvailable() {
  return !!core()?.available;
}

export function nativeCore() { return core(); }

function headersToObject(headers) {
  if (!headers) return {};
  if (headers instanceof Headers) return Object.fromEntries(headers.entries());
  if (Array.isArray(headers)) return Object.fromEntries(headers);
  return { ...headers };
}

export async function nativeFetch(url, init = {}, { credentialId = '' } = {}) {
  const bridge = core();
  if (!bridge?.available) return fetch(url, init);

  const signal = init.signal;
  let transport = null;
  let settled = false;
  let streamController = null;
  const stream = new ReadableStream({
    start(controller) { streamController = controller; },
    cancel() { transport?.cancel?.(); },
  });

  const responsePromise = new Promise((resolve, reject) => {
    const cleanupAbort = () => signal?.removeEventListener?.('abort', onAbort);
    const onAbort = () => {
      transport?.cancel?.();
      if (!settled) reject(new DOMException('The operation was aborted.', 'AbortError'));
      else streamController?.error(new DOMException('The operation was aborted.', 'AbortError'));
    };
    if (signal?.aborted) return onAbort();
    signal?.addEventListener?.('abort', onAbort, { once: true });

    transport = bridge.streamRequest({
      url: String(url),
      method: init.method || 'GET',
      headers: headersToObject(init.headers),
      body: typeof init.body === 'string' ? init.body : init.body == null ? null : String(init.body),
      credentialId: String(credentialId || ''),
    }, (event) => {
      if (!event) return;
      if (event.type === 'meta') {
        settled = true;
        resolve(new Response(stream, {
          status: Number(event.status || 0),
          statusText: String(event.statusText || ''),
          headers: event.headers || {},
        }));
      } else if (event.type === 'chunk') {
        streamController?.enqueue(new Uint8Array(event.data || []));
      } else if (event.type === 'end') {
        cleanupAbort();
        streamController?.close();
        transport?.dispose?.();
      } else if (event.type === 'error') {
        cleanupAbort();
        const error = event.name === 'AbortError'
          ? new DOMException(event.message || 'The operation was aborted.', 'AbortError')
          : new Error(event.message || 'Native provider request failed.');
        if (!settled) reject(error);
        else streamController?.error(error);
        transport?.dispose?.();
      }
    });
  });

  return responsePromise;
}

export async function saveNativeStateBackup(payload = {}) { return core()?.saveStateBackup?.(payload) || null; }
export async function loadNativeStateBackup() { return core()?.loadStateBackup?.() || null; }
