const STORAGE_KEY = 'blackriver.providers.v1';
const SESSION_KEY_PREFIX = 'blackriver.provider.secret.';

function uid() {
  return `provider_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function isRetiredNvidia(value = {}) {
  const text = typeof value === 'string' ? value : `${value.flavor || ''} ${value.name || ''} ${value.baseUrl || ''}`;
  return /(?:^|\b)nvidia(?:\b|\s)|integrate\.api\.nvidia\.com/i.test(String(text || ''));
}

function sanitizeBaseUrl(value = '') {
  let url = String(value || '').trim().replace(/\/+$/, '');
  if (!url) return '';
  // Store the server root. Users may paste either http://host:port or .../v1.
  if (/\/v1$/i.test(url)) url = url.slice(0, -3);
  return url;
}

function inferFlavor(value = {}) {
  if (['llama.cpp', 'ollama'].includes(value.flavor)) return value.flavor;
  const name = String(value.name || '');
  if (/llama\.?cpp/i.test(name)) return 'llama.cpp';
  if (/^ollama(?:\s|$)/i.test(name.trim())) return 'ollama';
  try {
    const url = new URL(value.baseUrl || '');
    const host = url.hostname.toLowerCase();
    if (host === 'ollama.com') return 'ollama';
    if (url.port === '11434' && ['127.0.0.1', 'localhost', '::1'].includes(host)) return 'ollama';
  } catch {}
  return '';
}

function normalizeProvider(value = {}) {
  return {
    id: value.id || uid(),
    type: 'openai-compatible',
    // Explicit flavor keeps llama.cpp behavior reliable even when the server is
    // on a LAN hostname/IP instead of localhost. Generic providers stay blank.
    flavor: inferFlavor(value),
    name: String(value.name || 'OpenAI-compatible API').trim() || 'OpenAI-compatible API',
    baseUrl: sanitizeBaseUrl(value.baseUrl),
    transport: ['direct', 'relay', 'auto'].includes(value.transport) ? value.transport : (() => {
      const flavor = inferFlavor(value);
      if (flavor === 'ollama') {
        try { return new URL(value.baseUrl || '').hostname.toLowerCase() === 'ollama.com' ? 'auto' : 'direct'; }
        catch { return 'direct'; }
      }
      return 'direct';
    })(),
    apiKey: value.rememberKey ? String(value.apiKey || '') : '',
    rememberKey: !!value.rememberKey,
    credentialId: String(value.credentialId || ''),
    authMode: String(value.authMode || ''),
    modelIds: Array.isArray(value.modelIds) ? [...new Set(value.modelIds.filter(Boolean).map(String))] : [],
    lastModelId: String(value.lastModelId || ''),
    updatedAt: Number(value.updatedAt || Date.now()),
  };
}

export class ProviderStore extends EventTarget {
  constructor() {
    super();
    this.providers = [];
    this.retiredCredentialIds = [];
    this.selection = { kind: 'wllama' };
    this.load();
  }

  load() {
    try {
      const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
      const rawProviders = Array.isArray(parsed.providers) ? parsed.providers : [];
      this.retiredCredentialIds = rawProviders.filter(isRetiredNvidia).map((item) => String(item.credentialId || '')).filter(Boolean);
      this.providers = rawProviders.filter((item) => !isRetiredNvidia(item)).map(normalizeProvider);
      if (parsed.selection?.kind === 'api' && this.providers.some((p) => p.id === parsed.selection.providerId)) {
        this.selection = {
          kind: 'api',
          providerId: parsed.selection.providerId,
          modelId: String(parsed.selection.modelId || ''),
        };
      }
      else if (parsed.selection?.kind === 'codex' && parsed.selection?.modelId) {
        this.selection = { kind: 'codex', modelId: String(parsed.selection.modelId || '') };
      }
      if (rawProviders.some(isRetiredNvidia)) {
        const persistProviders = this.providers.map((p) => ({ ...p, apiKey: p.credentialId ? '' : (p.rememberKey ? p.apiKey : '') }));
        localStorage.setItem(STORAGE_KEY, JSON.stringify({ providers: persistProviders, selection: this.selection }));
      }
    } catch {
      this.providers = [];
      this.retiredCredentialIds = [];
      this.selection = { kind: 'wllama' };
    }
  }

  takeRetiredCredentialIds() {
    const ids = [...new Set(this.retiredCredentialIds.filter(Boolean))];
    this.retiredCredentialIds = [];
    return ids;
  }

  save() {
    const persistProviders = this.providers.map((p) => ({
      ...p,
      apiKey: p.credentialId ? '' : (p.rememberKey ? this.getSecret(p.id) : ''),
    }));
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ providers: persistProviders, selection: this.selection }));
    this.dispatchEvent(new CustomEvent('change', { detail: { providers: this.providers, selection: this.selection } }));
  }

  list() {
    return this.providers.map((p) => ({ ...p, apiKey: this.getSecret(p.id) }));
  }

  get(id) {
    const p = this.providers.find((entry) => entry.id === id);
    return p ? { ...p, apiKey: this.getSecret(id) } : null;
  }

  getSecret(id) {
    const p = this.providers.find((entry) => entry.id === id);
    if (!p) return '';
    if (p.credentialId) return '';
    if (p.rememberKey && p.apiKey) return p.apiKey;
    try { return sessionStorage.getItem(`${SESSION_KEY_PREFIX}${id}`) || ''; }
    catch { return ''; }
  }

  setSecret(id, apiKey = '', rememberKey = false) {
    const p = this.providers.find((entry) => entry.id === id);
    if (!p) return;
    p.rememberKey = !!rememberKey;
    p.apiKey = rememberKey ? String(apiKey || '') : '';
    try {
      const key = `${SESSION_KEY_PREFIX}${id}`;
      if (rememberKey) sessionStorage.removeItem(key);
      else if (apiKey) sessionStorage.setItem(key, String(apiKey));
      else sessionStorage.removeItem(key);
    } catch {}
  }

  upsert(input = {}) {
    if (isRetiredNvidia(input)) throw new Error('NVIDIA NIM is temporarily disabled in this BlackRiver release.');
    const normalizedBase = sanitizeBaseUrl(input.baseUrl);
    const existing = input.id
      ? this.providers.find((p) => p.id === input.id)
      : this.providers.find((p) => normalizedBase && p.baseUrl === normalizedBase);
    const merged = normalizeProvider({ ...(existing || {}), ...input, baseUrl: normalizedBase, id: existing?.id || input.id || uid(), updatedAt: Date.now() });
    const apiKey = String(input.apiKey ?? this.getSecret(merged.id) ?? '');
    if (existing) Object.assign(existing, merged);
    else this.providers.push(merged);
    this.setSecret(merged.id, apiKey, merged.rememberKey);
    this.save();
    return this.get(merged.id);
  }

  updateModels(id, modelIds = [], lastModelId = undefined) {
    const p = this.providers.find((entry) => entry.id === id);
    if (!p) return;
    p.modelIds = [...new Set((modelIds || []).filter(Boolean).map(String))];
    if (lastModelId !== undefined) p.lastModelId = String(lastModelId || '');
    if (!p.lastModelId || !p.modelIds.includes(p.lastModelId)) p.lastModelId = p.modelIds[0] || '';
    if (this.selection.kind === 'api' && this.selection.providerId === id && !p.modelIds.includes(this.selection.modelId)) {
      this.selection = { kind: 'api', providerId: id, modelId: p.lastModelId };
    }
    p.updatedAt = Date.now();
    this.save();
  }

  remove(id) {
    this.providers = this.providers.filter((p) => p.id !== id);
    try { sessionStorage.removeItem(`${SESSION_KEY_PREFIX}${id}`); } catch {}
    if (this.selection.kind === 'api' && this.selection.providerId === id) this.selection = { kind: 'wllama' };
    this.save();
  }

  selectWllama() {
    if (this.selection.kind === 'wllama') return;
    this.selection = { kind: 'wllama' };
    this.save();
  }

  selectCodex(modelId) {
    const next = String(modelId || '').trim();
    if (!next) throw new Error('Choose a ChatGPT / Codex model first.');
    if (this.selection.kind === 'codex' && this.selection.modelId === next) return;
    this.selection = { kind: 'codex', modelId: next };
    this.save();
  }

  selectApi(providerId, modelId) {
    const p = this.providers.find((entry) => entry.id === providerId);
    if (!p) throw new Error('Provider not found.');
    p.lastModelId = String(modelId || p.lastModelId || p.modelIds[0] || '');
    if (this.selection.kind === 'api' && this.selection.providerId === providerId && this.selection.modelId === p.lastModelId) return;
    this.selection = { kind: 'api', providerId, modelId: p.lastModelId };
    this.save();
  }
}

export { sanitizeBaseUrl };
